-- Remaining 21 approved launch courses: unpublished drafts. Requires existing account/training schema.
-- Does not publish, release, assign, reset progress, or change existing course content.
begin;
do $courseimport$
declare
 payload jsonb := $coursedata${"course": {"id": "00d22f7c-a06f-52b5-84d2-45569901ca4b", "slug": "cs-101-customer-service-fundamentals", "version": 1, "title": "Customer Service Fundamentals", "description": "Learn how to welcome customers, understand their needs, offer honest help, handle concerns, and end interactions well.", "category": "Customer Experience & Sales", "passing_percent": 80}, "lessons": [{"id": "38b34fc6-1693-5dd8-9411-ead26fe93c64", "position": 1, "title": "Make Every Customer Feel Welcome", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Customers may feel unsure when they enter a hardware store. A friendly greeting helps them feel comfortable. It also shows that help is available."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Start with a greeting"}, {"type": "paragraph", "text": "Look up when a customer approaches. Use a friendly tone. Say hello and offer help. Give the customer space if they prefer to browse."}, {"type": "heading", "text": "Respect different shopping styles"}, {"type": "paragraph", "text": "Some customers know the exact item they need. Others need time to think. Do not assume that every customer wants a long conversation."}, {"type": "heading", "text": "Stay available"}, {"type": "paragraph", "text": "A customer may decline help at first. Let them know where to find you. Check back when it makes sense. Do not follow them around the store."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer enters and looks at the aisle signs. You say, “Welcome! Can I help you find something?” The customer says they want to look around. You reply, “Of course. I’ll be near the front if you need anything.”"}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Greet customers in a friendly voice."}, {"type": "bullet", "text": "Offer help with a simple question."}, {"type": "bullet", "text": "Respect a customer who wants to browse."}, {"type": "bullet", "text": "Stay easy to find."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Ignoring a customer because you are stocking shelves."}, {"type": "bullet", "text": "Asking too many questions after a customer declines help."}, {"type": "bullet", "text": "Assuming a customer knows where products are located."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a coworker or manager if you cannot leave an assigned station or if customers need help in another area."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "A greeting sets the tone."}, {"type": "bullet", "text": "Offer help without pressure."}, {"type": "bullet", "text": "Respect the customer’s pace."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Question ID: CS-101-L01-P01"}, {"type": "paragraph", "text": "Question: A customer says, “I’m just looking.” What should you do?"}, {"type": "paragraph", "text": "A. Follow them and explain every aisle."}, {"type": "paragraph", "text": "B. Say, “No problem. Let me know if you need help.”"}, {"type": "paragraph", "text": "C. Walk away without speaking."}, {"type": "paragraph", "text": "D. Ask why they came to the store."}, {"type": "paragraph", "text": "Answer: B"}, {"type": "paragraph", "text": "Explanation: Respect the customer’s choice. Stay available without pressuring them."}, {"type": "heading", "text": "Optional practice"}, {"type": "paragraph", "text": "None assigned. The lesson question above is unscored."}]}, {"id": "2d6de14b-d2c1-5f20-b679-171aecdf3081", "position": 2, "title": "Listen Before You Recommend", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Customers often describe a problem instead of naming a product. Good questions help employees understand the job before suggesting an item."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Learn the goal"}, {"type": "paragraph", "text": "Start with the project. Ask, “What are you working on?” Let the customer finish their explanation."}, {"type": "heading", "text": "Ask one useful question at a time"}, {"type": "paragraph", "text": "Ask about the material, location, or existing part. Use words the customer understands. Avoid a long list of questions."}, {"type": "heading", "text": "Repeat the need"}, {"type": "paragraph", "text": "Summarize what you heard. You might say, “You need a way to hang a picture on a plaster wall. Is that right?” This gives the customer a chance to correct you."}, {"type": "heading", "text": "Avoid guessing"}, {"type": "paragraph", "text": "Similar products may serve different purposes. Check labels and instructions. Ask for help when product suitability is uncertain."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer asks for “the glue for outside.” You ask what they are joining and where the repair will be used. The customer says they need to repair a wooden planter. You check product labels before suggesting options."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Ask about the project first."}, {"type": "bullet", "text": "Listen without interrupting."}, {"type": "bullet", "text": "Confirm your understanding."}, {"type": "bullet", "text": "Verify product details before recommending an item."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Recommending the first familiar product."}, {"type": "bullet", "text": "Using technical words without explaining them."}, {"type": "bullet", "text": "Treating a customer’s first description as complete."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a knowledgeable coworker or refer to official product instructions when the application is unclear. Refer specialized or regulated work to a qualified professional."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Understand the job before naming a product."}, {"type": "bullet", "text": "Ask clear questions."}, {"type": "bullet", "text": "Confirm what you heard."}, {"type": "bullet", "text": "Never guess about suitability."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Question ID: CS-101-L02-P01"}, {"type": "paragraph", "text": "Question: A customer asks for “a screw for my deck.” What is the best first step?"}, {"type": "paragraph", "text": "A. Hand them any wood screw."}, {"type": "paragraph", "text": "B. Ask what material they are fastening and where it will be used."}, {"type": "paragraph", "text": "C. Tell them all screws are alike."}, {"type": "paragraph", "text": "D. Send them to checkout."}, {"type": "paragraph", "text": "Answer: B"}, {"type": "paragraph", "text": "Explanation: The material and location help narrow the choice. Do not recommend a fastener before learning the project details."}, {"type": "heading", "text": "Optional practice"}, {"type": "paragraph", "text": "None assigned. The lesson question above is unscored."}]}, {"id": "863ba92b-b012-551d-9511-5e2378d78597", "position": 3, "title": "Give Clear and Honest Help", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Customers need information they can use. Clear words and honest answers build confidence. Guessing can cause mistakes and frustration."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Use everyday language"}, {"type": "paragraph", "text": "Name the aisle or product group. Point out a label or feature. Explain unfamiliar terms in simple words."}, {"type": "heading", "text": "Be honest about limits"}, {"type": "paragraph", "text": "You do not need to know every answer. Say, “I want to check that before I recommend it.” Then use an approved resource or ask a coworker."}, {"type": "heading", "text": "Make a useful handoff"}, {"type": "paragraph", "text": "Explain the customer’s question to the next employee. Stay with the customer when practical. Do not send them from person to person without context."}, {"type": "heading", "text": "Avoid promises you cannot confirm"}, {"type": "paragraph", "text": "Check inventory, service availability, and delivery details before making a promise. Store systems and procedures vary."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer wants to know whether a particular light bulb works with a dimmer. You check the package. The label is unclear. You say, “Let me verify that before you buy it.” You ask a trained coworker to help."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Use short, clear explanations."}, {"type": "bullet", "text": "Show where to find product information."}, {"type": "bullet", "text": "Say when you need to verify an answer."}, {"type": "bullet", "text": "Explain the customer’s need during a handoff."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Guessing to sound confident."}, {"type": "bullet", "text": "Giving directions that are too vague."}, {"type": "bullet", "text": "Promising a product or service without checking."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Consult product labels, manufacturer instructions, an experienced coworker, or a manager. Do not give instructions for work that requires a qualified professional."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Clarity matters more than jargon."}, {"type": "bullet", "text": "Honesty builds trust."}, {"type": "bullet", "text": "A good handoff saves time."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Question ID: CS-101-L03-P01"}, {"type": "paragraph", "text": "Question: You cannot confirm whether a bulb works with a dimmer. What should you say?"}, {"type": "paragraph", "text": "A. “It probably works.”"}, {"type": "paragraph", "text": "B. “That is not my problem.”"}, {"type": "paragraph", "text": "C. “Let me check the product information and ask someone who knows.”"}, {"type": "paragraph", "text": "D. “All LED bulbs work with dimmers.”"}, {"type": "paragraph", "text": "Answer: C"}, {"type": "paragraph", "text": "Explanation: Verify compatibility instead of guessing. The package and manufacturer information can help."}, {"type": "heading", "text": "Optional practice"}, {"type": "paragraph", "text": "None assigned. The lesson question above is unscored."}]}, {"id": "37c47c5d-f52e-58c5-9e6d-f1581411dc99", "position": 4, "title": "Handle Frustration with Respect", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Customers sometimes face delays, missing products, or confusing information. A calm response can keep a problem from getting worse."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Listen first"}, {"type": "paragraph", "text": "Let the customer explain the concern. Keep your voice steady. Avoid interrupting or arguing."}, {"type": "heading", "text": "Acknowledge the problem"}, {"type": "paragraph", "text": "Show that you understand the inconvenience. You might say, “I can see why that is frustrating.” Do not promise a result before you know what is possible."}, {"type": "heading", "text": "Offer a clear next step"}, {"type": "paragraph", "text": "Check the facts. Explain the options allowed by store policy. Ask a manager to help with decisions outside your authority."}, {"type": "heading", "text": "Protect everyone’s safety"}, {"type": "paragraph", "text": "Do not accept threats or abusive behavior as part of the job. Follow store procedures. Get a manager or emergency help when needed."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer says a special-order item has not arrived. You listen and acknowledge the delay. You check the order status through the approved process. You explain what you can confirm and ask a manager to assist with options."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Stay calm and listen."}, {"type": "bullet", "text": "Acknowledge the concern without blame."}, {"type": "bullet", "text": "Check facts before offering a solution."}, {"type": "bullet", "text": "Escalate issues beyond your authority."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Arguing about who caused the problem."}, {"type": "bullet", "text": "Promising a refund or delivery date without approval."}, {"type": "bullet", "text": "Taking an angry comment personally."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Involve a manager for policy exceptions, refund disputes, repeated complaints, threats, or unsafe behavior. Follow the store’s incident and emergency procedures."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Listen before responding."}, {"type": "bullet", "text": "Acknowledge frustration."}, {"type": "bullet", "text": "Offer only confirmed options."}, {"type": "bullet", "text": "Get help when needed."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Question ID: CS-101-L04-P01"}, {"type": "paragraph", "text": "Question: A customer is upset about a delayed order. What is the best first response?"}, {"type": "paragraph", "text": "A. Tell them delays happen everywhere."}, {"type": "paragraph", "text": "B. Listen, acknowledge the concern, and check the order status."}, {"type": "paragraph", "text": "C. Promise the order will arrive tomorrow."}, {"type": "paragraph", "text": "D. Tell them to contact the supplier directly."}, {"type": "paragraph", "text": "Answer: B"}, {"type": "paragraph", "text": "Explanation: Listening and checking facts create a useful next step. Do not promise dates that are not confirmed."}, {"type": "heading", "text": "Optional practice"}, {"type": "paragraph", "text": "None assigned. The lesson question above is unscored."}]}, {"id": "f02829db-f96a-58b6-ab36-681db7f135e8", "position": 5, "title": "Finish the Interaction Well", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "A helpful conversation can still end poorly if the customer does not know what happens next. A clear close reduces confusion."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Confirm the result"}, {"type": "paragraph", "text": "Ask whether the customer found what they need. If another person will help, explain who and where."}, {"type": "heading", "text": "Be clear about follow-up"}, {"type": "paragraph", "text": "For orders or services, share only verified details. Explain how the customer will receive updates under the store’s process."}, {"type": "heading", "text": "Offer one final opportunity"}, {"type": "paragraph", "text": "Ask, “Is there anything else I can help you find?” Do not pressure the customer to buy more."}, {"type": "heading", "text": "Thank the customer"}, {"type": "paragraph", "text": "End with a friendly thank-you. A simple close shows respect for their time."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "You help a customer locate a paint roller. They also need a tray. You show them the tray options. You ask whether they need anything else. The customer says no. You thank them and point out the checkout area."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Confirm the customer’s next step."}, {"type": "bullet", "text": "Check whether more help is needed."}, {"type": "bullet", "text": "Avoid unverified promises."}, {"type": "bullet", "text": "Thank the customer."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Leaving without saying what happens next."}, {"type": "bullet", "text": "Assuming the customer has everything they need."}, {"type": "bullet", "text": "Using a sales pitch when the customer is ready to leave."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a coworker or manager when an order, service, or complaint still needs follow-up. Confirm who owns the next step."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Make the next step clear."}, {"type": "bullet", "text": "Offer more help without pressure."}, {"type": "bullet", "text": "End with a thank-you."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Question ID: CS-101-L05-P01"}, {"type": "paragraph", "text": "Question: A coworker will finish helping your customer. What should you do before leaving?"}, {"type": "paragraph", "text": "A. Walk away as soon as the coworker arrives."}, {"type": "paragraph", "text": "B. Tell the customer to explain everything again."}, {"type": "paragraph", "text": "C. Brief the coworker and confirm the customer knows who will help."}, {"type": "paragraph", "text": "D. Promise the coworker can solve every problem."}, {"type": "paragraph", "text": "Answer: C"}, {"type": "paragraph", "text": "Explanation: A clear handoff helps the customer avoid repeating the full story. Confirm who will take over."}, {"type": "heading", "text": "Optional practice"}, {"type": "paragraph", "text": "None assigned. The lesson question above is unscored."}]}], "questions": [{"id": "92de1f24-d044-5a55-8de3-144fdfa663f5", "position": 1, "prompt": "A customer enters and says they want to browse. What is the best response?", "options": ["Explain every department before they start.", "Respect their choice and tell them where to find help.", "Ignore them for the rest of the visit.", "Ask them to name a product before entering."], "correct_option": 1, "explanation": "A friendly greeting and a low-pressure offer of help respect the customer’s choice."}, {"id": "f23979f7-a3a0-5174-9091-5f8cf2c680f2", "position": 2, "prompt": "A customer asks for tape to repair something outdoors. What should you do first?", "options": ["Recommend the first tape on the shelf.", "Tell them all tape works outdoors.", "Ask what material they need to repair and what conditions it faces.", "Send them to the paint department without asking questions."], "correct_option": 2, "explanation": "Ask about the material and conditions. These details help narrow the options. Do not guess based on a broad request."}, {"id": "67232f80-4839-57e3-b3cb-81372f73b647", "position": 3, "prompt": "You are unsure whether a replacement part fits a customer’s tool. What is the best response?", "options": ["Say it fits because it looks similar.", "Check the model information and approved product resources before answering.", "Tell the customer to buy it and try it.", "Avoid the customer until another employee arrives."], "correct_option": 1, "explanation": "Verify model and product information before recommending a replacement. Appearance alone does not confirm compatibility."}, {"id": "67692e97-7788-5415-872f-46ff1b3b55bf", "position": 4, "prompt": "A customer is upset about a return decision. You do not have authority to change it. What should you do?", "options": ["Argue until they agree with you.", "Promise an exception without approval.", "Listen calmly, explain what you can confirm, and involve a manager.", "Walk away without telling anyone."], "correct_option": 2, "explanation": "Listen and explain confirmed information. A manager should handle decisions outside your authority."}, {"id": "56d09b36-d2db-5662-b83a-13a6a6d4af36", "position": 5, "prompt": "You have helped a customer find the right aisle. What is a good way to finish?", "options": ["Leave immediately without checking.", "Ask if they need anything else and thank them.", "Insist that they buy another item.", "Promise a discount for their visit."], "correct_option": 1, "explanation": "A short check-in and thank-you give the interaction a clear, respectful ending."}], "catalog": {"course_code": "CS-101", "skill_level": "foundations", "topics": ["Customer Service"], "keywords": ["Make Every Customer Feel Welcome", "Listen Before You Recommend", "Give Clear and Honest Help", "Handle Frustration with Respect", "Finish the Interaction Well", "Why this matters", "Lesson content", "Start with a greeting", "Respect different shopping styles", "Stay available", "Hardware-store example", "What to say or do", "Common mistakes", "When to ask for help", "Key takeaways", "Unscored lesson practice", "Optional practice", "Learn the goal", "Ask one useful question at a time", "Repeat the need", "Avoid guessing", "Use everyday language", "Be honest about limits", "Make a useful handoff", "Avoid promises you cannot confirm", "Listen first", "Acknowledge the problem", "Offer a clear next step", "Protect everyone’s safety", "Confirm the result", "Be clear about follow-up", "Offer one final opportunity", "Thank the customer", "CS-101-", "ID", "L01-P01", "L02-P01", "L03-P01", "L04-P01", "L05-P01", "LED"], "learning_paths": ["New Retail Employee"]}}$coursedata$::jsonb;
 c jsonb; l jsonb; q jsonb; target uuid;
begin
 c := payload->'course'; target := (c->>'id')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('coltrain-course:' || target::text, 0));
 if exists(select 1 from public.training_courses where id=target) then
  if not exists(select 1 from public.training_courses t where t.id=target
   and t.slug=c->>'slug' and t.version=(c->>'version')::integer
   and t.title=c->>'title' and t.description=c->>'description'
   and t.category=c->>'category' and t.passing_percent=(c->>'passing_percent')::integer
   and t.owner_organization_id is null) then
   raise exception 'CS-101 course differs; create a new version rather than overwrite';
  end if;
  if (select count(*) from public.training_lessons where course_id=target) <> jsonb_array_length(payload->'lessons')
   or (select count(*) from public.training_questions where course_id=target) <> jsonb_array_length(payload->'questions') then
   raise exception 'CS-101 content differs; draft import was not changed';
  end if;
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   if not exists(select 1 from public.training_lessons t where t.id=(l->>'id')::uuid
    and t.course_id=target and t.position=(l->>'position')::integer
    and t.title=l->>'title' and t.body=l->'body') then
    raise exception 'CS-101 lesson differs; draft import was not changed';
   end if;
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   if not exists(select 1 from public.training_questions t join private.training_answer_keys k on k.question_id=t.id
    where t.id=(q->>'id')::uuid and t.course_id=target and t.position=(q->>'position')::integer
    and t.prompt=q->>'prompt' and t.options=q->'options'
    and k.correct_option=(q->>'correct_option')::integer and k.explanation=q->>'explanation') then
    raise exception 'CS-101 question differs; draft import was not changed';
   end if;
  end loop;
 else
  insert into public.training_courses(id,slug,version,title,description,category,passing_percent,published)
   values(target,c->>'slug',(c->>'version')::integer,c->>'title',c->>'description',c->>'category',(c->>'passing_percent')::integer,false);
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   insert into public.training_lessons(id,course_id,position,title,body)
    values((l->>'id')::uuid,target,(l->>'position')::integer,l->>'title',l->'body');
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   insert into public.training_questions(id,course_id,position,prompt,options)
    values((q->>'id')::uuid,target,(q->>'position')::integer,q->>'prompt',q->'options');
   insert into private.training_answer_keys(question_id,correct_option,explanation)
    values((q->>'id')::uuid,(q->>'correct_option')::integer,q->>'explanation');
  end loop;
 end if;
 -- Optional metadata: imports remain compatible before the catalog migration.
 if to_regclass('public.training_course_catalog') is not null then
  insert into public.training_course_catalog(course_id,course_code,skill_level,topics,keywords,learning_paths)
  values(target,payload->'catalog'->>'course_code',payload->'catalog'->>'skill_level',
   array(select jsonb_array_elements_text(payload->'catalog'->'topics')),
   array(select jsonb_array_elements_text(payload->'catalog'->'keywords')),
   array(select jsonb_array_elements_text(payload->'catalog'->'learning_paths')))
  on conflict(course_id) do nothing;
 end if;
end;
$courseimport$;
do $courseimport$
declare
 payload jsonb := $coursedata${"course": {"id": "22b7ea6f-154f-564a-ae6a-24dcc1c295b5", "slug": "cs-102-selling-skills-for-hardware-retail", "version": 1, "title": "Selling Skills for Hardware Retail", "description": "Learn how to understand a customer’s project, compare suitable products, and suggest useful supplies without pressure.", "category": "Customer Experience & Sales", "passing_percent": 80}, "lessons": [{"id": "0650b7cf-5534-5c23-8f88-f19d58830a7d", "position": 1, "title": "Discover the Customer’s Project", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "A customer may name a product before explaining the job. A few questions can prevent a poor match."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Start with the project"}, {"type": "paragraph", "text": "Ask what the customer wants to accomplish. Learn whether this is a repair, replacement, or new project. Ask what they have already tried."}, {"type": "heading", "text": "Collect the useful details"}, {"type": "paragraph", "text": "Ask about the material, size, location, and conditions. Ask whether the customer has a photo, old part, or instructions. Only collect details that matter to the choice."}, {"type": "heading", "text": "Confirm what you heard"}, {"type": "paragraph", "text": "Repeat the main need in plain language. For example: “You need a way to fasten this gate latch to a wood post. Is that right?”"}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer asks for screws. You ask what they are fastening. They say a gate latch to a wooden post outdoors. You now know the job and the location. You still need the latch instructions and size details before suggesting a fastener."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Ask: “What are you working on?”"}, {"type": "bullet", "text": "Ask: “Where will you use it?”"}, {"type": "bullet", "text": "Ask: “Do you have the old part or instructions?”"}, {"type": "bullet", "text": "Repeat the project goal before moving to products."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Starting with the most expensive product."}, {"type": "bullet", "text": "Assuming a familiar item fits every project."}, {"type": "bullet", "text": "Asking many questions without explaining why."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a knowledgeable coworker when the customer cannot describe the job clearly. Refer to product instructions for load, electrical, structural, or other safety-sensitive applications."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Start with the customer’s goal."}, {"type": "bullet", "text": "Ask only useful questions."}, {"type": "bullet", "text": "Confirm the project before choosing products."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Practice ID: CS-102-P01"}, {"type": "paragraph", "text": "Question: A customer asks for caulk. What should you ask first?"}, {"type": "bullet", "text": "A. “Which brand costs the most?”"}, {"type": "bullet", "text": "B. “What surface or gap are you sealing?”"}, {"type": "bullet", "text": "C. “Do you want two tubes?”"}, {"type": "bullet", "text": "D. “Can you return tomorrow?”"}, {"type": "paragraph", "text": "Answer: B"}, {"type": "paragraph", "text": "Explanation: The surface and location help narrow the correct product. Price and quantity come later."}, {"type": "heading", "text": "Optional practice"}, {"type": "bullet", "text": "None."}]}, {"id": "02758851-d3f0-5be3-aca1-8b014318da79", "position": 2, "title": "Match Features to Customer Needs", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Customers do not always know why two similar products have different prices or uses."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Features and benefits"}, {"type": "paragraph", "text": "A feature is a product fact. A benefit explains why that fact matters to the customer. For example, a longer hose is a feature. Reaching a distant garden bed is the benefit."}, {"type": "heading", "text": "Compare only relevant details"}, {"type": "paragraph", "text": "Use the project to select comparison points. These may include dimensions, material, capacity, compatibility, maintenance, and price. Verify product claims on packaging or official instructions."}, {"type": "heading", "text": "Be clear about limits"}, {"type": "paragraph", "text": "Do not promise that a product will work in every situation. If you cannot confirm compatibility, say what you need to check."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer needs a hose for a garden bed far from the spigot. You compare two hose lengths. You explain the reach of each option. You also ask about storage and the path to the garden."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Say: “This option may fit your project because…”"}, {"type": "bullet", "text": "Point to a verified feature on the label."}, {"type": "bullet", "text": "Explain a benefit in everyday words."}, {"type": "bullet", "text": "Mention an important limitation."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Listing features without explaining them."}, {"type": "bullet", "text": "Calling one product “best” for everyone."}, {"type": "bullet", "text": "Making claims that are not on verified product information."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask for help when a product rating, compatibility requirement, warranty, or safety instruction is unclear. Use current manufacturer documentation."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Explain benefits, not just features."}, {"type": "bullet", "text": "Compare products using the project."}, {"type": "bullet", "text": "Verify claims before sharing them."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Practice ID: CS-102-P02"}, {"type": "paragraph", "text": "Question: A customer needs a hose to reach a distant garden bed. Which statement is most helpful?"}, {"type": "bullet", "text": "A. “This hose is popular.”"}, {"type": "bullet", "text": "B. “This hose is the most expensive.”"}, {"type": "bullet", "text": "C. “This longer hose may reach the bed. Let’s confirm the distance.”"}, {"type": "bullet", "text": "D. “All hoses work the same.”"}, {"type": "paragraph", "text": "Answer: C"}, {"type": "paragraph", "text": "Explanation: This answer connects a feature to the customer’s need. It also checks a missing detail."}, {"type": "heading", "text": "Optional practice"}, {"type": "bullet", "text": "None."}]}, {"id": "7d9e5cb1-ef3a-56c2-8fd3-98a54dcd88a7", "position": 3, "title": "Build a Complete Project List", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "A customer may get home and discover a missing supply. Helpful selling reduces extra trips."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Think through the job"}, {"type": "paragraph", "text": "Ask what tools and materials the customer already has. Review the main steps of the project. Check instructions for required accessories and preparation."}, {"type": "heading", "text": "Offer relevant items"}, {"type": "paragraph", "text": "A paint project may also need tape, a drop cloth, a tray, and a suitable roller. These are examples, not a fixed shopping list. Match items to the surface and product instructions."}, {"type": "heading", "text": "Respect the customer’s choice"}, {"type": "paragraph", "text": "Explain why each item may help. Let the customer decide. Do not add products without permission."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer buys paint for a bedroom. You ask whether they have a roller, tray, and supplies to protect the floor. They have a roller but need a tray. You show an appropriate option and explain its use."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Ask: “What supplies do you already have?”"}, {"type": "bullet", "text": "Say: “You may also need this for the next step.”"}, {"type": "bullet", "text": "Explain the reason for each suggestion."}, {"type": "bullet", "text": "Accept a “no” without pressure."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Adding items to raise the sale total."}, {"type": "bullet", "text": "Assuming every customer needs a full kit."}, {"type": "bullet", "text": "Forgetting to check product instructions."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a department specialist about product compatibility or application requirements. Do not give unverified safety or installation advice."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Help customers avoid missing supplies."}, {"type": "bullet", "text": "Explain each companion item."}, {"type": "bullet", "text": "Respect customer decisions."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Practice ID: CS-102-P03"}, {"type": "paragraph", "text": "Question: A customer buys paint and says they already have brushes. What is the best next step?"}, {"type": "bullet", "text": "A. Add new brushes to the sale."}, {"type": "bullet", "text": "B. Ask what other supplies they have and suggest only relevant missing items."}, {"type": "bullet", "text": "C. Tell them their brushes are probably wrong."}, {"type": "bullet", "text": "D. Avoid discussing any other supplies."}, {"type": "paragraph", "text": "Answer: B"}, {"type": "paragraph", "text": "Explanation: A complete project list starts with what the customer owns. It does not require pressure."}, {"type": "heading", "text": "Optional practice"}, {"type": "bullet", "text": "None."}]}, {"id": "8a217afc-eba1-5091-97f7-433492356d80", "position": 4, "title": "Discuss Price and Value Clearly", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Customers often weigh price against durability, convenience, and project needs."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Understand the budget"}, {"type": "paragraph", "text": "Ask whether the customer has a price range. Do not assume the least expensive option is the best fit."}, {"type": "heading", "text": "Compare total value"}, {"type": "paragraph", "text": "Discuss verified differences that matter to the project. A lower price may be important. So may product life, quantity, or required accessories. Avoid unsupported claims about savings."}, {"type": "heading", "text": "Respond without arguing"}, {"type": "paragraph", "text": "Acknowledge the concern. Offer a clear comparison. Give the customer room to choose."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer says a drill costs more than expected. You ask how often they plan to use it. You compare two suitable models using verified specifications. You explain the differences and let them choose."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Say: “What price range works for you?”"}, {"type": "bullet", "text": "Say: “Here are the differences that matter for your project.”"}, {"type": "bullet", "text": "Offer a suitable lower-cost option when available."}, {"type": "bullet", "text": "Do not criticize a customer’s budget."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Treating a price concern as an objection to defeat."}, {"type": "bullet", "text": "Promising savings without evidence."}, {"type": "bullet", "text": "Assuming expensive always means better."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a manager about promotions, price adjustments, financing, or return policies. Never invent store terms or discounts."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Listen to price concerns."}, {"type": "bullet", "text": "Compare verified value."}, {"type": "bullet", "text": "Let the customer decide."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Practice ID: CS-102-P04"}, {"type": "paragraph", "text": "Question: A customer says a drill is too expensive. What should you do?"}, {"type": "bullet", "text": "A. Tell them they need the expensive one."}, {"type": "bullet", "text": "B. Offer an unapproved discount."}, {"type": "bullet", "text": "C. Ask about their use and budget. Compare suitable options."}, {"type": "bullet", "text": "D. End the conversation."}, {"type": "paragraph", "text": "Answer: C"}, {"type": "paragraph", "text": "Explanation: The goal is a suitable choice within the customer’s needs and budget."}, {"type": "heading", "text": "Optional practice"}, {"type": "bullet", "text": "None."}]}, {"id": "7193bd45-39ea-5314-a521-e39aeb87523a", "position": 5, "title": "Close the Sale with Confidence and Care", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "A good sale ends with a customer who understands the product and what happens next."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Confirm the choice"}, {"type": "paragraph", "text": "Summarize the product and the project need. Ask whether the customer has remaining questions."}, {"type": "heading", "text": "Check practical details"}, {"type": "paragraph", "text": "Confirm quantity, size, color, or compatibility as appropriate. Mention product instructions and important use limits. Do not invent return or warranty rules."}, {"type": "heading", "text": "End with a clear handoff"}, {"type": "paragraph", "text": "Direct the customer to checkout or the right service desk. Thank them. If a specialist must finish the consultation, introduce the customer and share what you learned."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer selects a garden hose. You confirm the length and connector type shown on the package. You ask if they need anything else. Then you guide them toward checkout."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Say: “Does this meet what you need for the project?”"}, {"type": "bullet", "text": "Confirm key details before checkout."}, {"type": "bullet", "text": "Ask: “Is there anything else you need?”"}, {"type": "bullet", "text": "Thank the customer without pressure."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Rushing the customer to checkout."}, {"type": "bullet", "text": "Making a final promise about unverified compatibility."}, {"type": "bullet", "text": "Leaving the customer without a next step."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask for help with unresolved product questions, unusual orders, or store policy. For high-risk applications, refer to manufacturer guidance or a qualified professional."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Confirm the product and need."}, {"type": "bullet", "text": "Check important details."}, {"type": "bullet", "text": "Close with respect and clarity."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Practice ID: CS-102-P05"}, {"type": "paragraph", "text": "Question: A customer has chosen a replacement part. What is the best way to finish?"}, {"type": "bullet", "text": "A. Promise it will fit without checking."}, {"type": "bullet", "text": "B. Confirm key details and ask about remaining questions."}, {"type": "bullet", "text": "C. Add an unrelated item to the purchase."}, {"type": "bullet", "text": "D. Leave without a handoff."}, {"type": "paragraph", "text": "Answer: B"}, {"type": "paragraph", "text": "Explanation: A final check can catch missing details and gives the customer a clear next step."}, {"type": "heading", "text": "Optional practice"}, {"type": "bullet", "text": "None."}]}], "questions": [{"id": "1e87f744-cdb9-59ae-bca1-12a04a84ef5c", "position": 1, "prompt": "A customer asks for an adhesive. Which first question best helps you make a useful recommendation?", "options": ["“Would you like the largest container?”", "“What materials are you joining, and where will you use it?”", "“Do you want our most expensive adhesive?”", "“Can you tell me the brand you always buy?”"], "correct_option": 1, "explanation": "The materials and location help identify the right category and instructions. Brand, size, and price do not establish suitability."}, {"id": "ad6fe8e1-ce9b-5ab9-b791-3fe7685018dc", "position": 2, "prompt": "A customer compares two extension cords for a project. What should you do?", "options": ["Recommend the longest one without questions.", "Say both cords are the same.", "Verify the intended use and the relevant product ratings before comparing options.", "Choose the cheapest cord regardless of specifications."], "correct_option": 2, "explanation": "Intended use and ratings matter. Do not guess about electrical product suitability."}, {"id": "db31b44a-ceea-53ad-ac02-3dc8d1ee9c72", "position": 3, "prompt": "A customer is buying a paint roller. Which approach supports a complete project sale?", "options": ["Ask about the surface and existing supplies. Suggest a suitable tray only if needed.", "Add a tray without asking.", "Insist on a full painting kit.", "Avoid mentioning any supplies."], "correct_option": 0, "explanation": "Relevant suggestions begin with the project and what the customer already owns. Unrequested additions and pressure are not appropriate."}, {"id": "2cee9e59-1d4b-5424-8f2d-d53e0a52266f", "position": 4, "prompt": "A customer says a product is above their budget. What is the best response?", "options": ["Tell them quality always costs more.", "Offer a discount without approval.", "Suggest they buy it anyway.", "Ask about their needs and compare suitable options within their budget."], "correct_option": 3, "explanation": "The customer’s needs and budget guide the comparison. Never promise discounts or pressure a purchase."}, {"id": "6b9a7f06-0a9f-5861-8270-eb577ba76cc4", "position": 5, "prompt": "A customer chooses a replacement garden hose connector. What should you do before checkout?", "options": ["Guarantee it fits every hose.", "Confirm the relevant size or connection details and ask about remaining questions.", "Add extra connectors without permission.", "End the interaction immediately."], "correct_option": 1, "explanation": "A final detail check helps prevent mistakes. Never guarantee universal compatibility."}], "catalog": {"course_code": "CS-102", "skill_level": "foundations", "topics": ["Selling Skills for Hardware Retail"], "keywords": ["Discover the Customer’s Project", "Match Features to Customer Needs", "Build a Complete Project List", "Discuss Price and Value Clearly", "Close the Sale with Confidence and Care", "Why this matters", "Lesson content", "Start with the project", "Collect the useful details", "Confirm what you heard", "Hardware-store example", "What to say or do", "Common mistakes", "When to ask for help", "Key takeaways", "Unscored lesson practice", "Optional practice", "Features and benefits", "Compare only relevant details", "Be clear about limits", "Think through the job", "Offer relevant items", "Respect the customer’s choice", "Understand the budget", "Compare total value", "Respond without arguing", "Confirm the choice", "Check practical details", "End with a clear handoff", "CS-102-", "ID", "P01", "P02", "P03", "P04", "P05"], "learning_paths": ["Sales Floor Associate"]}}$coursedata$::jsonb;
 c jsonb; l jsonb; q jsonb; target uuid;
begin
 c := payload->'course'; target := (c->>'id')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('coltrain-course:' || target::text, 0));
 if exists(select 1 from public.training_courses where id=target) then
  if not exists(select 1 from public.training_courses t where t.id=target
   and t.slug=c->>'slug' and t.version=(c->>'version')::integer
   and t.title=c->>'title' and t.description=c->>'description'
   and t.category=c->>'category' and t.passing_percent=(c->>'passing_percent')::integer
   and t.owner_organization_id is null) then
   raise exception 'CS-102 course differs; create a new version rather than overwrite';
  end if;
  if (select count(*) from public.training_lessons where course_id=target) <> jsonb_array_length(payload->'lessons')
   or (select count(*) from public.training_questions where course_id=target) <> jsonb_array_length(payload->'questions') then
   raise exception 'CS-102 content differs; draft import was not changed';
  end if;
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   if not exists(select 1 from public.training_lessons t where t.id=(l->>'id')::uuid
    and t.course_id=target and t.position=(l->>'position')::integer
    and t.title=l->>'title' and t.body=l->'body') then
    raise exception 'CS-102 lesson differs; draft import was not changed';
   end if;
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   if not exists(select 1 from public.training_questions t join private.training_answer_keys k on k.question_id=t.id
    where t.id=(q->>'id')::uuid and t.course_id=target and t.position=(q->>'position')::integer
    and t.prompt=q->>'prompt' and t.options=q->'options'
    and k.correct_option=(q->>'correct_option')::integer and k.explanation=q->>'explanation') then
    raise exception 'CS-102 question differs; draft import was not changed';
   end if;
  end loop;
 else
  insert into public.training_courses(id,slug,version,title,description,category,passing_percent,published)
   values(target,c->>'slug',(c->>'version')::integer,c->>'title',c->>'description',c->>'category',(c->>'passing_percent')::integer,false);
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   insert into public.training_lessons(id,course_id,position,title,body)
    values((l->>'id')::uuid,target,(l->>'position')::integer,l->>'title',l->'body');
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   insert into public.training_questions(id,course_id,position,prompt,options)
    values((q->>'id')::uuid,target,(q->>'position')::integer,q->>'prompt',q->'options');
   insert into private.training_answer_keys(question_id,correct_option,explanation)
    values((q->>'id')::uuid,(q->>'correct_option')::integer,q->>'explanation');
  end loop;
 end if;
 -- Optional metadata: imports remain compatible before the catalog migration.
 if to_regclass('public.training_course_catalog') is not null then
  insert into public.training_course_catalog(course_id,course_code,skill_level,topics,keywords,learning_paths)
  values(target,payload->'catalog'->>'course_code',payload->'catalog'->>'skill_level',
   array(select jsonb_array_elements_text(payload->'catalog'->'topics')),
   array(select jsonb_array_elements_text(payload->'catalog'->'keywords')),
   array(select jsonb_array_elements_text(payload->'catalog'->'learning_paths')))
  on conflict(course_id) do nothing;
 end if;
end;
$courseimport$;
do $courseimport$
declare
 payload jsonb := $coursedata${"course": {"id": "f03c1354-7aec-596c-b72e-7df51d92be50", "slug": "cs-103-helping-customers-when-you-don-t-know-the-answer", "version": 1, "title": "Helping Customers When You Don't Know the Answer", "description": "Learn how to respond with confidence when a customer asks an unfamiliar question. Gather details, verify information, and make a helpful handoff.", "category": "Customer Experience & Sales", "passing_percent": 80}, "lessons": [{"id": "18a678d9-7c59-54d0-9393-c5c7088056e4", "position": 1, "title": "Stay Calm and Take Ownership", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Customers expect help. They do not expect every new employee to know everything."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Be honest and helpful"}, {"type": "paragraph", "text": "Say you want to verify the answer. Keep a calm tone. Avoid guessing or dismissing the customer."}, {"type": "heading", "text": "Own the next step"}, {"type": "paragraph", "text": "Explain what you will do next. You might check a label, consult a coworker, or find official instructions."}, {"type": "heading", "text": "Stay connected"}, {"type": "paragraph", "text": "Do not send a customer away without a clear handoff. If you must leave, explain where you are going and return as promised."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer asks whether a certain blade fits their saw. You are unsure. You say you will check the saw model and blade information before giving an answer."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Say: “I want to make sure we get this right.”"}, {"type": "bullet", "text": "Ask for the product model or package."}, {"type": "bullet", "text": "Explain the next step."}, {"type": "bullet", "text": "Return with an answer or a clear referral."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Guessing to sound confident."}, {"type": "bullet", "text": "Saying “I don’t know” and walking away."}, {"type": "bullet", "text": "Promising an answer you cannot verify."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a specialist when product compatibility or safe use is uncertain. Never recommend an unverified blade or accessory."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Be honest."}, {"type": "bullet", "text": "Take responsibility for the next step."}, {"type": "bullet", "text": "Keep the customer informed."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Practice ID: CS-103-P01"}, {"type": "paragraph", "text": "Question: You do not know whether a blade fits a saw. What should you say?"}, {"type": "bullet", "text": "A. “It probably fits.”"}, {"type": "bullet", "text": "B. “I’m new. Ask someone else.”"}, {"type": "bullet", "text": "C. “Let’s check the model and the blade specifications.”"}, {"type": "bullet", "text": "D. “All blades fit most saws.”"}, {"type": "paragraph", "text": "Answer: C"}, {"type": "paragraph", "text": "Explanation: Checking the model and specifications is a useful next step. It avoids guessing."}, {"type": "heading", "text": "Optional practice"}, {"type": "bullet", "text": "None."}]}, {"id": "d48ff8f2-2c8c-5af4-bbb5-baf70dc90451", "position": 2, "title": "Ask Questions That Find the Missing Detail", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Many questions are hard to answer because key details are missing."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Clarify the problem"}, {"type": "paragraph", "text": "Ask what the customer is trying to do. Find out what is not working or what needs replacing."}, {"type": "heading", "text": "Identify the product"}, {"type": "paragraph", "text": "Ask for a model number, measurements, old part, package, or photo. Do not assume similar-looking parts are interchangeable."}, {"type": "heading", "text": "Repeat the request"}, {"type": "paragraph", "text": "Summarize what you know. This helps the customer correct missing or misunderstood details."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer needs a replacement filter but does not know the size. You ask for the equipment model and the label on the old filter. You can now look for a verified match."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Ask: “What equipment is this for?”"}, {"type": "bullet", "text": "Ask: “Do you have the model number?”"}, {"type": "bullet", "text": "Ask: “Can you show me the old part or a photo?”"}, {"type": "bullet", "text": "Repeat the key details."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Searching without enough information."}, {"type": "bullet", "text": "Assuming size from appearance."}, {"type": "bullet", "text": "Asking for details unrelated to the problem."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a coworker for help identifying a model or part. Use manufacturer documentation for compatibility."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Find the missing detail."}, {"type": "bullet", "text": "Use product identifiers."}, {"type": "bullet", "text": "Confirm what you heard."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Practice ID: CS-103-P02"}, {"type": "paragraph", "text": "Question: A customer needs a filter but does not know the size. What detail would help most?"}, {"type": "bullet", "text": "A. Their favorite brand color."}, {"type": "bullet", "text": "B. The equipment model or old filter label."}, {"type": "bullet", "text": "C. The date of their last store visit."}, {"type": "bullet", "text": "D. Their preferred checkout lane."}, {"type": "paragraph", "text": "Answer: B"}, {"type": "paragraph", "text": "Explanation: A model or filter label can help verify compatibility."}, {"type": "heading", "text": "Optional practice"}, {"type": "bullet", "text": "None."}]}, {"id": "4d4c10ab-60e0-50e8-8ed5-47cd0762a042", "position": 3, "title": "Use Reliable Information", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "A confident guess can lead to a wrong purchase or unsafe use."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Start with the product"}, {"type": "paragraph", "text": "Read the package and labels. Look for model numbers, sizes, ratings, and warnings. Do not treat packaging as a substitute for full instructions when more detail is needed."}, {"type": "heading", "text": "Use official instructions"}, {"type": "paragraph", "text": "For compatibility, safety, and warranty questions, prefer current manufacturer information. Check that the document matches the exact model."}, {"type": "heading", "text": "Know what is not confirmed"}, {"type": "paragraph", "text": "If you cannot verify a claim, tell the customer. Explain the next safe step."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer asks whether a particular battery works with a power tool. You compare the exact tool and battery models using official compatibility information. You do not rely on color or appearance."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Say: “Let’s check the model information.”"}, {"type": "bullet", "text": "Read the label with the customer."}, {"type": "bullet", "text": "Use current official product instructions when available."}, {"type": "bullet", "text": "State clearly what remains unverified."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Relying on memory for a safety claim."}, {"type": "bullet", "text": "Using instructions for a different model."}, {"type": "bullet", "text": "Treating an online comment as a manufacturer policy."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a specialist or manager if official information is unavailable or unclear. Refer the customer to manufacturer support or a qualified professional when appropriate."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Check exact models."}, {"type": "bullet", "text": "Prefer official instructions."}, {"type": "bullet", "text": "Do not present guesses as facts."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Practice ID: CS-103-P03"}, {"type": "paragraph", "text": "Question: A customer asks whether a battery fits a tool. Which source is strongest?"}, {"type": "bullet", "text": "A. A guess based on the color."}, {"type": "bullet", "text": "B. A comment from an unknown forum."}, {"type": "bullet", "text": "C. Current manufacturer compatibility information for the exact models."}, {"type": "bullet", "text": "D. A similar product on the next shelf."}, {"type": "paragraph", "text": "Answer: C"}, {"type": "paragraph", "text": "Explanation: Official information for the exact models is more reliable than appearance or guesses."}, {"type": "heading", "text": "Optional practice"}, {"type": "bullet", "text": "None."}]}, {"id": "b8150481-d144-5939-ad60-0077bede9229", "position": 4, "title": "Make a Helpful Handoff", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "A customer should not need to repeat the same story several times."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Choose the right helper"}, {"type": "paragraph", "text": "Find a coworker with relevant product knowledge. Use a manager for store policy or an unresolved service issue."}, {"type": "heading", "text": "Summarize the need"}, {"type": "paragraph", "text": "Tell the next employee what the customer wants, what details you checked, and what remains unanswered."}, {"type": "heading", "text": "Follow through"}, {"type": "paragraph", "text": "Confirm that the handoff happened. If no one is available, explain the options without promising a time you cannot guarantee."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer needs a part for a pressure washer. You have the model number but cannot confirm the fitting. You introduce the customer to the power equipment specialist and share the model number and the question."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Say: “I have the model number. Let me bring in our equipment specialist.”"}, {"type": "bullet", "text": "Share the details already collected."}, {"type": "bullet", "text": "Confirm the customer knows who will help next."}, {"type": "bullet", "text": "Avoid promising a wait time without checking."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Pointing vaguely across the store."}, {"type": "bullet", "text": "Making the customer repeat every detail."}, {"type": "bullet", "text": "Leaving before confirming the handoff."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a manager when a specialist is unavailable or a customer needs a policy decision. Refer technical work beyond retail advice to a qualified professional."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Find the right helper."}, {"type": "bullet", "text": "Share the details."}, {"type": "bullet", "text": "Confirm the handoff."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Practice ID: CS-103-P04"}, {"type": "paragraph", "text": "Question: You need to transfer a customer to a plumbing specialist. What should you do?"}, {"type": "bullet", "text": "A. Tell the customer to find someone in plumbing."}, {"type": "bullet", "text": "B. Introduce the specialist and share the details you already gathered."}, {"type": "bullet", "text": "C. Walk away without explanation."}, {"type": "bullet", "text": "D. Give an answer you are unsure about."}, {"type": "paragraph", "text": "Answer: B"}, {"type": "paragraph", "text": "Explanation: A good handoff saves time and shows ownership of the customer’s need."}, {"type": "heading", "text": "Optional practice"}, {"type": "bullet", "text": "None."}]}, {"id": "85049f8d-ff8b-58db-8b3a-ff95c751dffc", "position": 5, "title": "Know When to Stop and Escalate", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Some questions involve risks or decisions outside a retail employee’s authority."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Recognize higher-risk topics"}, {"type": "paragraph", "text": "Electrical wiring, gas connections, structural loads, chemical mixing, and power equipment safety can involve serious hazards. Product advice is not a substitute for professional work."}, {"type": "heading", "text": "Separate product facts from professional advice"}, {"type": "paragraph", "text": "You may help locate a product or find official instructions. Do not design, approve, or certify work that requires a qualified professional."}, {"type": "heading", "text": "Escalate clearly"}, {"type": "paragraph", "text": "Explain why you need another source. Ask a manager for store policies. Use official manufacturer support for unresolved product questions. Recommend a qualified professional for work beyond your role."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer asks you to confirm that a fastener will support a heavy overhead load. You can help find product specifications. You do not approve the installation. You explain that the load and installation need qualified evaluation."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Say: “I can help find the product specifications.”"}, {"type": "bullet", "text": "Say: “I cannot confirm this installation is safe.”"}, {"type": "bullet", "text": "Refer to a qualified professional for technical approval."}, {"type": "bullet", "text": "Ask a manager about store policy."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Treating a package rating as approval for every installation."}, {"type": "bullet", "text": "Giving installation advice outside your training."}, {"type": "bullet", "text": "Ignoring a warning because a customer wants a quick answer."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Escalate immediately when there is a safety concern, an unclear manufacturer warning, or a request for technical approval outside retail scope."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Know your role limits."}, {"type": "bullet", "text": "Escalate safety-sensitive questions."}, {"type": "bullet", "text": "Give a clear next step."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Practice ID: CS-103-P05"}, {"type": "paragraph", "text": "Question: A customer asks you to approve hardware for a heavy overhead installation. What should you do?"}, {"type": "bullet", "text": "A. Guarantee the hardware is safe."}, {"type": "bullet", "text": "B. Recommend the biggest fastener."}, {"type": "bullet", "text": "C. Find product specifications and refer the installation decision to a qualified professional."}, {"type": "bullet", "text": "D. Tell the customer any fastener will work."}, {"type": "paragraph", "text": "Answer: C"}, {"type": "paragraph", "text": "Explanation: Retail employees can provide verified product facts. They should not certify a high-risk installation."}, {"type": "heading", "text": "Optional practice"}, {"type": "bullet", "text": "None."}]}], "questions": [{"id": "5249089e-04c8-5601-a024-60ba50a3eb02", "position": 1, "prompt": "A customer asks a question about a product you have never sold. What should you do first?", "options": ["Guess based on the product name.", "Say you will verify the information and explain the next step.", "Tell them to shop elsewhere.", "Promise the product will work."], "correct_option": 1, "explanation": "Honesty and a clear next step build trust. Guessing or dismissing the customer does not help."}, {"id": "0a298efa-6926-54c3-9bd5-fcdec56161ae", "position": 2, "prompt": "A customer needs a replacement part for a tool. Which information is most useful?", "options": ["The tool model number and old part details.", "The customer’s preferred payment method.", "The color of the store sign.", "The day the customer usually shops."], "correct_option": 0, "explanation": "Exact model and part details support a reliable match. The other details do not identify the part."}, {"id": "b55e5a83-947b-5570-b6b1-14c031120785", "position": 3, "prompt": "A customer asks about a tool battery’s compatibility. What is the best next step?", "options": ["Choose one with the same color.", "Use a different tool’s manual.", "Ask another customer to guess.", "Check current manufacturer information for the exact tool and battery models."], "correct_option": 3, "explanation": "Manufacturer compatibility information for exact models is the appropriate source. Appearance and unrelated manuals are not reliable."}, {"id": "fbfad3d3-5ad6-5199-bbce-9e45c2559bbd", "position": 4, "prompt": "You have collected a pressure washer model number but need help finding a fitting. How should you hand off the customer?", "options": ["Point toward the equipment counter.", "Tell them to start the story over.", "Introduce a specialist and share the model and unanswered question.", "Leave without confirming anyone is available."], "correct_option": 2, "explanation": "A direct handoff with the known details saves time and keeps the customer supported."}, {"id": "3c56a04b-4055-5c6b-b145-e74c8f172d81", "position": 5, "prompt": "A customer asks you to approve a fastener for a heavy overhead load. What is the best response?", "options": ["Promise it is safe if the package shows a high rating.", "Help locate specifications and refer the installation decision to a qualified professional.", "Recommend any larger fastener.", "Say you can certify the installation."], "correct_option": 1, "explanation": "Product ratings do not establish suitability for every installation. A qualified professional must evaluate the application."}], "catalog": {"course_code": "CS-103", "skill_level": "foundations", "topics": ["Helping Customers When You Don't Know the Answer"], "keywords": ["Stay Calm and Take Ownership", "Ask Questions That Find the Missing Detail", "Use Reliable Information", "Make a Helpful Handoff", "Know When to Stop and Escalate", "Why this matters", "Lesson content", "Be honest and helpful", "Own the next step", "Stay connected", "Hardware-store example", "What to say or do", "Common mistakes", "When to ask for help", "Key takeaways", "Unscored lesson practice", "Optional practice", "Clarify the problem", "Identify the product", "Repeat the request", "Start with the product", "Use official instructions", "Know what is not confirmed", "Choose the right helper", "Summarize the need", "Follow through", "Recognize higher-risk topics", "Separate product facts from professional advice", "Escalate clearly", "CS-103-", "ID", "P01", "P02", "P03", "P04", "P05"], "learning_paths": ["New Retail Employee"]}}$coursedata$::jsonb;
 c jsonb; l jsonb; q jsonb; target uuid;
begin
 c := payload->'course'; target := (c->>'id')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('coltrain-course:' || target::text, 0));
 if exists(select 1 from public.training_courses where id=target) then
  if not exists(select 1 from public.training_courses t where t.id=target
   and t.slug=c->>'slug' and t.version=(c->>'version')::integer
   and t.title=c->>'title' and t.description=c->>'description'
   and t.category=c->>'category' and t.passing_percent=(c->>'passing_percent')::integer
   and t.owner_organization_id is null) then
   raise exception 'CS-103 course differs; create a new version rather than overwrite';
  end if;
  if (select count(*) from public.training_lessons where course_id=target) <> jsonb_array_length(payload->'lessons')
   or (select count(*) from public.training_questions where course_id=target) <> jsonb_array_length(payload->'questions') then
   raise exception 'CS-103 content differs; draft import was not changed';
  end if;
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   if not exists(select 1 from public.training_lessons t where t.id=(l->>'id')::uuid
    and t.course_id=target and t.position=(l->>'position')::integer
    and t.title=l->>'title' and t.body=l->'body') then
    raise exception 'CS-103 lesson differs; draft import was not changed';
   end if;
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   if not exists(select 1 from public.training_questions t join private.training_answer_keys k on k.question_id=t.id
    where t.id=(q->>'id')::uuid and t.course_id=target and t.position=(q->>'position')::integer
    and t.prompt=q->>'prompt' and t.options=q->'options'
    and k.correct_option=(q->>'correct_option')::integer and k.explanation=q->>'explanation') then
    raise exception 'CS-103 question differs; draft import was not changed';
   end if;
  end loop;
 else
  insert into public.training_courses(id,slug,version,title,description,category,passing_percent,published)
   values(target,c->>'slug',(c->>'version')::integer,c->>'title',c->>'description',c->>'category',(c->>'passing_percent')::integer,false);
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   insert into public.training_lessons(id,course_id,position,title,body)
    values((l->>'id')::uuid,target,(l->>'position')::integer,l->>'title',l->'body');
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   insert into public.training_questions(id,course_id,position,prompt,options)
    values((q->>'id')::uuid,target,(q->>'position')::integer,q->>'prompt',q->'options');
   insert into private.training_answer_keys(question_id,correct_option,explanation)
    values((q->>'id')::uuid,(q->>'correct_option')::integer,q->>'explanation');
  end loop;
 end if;
 -- Optional metadata: imports remain compatible before the catalog migration.
 if to_regclass('public.training_course_catalog') is not null then
  insert into public.training_course_catalog(course_id,course_code,skill_level,topics,keywords,learning_paths)
  values(target,payload->'catalog'->>'course_code',payload->'catalog'->>'skill_level',
   array(select jsonb_array_elements_text(payload->'catalog'->'topics')),
   array(select jsonb_array_elements_text(payload->'catalog'->'keywords')),
   array(select jsonb_array_elements_text(payload->'catalog'->'learning_paths')))
  on conflict(course_id) do nothing;
 end if;
end;
$courseimport$;
do $courseimport$
declare
 payload jsonb := $coursedata${"course": {"id": "9cbd5d08-66bc-5844-aadb-fd69f546dc69", "slug": "im-101-inventory-management-fundamentals", "version": 1, "title": "Inventory Management Fundamentals", "description": "Learn how products move through a hardware store, how inventory records support customer service, and how to handle common stock questions accurately.", "category": "Inventory & Merchandising", "passing_percent": 80}, "lessons": [{"id": "1f1d99f3-99b2-5efa-81a6-c5b32cfded96", "position": 1, "title": "Inventory Is More Than What Is on the Shelf", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Inventory is the merchandise a store has for sale. A product may be in the aisle, in a back room, on a display, or waiting to be received. The computer record is useful, but it is not a promise that an item is ready for a customer to take home."}, {"type": "heading", "text": "Lesson content"}, {"type": "paragraph", "text": "Three useful numbers. On-hand means the quantity recorded as physically owned or held by the store. Available means the quantity that can be sold now under the store’s system rules. On-order means units expected from a supplier. These numbers can differ because of holds, pending transactions, receiving delays, or errors."}, {"type": "paragraph", "text": "Why it matters. An incorrect count can lead to a missed sale, an unnecessary reorder, or a disappointed customer. Verify the item, size, and location before promising it is available."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer asks for twelve 3-inch deck screws in a specific package. The system shows twelve packages on hand, but only eight are on the shelf. The associate checks approved alternate locations and asks for help before promising twelve."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Confirm the exact SKU, size, and package quantity."}, {"type": "bullet", "text": "Check the approved inventory view and the shelf location."}, {"type": "bullet", "text": "Explain what you can verify, not what you assume."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Treating an on-hand count as a guarantee of availability."}, {"type": "bullet", "text": "Confusing pieces with packages."}, {"type": "bullet", "text": "Promising incoming stock before it is received."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask the inventory lead when a count, reservation, or shipment status is unclear."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Confirm the exact SKU, size, and package quantity."}, {"type": "bullet", "text": "Check the approved inventory view and the shelf location."}, {"type": "bullet", "text": "Ask the inventory lead when a count, reservation, or shipment status is unclear."}, {"type": "heading", "text": "Optional practice — unscored (IM-101-P01)"}, {"type": "paragraph", "text": "A system shows 10 on hand, but only 6 are visible. What should you tell a customer?"}, {"type": "bullet", "text": "A. Ten are definitely ready to buy."}, {"type": "bullet", "text": "B. You can verify six now and check for the others."}, {"type": "bullet", "text": "C. The system must be wrong."}, {"type": "bullet", "text": "D. Tell the customer to return tomorrow."}, {"type": "paragraph", "text": "Answer: B. The visible six can be verified. Check other approved locations before promising more."}]}, {"id": "08f4a144-2017-56ca-8574-d7bfe96d9e76", "position": 2, "title": "Follow a Product from Delivery to Sale", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "A product usually enters through an order and delivery. It is checked, received in the approved system, labeled or located, stocked, sold, and replenished when needed. Each step depends on accurate information from the previous step."}, {"type": "heading", "text": "Lesson content"}, {"type": "paragraph", "text": "Receiving is a checkpoint. Compare delivered products with the store’s receiving paperwork or system. Confirm product identity, units, and quantities. Record exceptions using the store’s process. Do not assume every box contains the expected item."}, {"type": "paragraph", "text": "Stocking supports finding. Place items in the correct approved location with readable labels. Keep the product identifier connected to the right shelf tag. A product placed in the wrong bay can appear missing even when it is in the building."}, {"type": "paragraph", "text": "Sales update records. A completed sale usually changes the system’s stock record. Returns, transfers, damage, and corrections may also change counts. Exact timing and permissions depend on the store’s software."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A carton marked “12” contains twelve individual hinges, but the store sells them in packs of two. The receiver checks the SKU and unit of measure before entering a quantity."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Check the item identifier and unit of measure."}, {"type": "bullet", "text": "Follow the store’s receiving workflow."}, {"type": "bullet", "text": "Set aside and report mismatches instead of guessing."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Receiving by carton count when the system expects eaches."}, {"type": "bullet", "text": "Putting merchandise out before resolving an item mismatch."}, {"type": "bullet", "text": "Leaving an unreadable shelf label in place."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a trained receiver or manager before posting a questionable receipt or correction."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Check the item identifier and unit of measure."}, {"type": "bullet", "text": "Follow the store’s receiving workflow."}, {"type": "bullet", "text": "Ask a trained receiver or manager before posting a questionable receipt or correction."}, {"type": "heading", "text": "Optional practice — unscored (IM-101-P02)"}, {"type": "paragraph", "text": "A carton holds 12 individual pieces, but the system expects packs of two. What comes first?"}, {"type": "bullet", "text": "A. Enter 12 packs."}, {"type": "bullet", "text": "B. Ignore the difference."}, {"type": "bullet", "text": "C. Verify the SKU and unit of measure."}, {"type": "bullet", "text": "D. Place everything on the shelf."}, {"type": "paragraph", "text": "Answer: C. The unit of measure determines how the quantity should be entered."}]}, {"id": "9a83d0ce-57f4-5909-a071-e7f4a4a33750", "position": 3, "title": "Stock Shelves with Accuracy and Care", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Good stocking makes products easier to find and reduces avoidable mistakes. It also keeps aisles usable and prevents damage. Follow the store’s safety rules and do not use equipment you are not authorized to operate."}, {"type": "heading", "text": "Lesson content"}, {"type": "paragraph", "text": "Match the label. Read the SKU, size, color, and package count. Similar-looking products can be different. Compare the product to the shelf tag before placing it."}, {"type": "paragraph", "text": "Keep stock organized. Use the store’s rotation rules when they apply. Keep heavy products in approved locations. Do not block exits, fire equipment, or customer walkways."}, {"type": "paragraph", "text": "Watch for damage. Do not place leaking, broken, or unsafe products on the sales floor. Follow the store’s process for isolating and reporting them."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "Two boxes of similar faucet connectors have different lengths. An associate checks both labels rather than placing them together behind one shelf tag."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Match product and shelf tag before stocking."}, {"type": "bullet", "text": "Keep merchandise within approved shelf limits."}, {"type": "bullet", "text": "Report damaged or mislabeled items."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Stocking by appearance alone."}, {"type": "bullet", "text": "Hiding extra product in an unrecorded location."}, {"type": "bullet", "text": "Blocking an aisle with cartons."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask for help with high, heavy, leaking, damaged, or uncertain merchandise."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Match product and shelf tag before stocking."}, {"type": "bullet", "text": "Keep merchandise within approved shelf limits."}, {"type": "bullet", "text": "Ask for help with high, heavy, leaking, damaged, or uncertain merchandise."}, {"type": "heading", "text": "Optional practice — unscored (IM-101-P03)"}, {"type": "paragraph", "text": "Two packages look alike but have different lengths. What is the best next step?"}, {"type": "bullet", "text": "A. Put both behind the same tag."}, {"type": "bullet", "text": "B. Check each product identifier against its location."}, {"type": "bullet", "text": "C. Choose the more expensive shelf."}, {"type": "bullet", "text": "D. Leave them in the aisle."}, {"type": "paragraph", "text": "Answer: B. The item identifier prevents a wrong-location error."}]}, {"id": "d1fae175-99ab-511e-b113-45973a33ca1b", "position": 4, "title": "Investigate Inventory Differences", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "A discrepancy is a difference between what the system says and what staff can verify. A missing item does not always mean theft. It may be in another location, not yet received, sold under another identifier, or counted in the wrong unit."}, {"type": "heading", "text": "Lesson content"}, {"type": "paragraph", "text": "Start with the exact item. Check the SKU and unit of measure. Look at approved shelf, display, back-stock, and hold locations. Review available transaction details only if your role permits."}, {"type": "paragraph", "text": "Record what you found. Use the store’s approved count or discrepancy process. State the quantity you physically verified and where you checked. Do not quietly change records or accuse anyone."}, {"type": "paragraph", "text": "Escalate adjustments. Inventory adjustments can affect ordering and financial records. Only authorized employees should make them."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A paint roller refill shows six on hand but none in its assigned bay. The associate checks the endcap and back-stock location, then reports the discrepancy with the SKU."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Verify the exact SKU."}, {"type": "bullet", "text": "Check approved alternate locations."}, {"type": "bullet", "text": "Document findings and request an authorized adjustment if needed."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Assuming missing stock was stolen."}, {"type": "bullet", "text": "Changing counts without permission."}, {"type": "bullet", "text": "Counting a similar item as the missing SKU."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask the inventory manager before any count correction, suspected loss investigation, or unexplained variance."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Verify the exact SKU."}, {"type": "bullet", "text": "Check approved alternate locations."}, {"type": "bullet", "text": "Ask the inventory manager before any count correction, suspected loss investigation, or unexplained variance."}, {"type": "heading", "text": "Optional practice — unscored (IM-101-P04)"}, {"type": "paragraph", "text": "You find a count mismatch. What should you do first?"}, {"type": "bullet", "text": "A. Accuse a coworker."}, {"type": "bullet", "text": "B. Change the count immediately."}, {"type": "bullet", "text": "C. Verify the SKU and approved locations."}, {"type": "bullet", "text": "D. Delete the product record."}, {"type": "paragraph", "text": "Answer: C. Check identity and locations before escalating a documented discrepancy."}]}, {"id": "a9ca136a-2c1f-5082-b023-596ffe6b2320", "position": 5, "title": "Help Customers with Stock Questions", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Customers want a reliable answer about whether they can buy an item today. Give the clearest verified answer you have. If the quantity is uncertain, say so and explain the next step."}, {"type": "heading", "text": "Lesson content"}, {"type": "paragraph", "text": "Separate facts from estimates. A shelf check is a verified observation. An expected delivery date may be an estimate. Do not promise a shipment or hold unless the store’s policy and system support it."}, {"type": "paragraph", "text": "Offer a useful next step. Check approved locations, request a stock check, or connect the customer with a team member who can confirm ordering options. Ask before suggesting a substitute because size or compatibility may matter."}, {"type": "paragraph", "text": "Close the loop. If you promise to check, tell the customer what you found or who will follow up. Do not leave a customer waiting without an update."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer needs eight matching cabinet pulls. Six are confirmed on the shelf. The associate explains that six are available now and asks the inventory lead to check the remaining quantity."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "State the quantity you verified."}, {"type": "bullet", "text": "Explain what still needs checking."}, {"type": "bullet", "text": "Offer an approved next step or handoff."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Promising an arrival date without confirmation."}, {"type": "bullet", "text": "Substituting a different size without checking fit."}, {"type": "bullet", "text": "Saying “we have it” based only on a system count."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a supervisor about special orders, reservations, transfers, or uncertain delivery dates."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "State the quantity you verified."}, {"type": "bullet", "text": "Explain what still needs checking."}, {"type": "bullet", "text": "Ask a supervisor about special orders, reservations, transfers, or uncertain delivery dates."}, {"type": "heading", "text": "Optional practice — unscored (IM-101-P05)"}, {"type": "paragraph", "text": "A customer needs eight pulls, but you can verify six. Which response is best?"}, {"type": "bullet", "text": "A. We definitely have eight."}, {"type": "bullet", "text": "B. Six are here; I can check whether we have two more."}, {"type": "bullet", "text": "C. You should buy a different style."}, {"type": "bullet", "text": "D. Our computer is always correct."}, {"type": "paragraph", "text": "Answer: B. A clear verified quantity plus a next step builds trust."}]}], "questions": [{"id": "1fb70fc2-8023-54bb-9ab7-3214e444ff1f", "position": 1, "prompt": "Which statement best describes an on-hand count?", "options": ["The exact number visible on the shelf.", "The quantity recorded in the inventory system.", "The number arriving tomorrow.", "The number customers have reserved."], "correct_option": 1, "explanation": "On-hand is a recorded quantity. Physical availability still needs verification."}, {"id": "55d2cc48-1f40-5af5-a256-1b4ae1254322", "position": 2, "prompt": "Why must a receiver check the unit of measure?", "options": ["To make the boxes look neat.", "To determine which employee gets credit.", "To avoid counting pieces as packs or cartons.", "To speed up price changes."], "correct_option": 2, "explanation": "A quantity entered in the wrong unit creates inaccurate inventory."}, {"id": "d06c411a-509b-5eeb-8f94-e49ff305ce34", "position": 3, "prompt": "What should an associate do with a damaged or leaking product?", "options": ["Stock it with a discount label.", "Follow the store’s isolate-and-report process.", "Hide it in back stock.", "Throw it away without a record."], "correct_option": 1, "explanation": "Potentially unsafe merchandise must be handled through approved procedures."}, {"id": "2e971df5-34cd-5c11-9154-1f3107937b4b", "position": 4, "prompt": "The shelf count does not match the system. What is the best response?", "options": ["Change the count without asking.", "Assume theft.", "Verify SKU and locations, then report the difference.", "Ignore it until the next delivery."], "correct_option": 2, "explanation": "Verification and documented escalation protect record accuracy."}, {"id": "f79efeac-26f4-5006-a302-1ace4cdd9237", "position": 5, "prompt": "A customer asks whether ten units are available, but you verified seven. What should you say?", "options": ["All ten are ready.", "Seven are confirmed; I can check on the remaining three.", "Come back later without explanation.", "The computer must be wrong."], "correct_option": 1, "explanation": "Report the verified amount and offer a helpful next step."}], "catalog": {"course_code": "IM-101", "skill_level": "foundations", "topics": ["Inventory Management"], "keywords": ["Inventory Is More Than What Is on the Shelf", "Follow a Product from Delivery to Sale", "Stock Shelves with Accuracy and Care", "Investigate Inventory Differences", "Help Customers with Stock Questions", "Why this matters", "Lesson content", "Hardware-store example", "What to say or do", "Common mistakes", "When to ask for help", "Key takeaways", "Optional practice — unscored (IM-101-P01)", "Optional practice — unscored (IM-101-P02)", "Optional practice — unscored (IM-101-P03)", "Optional practice — unscored (IM-101-P04)", "Optional practice — unscored (IM-101-P05)", "IM-101-", "P01", "P02", "P03", "P04", "P05", "SKU"], "learning_paths": ["Inventory & Merchandising Associate", "Store Manager/Owner"]}}$coursedata$::jsonb;
 c jsonb; l jsonb; q jsonb; target uuid;
begin
 c := payload->'course'; target := (c->>'id')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('coltrain-course:' || target::text, 0));
 if exists(select 1 from public.training_courses where id=target) then
  if not exists(select 1 from public.training_courses t where t.id=target
   and t.slug=c->>'slug' and t.version=(c->>'version')::integer
   and t.title=c->>'title' and t.description=c->>'description'
   and t.category=c->>'category' and t.passing_percent=(c->>'passing_percent')::integer
   and t.owner_organization_id is null) then
   raise exception 'IM-101 course differs; create a new version rather than overwrite';
  end if;
  if (select count(*) from public.training_lessons where course_id=target) <> jsonb_array_length(payload->'lessons')
   or (select count(*) from public.training_questions where course_id=target) <> jsonb_array_length(payload->'questions') then
   raise exception 'IM-101 content differs; draft import was not changed';
  end if;
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   if not exists(select 1 from public.training_lessons t where t.id=(l->>'id')::uuid
    and t.course_id=target and t.position=(l->>'position')::integer
    and t.title=l->>'title' and t.body=l->'body') then
    raise exception 'IM-101 lesson differs; draft import was not changed';
   end if;
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   if not exists(select 1 from public.training_questions t join private.training_answer_keys k on k.question_id=t.id
    where t.id=(q->>'id')::uuid and t.course_id=target and t.position=(q->>'position')::integer
    and t.prompt=q->>'prompt' and t.options=q->'options'
    and k.correct_option=(q->>'correct_option')::integer and k.explanation=q->>'explanation') then
    raise exception 'IM-101 question differs; draft import was not changed';
   end if;
  end loop;
 else
  insert into public.training_courses(id,slug,version,title,description,category,passing_percent,published)
   values(target,c->>'slug',(c->>'version')::integer,c->>'title',c->>'description',c->>'category',(c->>'passing_percent')::integer,false);
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   insert into public.training_lessons(id,course_id,position,title,body)
    values((l->>'id')::uuid,target,(l->>'position')::integer,l->>'title',l->'body');
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   insert into public.training_questions(id,course_id,position,prompt,options)
    values((q->>'id')::uuid,target,(q->>'position')::integer,q->>'prompt',q->'options');
   insert into private.training_answer_keys(question_id,correct_option,explanation)
    values((q->>'id')::uuid,(q->>'correct_option')::integer,q->>'explanation');
  end loop;
 end if;
 -- Optional metadata: imports remain compatible before the catalog migration.
 if to_regclass('public.training_course_catalog') is not null then
  insert into public.training_course_catalog(course_id,course_code,skill_level,topics,keywords,learning_paths)
  values(target,payload->'catalog'->>'course_code',payload->'catalog'->>'skill_level',
   array(select jsonb_array_elements_text(payload->'catalog'->'topics')),
   array(select jsonb_array_elements_text(payload->'catalog'->'keywords')),
   array(select jsonb_array_elements_text(payload->'catalog'->'learning_paths')))
  on conflict(course_id) do nothing;
 end if;
end;
$courseimport$;
do $courseimport$
declare
 payload jsonb := $coursedata${"course": {"id": "d55fd14c-b59a-523b-a706-4b8bc7017798", "slug": "im-102-loss-prevention-fundamentals", "version": 1, "title": "Loss Prevention Fundamentals", "description": "Learn everyday habits that help protect people, merchandise, and store records without confrontation or profiling.", "category": "Inventory & Merchandising", "passing_percent": 80}, "lessons": [{"id": "6855e5ff-be11-522f-88a3-41792aec3815", "position": 1, "title": "Understand Loss and Shrink", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Loss prevention means reducing avoidable losses while keeping employees and customers safe. Shrink is the difference between recorded inventory and the inventory actually accounted for. Theft can contribute, but so can damage, mistakes, miscounts, and process problems."}, {"type": "heading", "text": "Lesson content"}, {"type": "paragraph", "text": "More than theft. Examples include damaged bags of soil, incorrect receiving quantities, mis-scanned products, and items placed in the wrong location. Never treat a discrepancy alone as proof of theft."}, {"type": "paragraph", "text": "People come first. Safety matters more than merchandise. Follow store policy for incidents and never confront, chase, restrain, or physically intervene with a suspected shoplifter."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A box of screws is counted as twelve cartons instead of twelve pieces. The inventory record is wrong even though no product was stolen."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Use neutral language such as “inventory difference.”"}, {"type": "bullet", "text": "Report damaged or missing stock using approved channels."}, {"type": "bullet", "text": "Keep yourself and customers safe."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Assuming every shortage is theft."}, {"type": "bullet", "text": "Trying to recover merchandise by force."}, {"type": "bullet", "text": "Sharing suspicions as facts."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a manager about an unexplained difference or any situation that feels unsafe."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Use neutral language such as “inventory difference.”"}, {"type": "bullet", "text": "Report damaged or missing stock using approved channels."}, {"type": "bullet", "text": "Ask a manager about an unexplained difference or any situation that feels unsafe."}, {"type": "heading", "text": "Optional practice — unscored (IM-102-P01)"}, {"type": "paragraph", "text": "A count is short by two items. What can you conclude?"}, {"type": "bullet", "text": "A. The last customer stole them."}, {"type": "bullet", "text": "B. A coworker is responsible."}, {"type": "bullet", "text": "C. There is a discrepancy that needs review."}, {"type": "bullet", "text": "D. The supplier always shipped too few."}, {"type": "paragraph", "text": "Answer: C. A shortage alone does not identify a cause."}]}, {"id": "2343dbbb-510c-56a9-a4fb-55030dfa6003", "position": 2, "title": "Reduce Loss Through Daily Habits", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Small, consistent actions protect merchandise. Accurate receiving, correct shelf labels, prompt damage reports, and careful transactions all matter."}, {"type": "heading", "text": "Lesson content"}, {"type": "paragraph", "text": "Check products and labels. Confirm the SKU and unit of measure when receiving or stocking. Keep small or high-value products in approved display locations without inventing new restrictions."}, {"type": "paragraph", "text": "Care for merchandise. Report torn packaging, leaks, and broken displays. Follow the store’s approved damage and disposal process."}, {"type": "paragraph", "text": "Keep work areas clear. A tidy checkout and organized receiving area make mistakes easier to spot. Keep customer walkways safe and maintain visibility according to store policy."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "An associate notices two nearly identical drill bits in the same bin. The associate separates them using the correct shelf tags and tells the department lead."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Match product to label."}, {"type": "bullet", "text": "Record damage and returns correctly."}, {"type": "bullet", "text": "Ask before moving controlled or secured merchandise."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Guessing which SKU belongs to a product."}, {"type": "bullet", "text": "Throwing away damaged stock without recording it."}, {"type": "bullet", "text": "Moving high-value items without updating approved locations."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask the department lead about damaged merchandise, security fixtures, or labeling problems."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Match product to label."}, {"type": "bullet", "text": "Record damage and returns correctly."}, {"type": "bullet", "text": "Ask the department lead about damaged merchandise, security fixtures, or labeling problems."}, {"type": "heading", "text": "Optional practice — unscored (IM-102-P02)"}, {"type": "paragraph", "text": "Which habit helps prevent avoidable inventory loss?"}, {"type": "bullet", "text": "A. Putting similar items in one unlabeled bin."}, {"type": "bullet", "text": "B. Recording damage through the approved process."}, {"type": "bullet", "text": "C. Ignoring torn packages."}, {"type": "bullet", "text": "D. Skipping receiving checks."}, {"type": "paragraph", "text": "Answer: B. Accurate damage records help explain missing or unsellable stock."}]}, {"id": "6e7d2613-2da3-5f9a-acee-96f4c61ce2d4", "position": 3, "title": "Notice Concerns Without Profiling", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Good loss prevention focuses on behavior and store processes, not on a person’s appearance, age, race, clothing, or other personal traits. Ordinary shopping behavior can have many explanations."}, {"type": "heading", "text": "Lesson content"}, {"type": "paragraph", "text": "Observe facts, not identities. If a situation raises concern, note what you actually saw and where it happened. Do not label someone a thief or make a claim you cannot support."}, {"type": "paragraph", "text": "Use normal customer service. Offer the same respectful assistance you would offer any customer. Do not follow, intimidate, or accuse a person."}, {"type": "paragraph", "text": "Keep reports private. Share factual concerns only with designated staff using approved channels. Avoid discussing suspicions on the sales floor or in personal group chats."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "An employee notices an opened package on a shelf. They report the package location and condition to a manager without accusing nearby shoppers."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Offer normal customer service."}, {"type": "bullet", "text": "Describe objective facts."}, {"type": "bullet", "text": "Tell the designated manager privately."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Making assumptions based on appearance."}, {"type": "bullet", "text": "Following or confronting a shopper."}, {"type": "bullet", "text": "Sharing an unverified accusation."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Contact a manager when you see damaged packaging, an unsafe situation, or a concerning incident."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Offer normal customer service."}, {"type": "bullet", "text": "Describe objective facts."}, {"type": "bullet", "text": "Contact a manager when you see damaged packaging, an unsafe situation, or a concerning incident."}, {"type": "heading", "text": "Optional practice — unscored (IM-102-P03)"}, {"type": "paragraph", "text": "You find an opened package near several shoppers. What should you report?"}, {"type": "bullet", "text": "A. Which shopper looks suspicious."}, {"type": "bullet", "text": "B. The package condition and exact location."}, {"type": "bullet", "text": "C. That a customer definitely stole something."}, {"type": "bullet", "text": "D. Nothing, because you did not see the opening."}, {"type": "paragraph", "text": "Answer: B. Report observable facts without speculation."}]}, {"id": "70371e31-d0d7-5b37-a43a-8a7931bc2696", "position": 4, "title": "Respond Safely to Suspected Theft", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "A loss-prevention concern is never a reason to put yourself or another person in danger. Your role is to stay safe, provide ordinary customer service if appropriate, and alert authorized staff."}, {"type": "heading", "text": "Lesson content"}, {"type": "paragraph", "text": "Do not intervene physically. Do not chase, block an exit, grab merchandise, search bags, or detain someone. Do not make accusations. Store rules and local laws may place additional limits on staff actions."}, {"type": "paragraph", "text": "Get help promptly. Notify the designated manager or security contact according to store policy. If there is an immediate threat, move to safety and use the store’s emergency procedure."}, {"type": "paragraph", "text": "Preserve factual information. If asked to report an incident, record only what you directly observed, such as time, location, and actions. Do not access or share video unless authorized."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "An associate thinks a customer may have left without paying. The associate does not pursue the person. They tell the manager what they directly observed."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Stay safe and avoid confrontation."}, {"type": "bullet", "text": "Use the designated reporting channel."}, {"type": "bullet", "text": "Follow emergency procedures for threats."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Chasing someone into the parking lot."}, {"type": "bullet", "text": "Blocking an exit."}, {"type": "bullet", "text": "Posting incident images online."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Contact a manager immediately for suspected theft; use emergency procedures if anyone is threatened."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Stay safe and avoid confrontation."}, {"type": "bullet", "text": "Use the designated reporting channel."}, {"type": "bullet", "text": "Contact a manager immediately for suspected theft; use emergency procedures if anyone is threatened."}, {"type": "heading", "text": "Optional practice — unscored (IM-102-P04)"}, {"type": "paragraph", "text": "A customer appears to leave with unpaid merchandise. What is the safest response?"}, {"type": "bullet", "text": "A. Chase them into the lot."}, {"type": "bullet", "text": "B. Block the doorway."}, {"type": "bullet", "text": "C. Notify the designated manager without confrontation."}, {"type": "bullet", "text": "D. Search their bag."}, {"type": "paragraph", "text": "Answer: C. Staff safety comes before merchandise recovery."}]}, {"id": "9b087a75-ecc6-5163-a3ff-49e5a9497cb3", "position": 5, "title": "Protect Transactions and Report Errors", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Transaction errors can cause loss even when no one intended harm. Accuracy at checkout, returns, discounts, and cash handling helps the store understand what happened."}, {"type": "heading", "text": "Lesson content"}, {"type": "paragraph", "text": "Verify before completing a transaction. Use the correct product barcode, quantity, and unit. Follow store procedures for discounts, returns, refunds, and overrides. Never share passwords or use another employee’s credentials."}, {"type": "paragraph", "text": "Correct mistakes openly. If you notice a missed scan, wrong quantity, or incorrect refund, tell an authorized team member and follow the correction process. Do not quietly edit or hide it."}, {"type": "paragraph", "text": "Respect privacy. Keep customer and payment information confidential. Use approved systems and channels for incident reports."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A cashier notices that a customer bought two identical items but only one was scanned. The cashier follows the approved correction process and requests help if the sale is complete."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Check item quantity and product identifiers."}, {"type": "bullet", "text": "Request authorized overrides or corrections."}, {"type": "bullet", "text": "Report errors without blame."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Using another employee’s login."}, {"type": "bullet", "text": "Applying unapproved discounts."}, {"type": "bullet", "text": "Concealing a scanning mistake."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a supervisor about overrides, cash discrepancies, refunds, or suspected fraud."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Check item quantity and product identifiers."}, {"type": "bullet", "text": "Request authorized overrides or corrections."}, {"type": "bullet", "text": "Ask a supervisor about overrides, cash discrepancies, refunds, or suspected fraud."}, {"type": "heading", "text": "Optional practice — unscored (IM-102-P05)"}, {"type": "paragraph", "text": "You notice a completed sale has a quantity error. What should you do?"}, {"type": "bullet", "text": "A. Edit the record secretly."}, {"type": "bullet", "text": "B. Follow the store’s correction process with authorized help."}, {"type": "bullet", "text": "C. Ignore it."}, {"type": "bullet", "text": "D. Use a coworker’s password."}, {"type": "paragraph", "text": "Answer: B. Authorized corrections keep transaction records reliable."}]}], "questions": [{"id": "c0c6a438-210c-585f-a872-0a4ab983b9ad", "position": 1, "prompt": "Which can cause inventory shrink besides theft?", "options": ["A receiving quantity error.", "A clean aisle.", "A correct shelf tag.", "A completed stock check."], "correct_option": 0, "explanation": "Shrink can come from process errors and damage as well as theft."}, {"id": "13d767e8-76ab-5a02-9691-98aeb292091f", "position": 2, "prompt": "What should an employee do with damaged merchandise?", "options": ["Discard it without recording it.", "Follow the approved damage-reporting process.", "Sell it without checking safety.", "Hide it behind the shelf."], "correct_option": 1, "explanation": "Documenting damage helps protect inventory accuracy."}, {"id": "673bf090-caa9-586a-b699-923d08d6ee84", "position": 3, "prompt": "What is the best basis for a concern report?", "options": ["A customer’s clothing.", "A customer’s age.", "Specific actions and conditions directly observed.", "A guess about someone’s intentions."], "correct_option": 2, "explanation": "Objective observations avoid unsupported assumptions and profiling."}, {"id": "74d479a8-7eaf-5ad1-8982-fd26e5f34cab", "position": 4, "prompt": "If you suspect someone has taken merchandise, what should you do?", "options": ["Chase them.", "Detain them.", "Notify the designated manager without confrontation.", "Demand to inspect their bag."], "correct_option": 2, "explanation": "Avoid physical intervention and follow store policy."}, {"id": "4aeae6ff-c434-5137-af25-29290e1eac8d", "position": 5, "prompt": "A completed sale contains a scanning error. What is the best response?", "options": ["Hide it.", "Use a coworker’s login to fix it.", "Tell authorized staff and follow the correction process.", "Blame the customer."], "correct_option": 2, "explanation": "Transparent, authorized corrections protect records and trust."}], "catalog": {"course_code": "IM-102", "skill_level": "foundations", "topics": ["Loss Prevention"], "keywords": ["Understand Loss and Shrink", "Reduce Loss Through Daily Habits", "Notice Concerns Without Profiling", "Respond Safely to Suspected Theft", "Protect Transactions and Report Errors", "Why this matters", "Lesson content", "Hardware-store example", "What to say or do", "Common mistakes", "When to ask for help", "Key takeaways", "Optional practice — unscored (IM-102-P01)", "Optional practice — unscored (IM-102-P02)", "Optional practice — unscored (IM-102-P03)", "Optional practice — unscored (IM-102-P04)", "Optional practice — unscored (IM-102-P05)", "IM-102-", "P01", "P02", "P03", "P04", "P05", "SKU"], "learning_paths": ["Inventory & Merchandising Associate", "Store Manager/Owner"]}}$coursedata$::jsonb;
 c jsonb; l jsonb; q jsonb; target uuid;
begin
 c := payload->'course'; target := (c->>'id')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('coltrain-course:' || target::text, 0));
 if exists(select 1 from public.training_courses where id=target) then
  if not exists(select 1 from public.training_courses t where t.id=target
   and t.slug=c->>'slug' and t.version=(c->>'version')::integer
   and t.title=c->>'title' and t.description=c->>'description'
   and t.category=c->>'category' and t.passing_percent=(c->>'passing_percent')::integer
   and t.owner_organization_id is null) then
   raise exception 'IM-102 course differs; create a new version rather than overwrite';
  end if;
  if (select count(*) from public.training_lessons where course_id=target) <> jsonb_array_length(payload->'lessons')
   or (select count(*) from public.training_questions where course_id=target) <> jsonb_array_length(payload->'questions') then
   raise exception 'IM-102 content differs; draft import was not changed';
  end if;
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   if not exists(select 1 from public.training_lessons t where t.id=(l->>'id')::uuid
    and t.course_id=target and t.position=(l->>'position')::integer
    and t.title=l->>'title' and t.body=l->'body') then
    raise exception 'IM-102 lesson differs; draft import was not changed';
   end if;
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   if not exists(select 1 from public.training_questions t join private.training_answer_keys k on k.question_id=t.id
    where t.id=(q->>'id')::uuid and t.course_id=target and t.position=(q->>'position')::integer
    and t.prompt=q->>'prompt' and t.options=q->'options'
    and k.correct_option=(q->>'correct_option')::integer and k.explanation=q->>'explanation') then
    raise exception 'IM-102 question differs; draft import was not changed';
   end if;
  end loop;
 else
  insert into public.training_courses(id,slug,version,title,description,category,passing_percent,published)
   values(target,c->>'slug',(c->>'version')::integer,c->>'title',c->>'description',c->>'category',(c->>'passing_percent')::integer,false);
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   insert into public.training_lessons(id,course_id,position,title,body)
    values((l->>'id')::uuid,target,(l->>'position')::integer,l->>'title',l->'body');
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   insert into public.training_questions(id,course_id,position,prompt,options)
    values((q->>'id')::uuid,target,(q->>'position')::integer,q->>'prompt',q->'options');
   insert into private.training_answer_keys(question_id,correct_option,explanation)
    values((q->>'id')::uuid,(q->>'correct_option')::integer,q->>'explanation');
  end loop;
 end if;
 -- Optional metadata: imports remain compatible before the catalog migration.
 if to_regclass('public.training_course_catalog') is not null then
  insert into public.training_course_catalog(course_id,course_code,skill_level,topics,keywords,learning_paths)
  values(target,payload->'catalog'->>'course_code',payload->'catalog'->>'skill_level',
   array(select jsonb_array_elements_text(payload->'catalog'->'topics')),
   array(select jsonb_array_elements_text(payload->'catalog'->'keywords')),
   array(select jsonb_array_elements_text(payload->'catalog'->'learning_paths')))
  on conflict(course_id) do nothing;
 end if;
end;
$courseimport$;
do $courseimport$
declare
 payload jsonb := $coursedata${"course": {"id": "7e20f6a5-e8da-5907-ae10-a34aa7b5836e", "slug": "im-103-merchandising-fundamentals", "version": 1, "title": "Merchandising Fundamentals", "description": "Learn how clear product presentation, accurate shelf information, and thoughtful displays help customers shop confidently.", "category": "Inventory & Merchandising", "passing_percent": 80}, "lessons": [{"id": "532ceb27-0d6b-598f-a741-774a4a860563", "position": 1, "title": "See the Store Through the Customer’s Eyes", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Merchandising is the way a store organizes and presents products for customers. Good merchandising helps a shopper find the right item, compare choices, and understand what else a project may require."}, {"type": "heading", "text": "Lesson content"}, {"type": "paragraph", "text": "Make products easy to find. Clear categories, readable signs, and organized shelves reduce confusion. Customers should not need to guess where related items are kept."}, {"type": "paragraph", "text": "Help customers compare. Group products according to the store’s approved plan. Make differences such as size, use, and package count visible."}, {"type": "paragraph", "text": "Keep information accurate. A tidy display is not helpful if the shelf label belongs to another product."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A shopper needs a paint roller. The associate points to a section where roller covers are arranged by size and type, with clear labels."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Walk an aisle as a first-time shopper would."}, {"type": "bullet", "text": "Check whether categories and labels make sense."}, {"type": "bullet", "text": "Report confusing signs or mixed products."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Assuming customers know store terminology."}, {"type": "bullet", "text": "Using an attractive sign that is hard to read."}, {"type": "bullet", "text": "Ignoring misplaced products."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a department lead before changing the store’s layout or category grouping."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Walk an aisle as a first-time shopper would."}, {"type": "bullet", "text": "Check whether categories and labels make sense."}, {"type": "bullet", "text": "Ask a department lead before changing the store’s layout or category grouping."}, {"type": "heading", "text": "Optional practice — unscored (IM-103-P01)"}, {"type": "paragraph", "text": "What is the main purpose of good merchandising?"}, {"type": "bullet", "text": "A. Make every shelf look full at any cost."}, {"type": "bullet", "text": "B. Help customers find and understand products."}, {"type": "bullet", "text": "C. Hide slower-selling items."}, {"type": "bullet", "text": "D. Reduce employee conversations."}, {"type": "paragraph", "text": "Answer: B. Merchandising supports clear, confident shopping."}]}, {"id": "a3bcada3-077b-5a2b-87d4-b2e2bdfeb2a8", "position": 2, "title": "Match Products, Locations, and Shelf Labels", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Shelf tags and signs should identify the product actually displayed. Similar packages can vary in size, quantity, finish, or price. Always check the item identifier rather than guessing from appearance."}, {"type": "heading", "text": "Lesson content"}, {"type": "paragraph", "text": "Read the details. Confirm SKU or barcode, description, size, unit, and price display according to store policy. If the label seems wrong, request verification before replacing it."}, {"type": "paragraph", "text": "Follow the approved plan. A planogram is a diagram or guide showing where products should be placed. Not every store uses one. Follow the store’s approved shelf arrangement or manager direction."}, {"type": "paragraph", "text": "Avoid misleading displays. Do not place a product under a price or promotion sign that applies to something else. Refer uncertain price questions to authorized staff."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "Two tubes of adhesive have similar packaging but different uses. The associate checks each item against its shelf tag before filling the hooks."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Match the product identifier to the shelf label."}, {"type": "bullet", "text": "Check size and unit differences."}, {"type": "bullet", "text": "Report uncertain pricing or signage."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Placing products based on package color."}, {"type": "bullet", "text": "Handwriting a price without permission."}, {"type": "bullet", "text": "Mixing items behind one label."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask the pricing or merchandising lead when the tag, price, or placement does not match."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Match the product identifier to the shelf label."}, {"type": "bullet", "text": "Check size and unit differences."}, {"type": "bullet", "text": "Ask the pricing or merchandising lead when the tag, price, or placement does not match."}, {"type": "heading", "text": "Optional practice — unscored (IM-103-P02)"}, {"type": "paragraph", "text": "Two products look alike but have different SKUs. What should you do?"}, {"type": "bullet", "text": "A. Place them together behind one tag."}, {"type": "bullet", "text": "B. Match each SKU to its approved shelf label."}, {"type": "bullet", "text": "C. Choose the label with the lower price."}, {"type": "bullet", "text": "D. Remove both labels."}, {"type": "paragraph", "text": "Answer: B. Accurate product-to-label matching prevents confusion."}]}, {"id": "590b179e-ef80-544c-a4da-9dc25dd73dfd", "position": 3, "title": "Build Useful and Safe Displays", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "A display should make a product easy to see and select without creating a hazard. Good displays balance visibility, clear information, accessibility, and safe storage."}, {"type": "heading", "text": "Lesson content"}, {"type": "paragraph", "text": "Show the purpose. A small project display can group related items, such as a paint tray, roller cover, painter’s tape, and drop cloth. Keep labels and prices clear for each product."}, {"type": "paragraph", "text": "Respect safe limits. Do not stack heavy or unstable products beyond approved limits. Keep exits, safety equipment, and walking routes clear. Ask for authorized help with ladders or powered equipment."}, {"type": "paragraph", "text": "Keep it shoppable. Customers should be able to take a product without pulling down a pile or disturbing another display. Replace damaged packaging through approved procedures."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A fall cleanup display pairs leaf bags with gloves and rakes. The team checks that the products are secure and the display does not narrow the aisle."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Use approved display fixtures and locations."}, {"type": "bullet", "text": "Keep products reachable and stable."}, {"type": "bullet", "text": "Show related products with clear individual labels."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Blocking a walkway with promotional merchandise."}, {"type": "bullet", "text": "Overloading a shelf."}, {"type": "bullet", "text": "Creating a display without accurate price information."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a manager about fixture limits, heavy merchandise, or new display locations."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Use approved display fixtures and locations."}, {"type": "bullet", "text": "Keep products reachable and stable."}, {"type": "bullet", "text": "Ask a manager about fixture limits, heavy merchandise, or new display locations."}, {"type": "heading", "text": "Optional practice — unscored (IM-103-P03)"}, {"type": "paragraph", "text": "Which display is most helpful?"}, {"type": "bullet", "text": "A. An unstable tower of products."}, {"type": "bullet", "text": "B. A clear project display with accurate labels and open walkways."}, {"type": "bullet", "text": "C. Mixed products with one price tag."}, {"type": "bullet", "text": "D. A display blocking a fire extinguisher."}, {"type": "paragraph", "text": "Answer: B. Useful displays are clear, accurate, and safe."}]}, {"id": "f3a7ae8f-a4ee-5133-9f59-3f4f0652059e", "position": 4, "title": "Maintain Shelves and Seasonal Areas", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Displays need attention after customers shop them. Empty hooks, mixed products, damaged packages, and outdated signs can confuse shoppers."}, {"type": "heading", "text": "Lesson content"}, {"type": "paragraph", "text": "Recover the aisle. Recovery means returning products to their proper locations and straightening shelves. Check item labels as you go rather than pushing everything forward without looking."}, {"type": "paragraph", "text": "Check promotions. Use the current approved promotion information. Remove or report outdated signs according to store procedure. Do not promise a promotion that cannot be verified."}, {"type": "paragraph", "text": "Think seasonally. Seasonal products should be easy to find when demand rises. Follow the approved calendar and layout. Do not move stock into a new location without approval."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "After a weekend sale, an associate finds spring seed packets mixed into fall lawn-care supplies. They sort them into approved locations and flag an expired sign."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Check for misplaced products."}, {"type": "bullet", "text": "Report empty locations and expired signs."}, {"type": "bullet", "text": "Follow the approved seasonal merchandising plan."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Leaving an expired sale sign up."}, {"type": "bullet", "text": "Moving seasonal stock without telling the team."}, {"type": "bullet", "text": "Ignoring damaged display packaging."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a manager about promotional timing, seasonal resets, or unavailable replacement signs."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Check for misplaced products."}, {"type": "bullet", "text": "Report empty locations and expired signs."}, {"type": "bullet", "text": "Ask a manager about promotional timing, seasonal resets, or unavailable replacement signs."}, {"type": "heading", "text": "Optional practice — unscored (IM-103-P04)"}, {"type": "paragraph", "text": "You notice an expired promotion sign. What is the best response?"}, {"type": "bullet", "text": "A. Leave it because it looks nice."}, {"type": "bullet", "text": "B. Verify and follow the approved sign-correction process."}, {"type": "bullet", "text": "C. Promise the discount anyway."}, {"type": "bullet", "text": "D. Move it to another aisle."}, {"type": "paragraph", "text": "Answer: B. Current, accurate signs reduce customer confusion."}]}, {"id": "b5857c4a-4045-5543-b7d8-fcbcbbd58e99", "position": 5, "title": "Improve Displays Using Customer Questions", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Customers show us where merchandising is confusing. Repeated questions about a location, size, or difference between products can point to a sign or layout problem."}, {"type": "heading", "text": "Lesson content"}, {"type": "paragraph", "text": "Notice repeated questions. If several shoppers cannot find the same product, check whether the location or sign is clear. One question does not prove the layout is wrong."}, {"type": "paragraph", "text": "Share a specific suggestion. Describe the customer problem and a possible improvement. Example: “Three shoppers asked where hose washers are. Could we add a clearer sign near the hose fittings?”"}, {"type": "paragraph", "text": "Make changes with approval. Managers may consider space, inventory, brand requirements, and safety before approving a new sign or display. Do not change prices or permanent layouts on your own."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "Customers regularly ask which sandpaper grit to choose. An associate suggests an approved comparison sign that explains grit ranges in plain language, subject to product accuracy review."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Record the recurring customer question."}, {"type": "bullet", "text": "Propose a clear, specific improvement."}, {"type": "bullet", "text": "Request approval before changing fixtures or permanent signs."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Changing prices to make a display simpler."}, {"type": "bullet", "text": "Treating one complaint as proof."}, {"type": "bullet", "text": "Adding unverified technical claims to signage."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a manager to review new signs, product claims, or layout changes."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Record the recurring customer question."}, {"type": "bullet", "text": "Propose a clear, specific improvement."}, {"type": "bullet", "text": "Ask a manager to review new signs, product claims, or layout changes."}, {"type": "heading", "text": "Optional practice — unscored (IM-103-P05)"}, {"type": "paragraph", "text": "Several customers cannot find hose washers. What is a useful next step?"}, {"type": "bullet", "text": "A. Ignore the questions."}, {"type": "bullet", "text": "B. Move the washers without telling anyone."}, {"type": "bullet", "text": "C. Suggest a clearer sign or location to the department lead."}, {"type": "bullet", "text": "D. Tell customers to search harder."}, {"type": "paragraph", "text": "Answer: C. Specific feedback can guide an approved improvement."}]}], "questions": [{"id": "d9b80c86-f9a8-5b90-9a59-1cde0ff9034f", "position": 1, "prompt": "What is a key purpose of merchandising?", "options": ["Make shopping harder.", "Help customers find and compare products.", "Keep all products in storage.", "Avoid using labels."], "correct_option": 1, "explanation": "Merchandising makes product selection clearer."}, {"id": "eacd41c4-b60d-5ec4-93b8-04791003cb56", "position": 2, "prompt": "Two similar products have different SKUs. What should you check?", "options": ["Only package color.", "Which box is heavier.", "The correct product-to-shelf-label match.", "Which shelf is empty."], "correct_option": 2, "explanation": "The item identifier helps prevent incorrect shelf placement."}, {"id": "d203519d-7918-5563-bc01-5a55c9b309de", "position": 3, "prompt": "Which display follows good merchandising practice?", "options": ["One blocking an exit.", "One with unstable stacks.", "One with clear labels and safe access.", "One using a single price for different products."], "correct_option": 2, "explanation": "Displays must be clear, accurate, and safe."}, {"id": "e28007f1-6d0b-546e-8bba-25a986e83bb4", "position": 4, "prompt": "You see an outdated promotional sign. What should you do?", "options": ["Leave it in place.", "Follow the approved sign-correction process.", "Promise the old price without checking.", "Move the sign to another product."], "correct_option": 1, "explanation": "Promotional information must be current and verified."}, {"id": "0333bd55-17d8-50f1-bfe0-a99f129fe6f0", "position": 5, "prompt": "Several customers ask where the same item is located. What should you do?", "options": ["Suggest a clear signage or placement improvement to the lead.", "Change all shelf locations without permission.", "Assume customers are careless.", "Remove the product."], "correct_option": 0, "explanation": "Repeated questions can reveal a merchandising improvement opportunity."}], "catalog": {"course_code": "IM-103", "skill_level": "foundations", "topics": ["Merchandising"], "keywords": ["See the Store Through the Customer’s Eyes", "Match Products, Locations, and Shelf Labels", "Build Useful and Safe Displays", "Maintain Shelves and Seasonal Areas", "Improve Displays Using Customer Questions", "Why this matters", "Lesson content", "Hardware-store example", "What to say or do", "Common mistakes", "When to ask for help", "Key takeaways", "Optional practice — unscored (IM-103-P01)", "Optional practice — unscored (IM-103-P02)", "Optional practice — unscored (IM-103-P03)", "Optional practice — unscored (IM-103-P04)", "Optional practice — unscored (IM-103-P05)", "IM-103-", "P01", "P02", "P03", "P04", "P05", "SKU"], "learning_paths": ["Sales Floor Associate", "Inventory & Merchandising Associate", "Store Manager/Owner"]}}$coursedata$::jsonb;
 c jsonb; l jsonb; q jsonb; target uuid;
begin
 c := payload->'course'; target := (c->>'id')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('coltrain-course:' || target::text, 0));
 if exists(select 1 from public.training_courses where id=target) then
  if not exists(select 1 from public.training_courses t where t.id=target
   and t.slug=c->>'slug' and t.version=(c->>'version')::integer
   and t.title=c->>'title' and t.description=c->>'description'
   and t.category=c->>'category' and t.passing_percent=(c->>'passing_percent')::integer
   and t.owner_organization_id is null) then
   raise exception 'IM-103 course differs; create a new version rather than overwrite';
  end if;
  if (select count(*) from public.training_lessons where course_id=target) <> jsonb_array_length(payload->'lessons')
   or (select count(*) from public.training_questions where course_id=target) <> jsonb_array_length(payload->'questions') then
   raise exception 'IM-103 content differs; draft import was not changed';
  end if;
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   if not exists(select 1 from public.training_lessons t where t.id=(l->>'id')::uuid
    and t.course_id=target and t.position=(l->>'position')::integer
    and t.title=l->>'title' and t.body=l->'body') then
    raise exception 'IM-103 lesson differs; draft import was not changed';
   end if;
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   if not exists(select 1 from public.training_questions t join private.training_answer_keys k on k.question_id=t.id
    where t.id=(q->>'id')::uuid and t.course_id=target and t.position=(q->>'position')::integer
    and t.prompt=q->>'prompt' and t.options=q->'options'
    and k.correct_option=(q->>'correct_option')::integer and k.explanation=q->>'explanation') then
    raise exception 'IM-103 question differs; draft import was not changed';
   end if;
  end loop;
 else
  insert into public.training_courses(id,slug,version,title,description,category,passing_percent,published)
   values(target,c->>'slug',(c->>'version')::integer,c->>'title',c->>'description',c->>'category',(c->>'passing_percent')::integer,false);
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   insert into public.training_lessons(id,course_id,position,title,body)
    values((l->>'id')::uuid,target,(l->>'position')::integer,l->>'title',l->'body');
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   insert into public.training_questions(id,course_id,position,prompt,options)
    values((q->>'id')::uuid,target,(q->>'position')::integer,q->>'prompt',q->'options');
   insert into private.training_answer_keys(question_id,correct_option,explanation)
    values((q->>'id')::uuid,(q->>'correct_option')::integer,q->>'explanation');
  end loop;
 end if;
 -- Optional metadata: imports remain compatible before the catalog migration.
 if to_regclass('public.training_course_catalog') is not null then
  insert into public.training_course_catalog(course_id,course_code,skill_level,topics,keywords,learning_paths)
  values(target,payload->'catalog'->>'course_code',payload->'catalog'->>'skill_level',
   array(select jsonb_array_elements_text(payload->'catalog'->'topics')),
   array(select jsonb_array_elements_text(payload->'catalog'->'keywords')),
   array(select jsonb_array_elements_text(payload->'catalog'->'learning_paths')))
  on conflict(course_id) do nothing;
 end if;
end;
