llet", "text": "Recommending a tool from its appearance alone."}, {"type": "bullet", "text": "Using a cutting tool for a task it was not designed to perform."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask for help with specialized tools, energized systems, and applications requiring professional qualifications."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Screwdrivers turn screws."}, {"type": "bullet", "text": "Ask what the customer needs to do."}, {"type": "bullet", "text": "Ask for help with specialized tools, energized systems, and applications requiring professional qualifications."}, {"type": "heading", "text": "Unscored practice"}, {"type": "paragraph", "text": "HT-102-P01: Before recommending a product, what would you check in this situation? A customer asks for a tool to tighten a hex nut under a sink. You show a correctly sized wrench and ask about clearance before recommending one."}, {"type": "paragraph", "text": "Sample answer: Ask what the customer needs to do. Identify the fastener or material."}, {"type": "paragraph", "text": "Why: A customer may describe a job without knowing the name of the tool. Ask for help with specialized tools, energized systems, and applications requiring professional qualifications."}, {"type": "heading", "text": "Optional workplace activity"}, {"type": "bullet", "text": "None required."}]}, {"id": "83ef3f9b-a512-5e7e-b335-db922f169476", "position": 2, "title": "Choose the Right Size and Fit", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "A correct tool type can still be wrong if it does not fit."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Fit first"}, {"type": "paragraph", "text": "Choose a screwdriver tip, socket, or wrench that matches the fastener type and size. Poor fit can round or strip parts."}, {"type": "heading", "text": "Consider access"}, {"type": "paragraph", "text": "A deep socket, short handle, or different wrench shape may help in a tight area. Check the actual clearance before recommending a specific design."}, {"type": "heading", "text": "Choose by job"}, {"type": "paragraph", "text": "A hand saw must be appropriate for the material. A measuring tool must offer the range and precision the customer needs. Verify tool specifications rather than assuming."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer needs to tighten a bolt behind a cabinet. You ask about the space around the bolt and the head size. You compare tool options without guaranteeing clearance."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Confirm size and shape."}, {"type": "bullet", "text": "Ask about working space."}, {"type": "bullet", "text": "Check packaging for material and tool limits."}, {"type": "bullet", "text": "Encourage a safe fit check."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Using adjustable tools carelessly on a poorly matched head."}, {"type": "bullet", "text": "Choosing by handle color."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Escalate if the customer cannot identify the fastener or if tool use could damage safety-critical equipment."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Choose a screwdriver tip, socket, or wrench that matches the fastener type and size."}, {"type": "bullet", "text": "Confirm size and shape."}, {"type": "bullet", "text": "Escalate if the customer cannot identify the fastener or if tool use could damage safety-critical equipment."}, {"type": "heading", "text": "Unscored practice"}, {"type": "paragraph", "text": "HT-102-P02: Before recommending a product, what would you check in this situation? A customer needs to tighten a bolt behind a cabinet. You ask about the space around the bolt and the head size. You compare tool options without guaranteeing clearance."}, {"type": "paragraph", "text": "Sample answer: Confirm size and shape. Ask about working space."}, {"type": "paragraph", "text": "Why: A correct tool type can still be wrong if it does not fit. Escalate if the customer cannot identify the fastener or if tool use could damage safety-critical equipment."}, {"type": "heading", "text": "Optional workplace activity"}, {"type": "bullet", "text": "None required."}]}, {"id": "bc857cdf-312f-55c5-a925-a393246edfa9", "position": 3, "title": "Measure, Mark, and Check Work", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "A small measuring mistake can waste materials or make parts fail to fit."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Measure carefully"}, {"type": "paragraph", "text": "Start at the correct reference point. Read the unit marks and record the number. Measure again before cutting."}, {"type": "heading", "text": "Keep things straight"}, {"type": "paragraph", "text": "A level checks orientation against level or plumb. A square helps check or mark right angles. Use each tool according to its design."}, {"type": "heading", "text": "Communicate measurements"}, {"type": "paragraph", "text": "Repeat the number and unit. A measurement of 24 inches is not the same as 24 centimeters. Ask whether the measurement is exact or approximate."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer wants a shelf cut to size. You ask whether their measurement includes brackets and have them confirm the unit and finished dimension."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Say the unit with every measurement."}, {"type": "bullet", "text": "Check the reference edge."}, {"type": "bullet", "text": "Measure twice before an irreversible cut."}, {"type": "bullet", "text": "Verify store cutting policies separately."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Mixing units."}, {"type": "bullet", "text": "Measuring from the wrong end of a damaged tape."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask for help with precision layout, building-code questions, and store cutting services."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Start at the correct reference point."}, {"type": "bullet", "text": "Say the unit with every measurement."}, {"type": "bullet", "text": "Ask for help with precision layout, building-code questions, and store cutting services."}, {"type": "heading", "text": "Unscored practice"}, {"type": "paragraph", "text": "HT-102-P03: Before recommending a product, what would you check in this situation? A customer wants a shelf cut to size. You ask whether their measurement includes brackets and have them confirm the unit and finished dimension."}, {"type": "paragraph", "text": "Sample answer: Say the unit with every measurement. Check the reference edge."}, {"type": "paragraph", "text": "Why: A small measuring mistake can waste materials or make parts fail to fit. Ask for help with precision layout, building-code questions, and store cutting services."}, {"type": "heading", "text": "Optional workplace activity"}, {"type": "bullet", "text": "None required."}]}, {"id": "534011a8-9319-5b82-932e-5db613d020ba", "position": 4, "title": "Explain Basic Hand Tool Safety", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Even simple hand tools can injure users if damaged or misused."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Inspect before use"}, {"type": "paragraph", "text": "Look for cracked handles, loose heads, damaged cutting edges, and other defects. Do not use or sell a tool as safe when damage is suspected."}, {"type": "heading", "text": "Use tools as intended"}, {"type": "paragraph", "text": "Wear protective equipment specified by the tool and task. Keep cutting edges away from the body. Secure workpieces when appropriate. Follow manufacturer instructions."}, {"type": "heading", "text": "Know what not to advise"}, {"type": "paragraph", "text": "Do not suggest using ordinary hand tools on live electrical parts. Do not improvise a tool as a lever or striking device beyond its intended use."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer asks if a regular screwdriver can be used on an energized outlet. You do not advise working live. You direct them to a qualified electrician and appropriate safety guidance."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Check tool condition."}, {"type": "bullet", "text": "Explain the intended use."}, {"type": "bullet", "text": "Refer to the manufacturer safety instructions."}, {"type": "bullet", "text": "Stop when a task involves electrical or other serious hazards."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Treating all screwdrivers as safe for electrical work."}, {"type": "bullet", "text": "Ignoring a loose hammer head."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Refer electrical, gas, structural, and other high-risk tasks to qualified professionals."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Look for cracked handles, loose heads, damaged cutting edges, and other defects."}, {"type": "bullet", "text": "Check tool condition."}, {"type": "bullet", "text": "Refer electrical, gas, structural, and other high-risk tasks to qualified professionals."}, {"type": "heading", "text": "Unscored practice"}, {"type": "paragraph", "text": "HT-102-P04: Before recommending a product, what would you check in this situation? A customer asks if a regular screwdriver can be used on an energized outlet. You do not advise working live. You direct them to a qualified electrician and appropriate safety guidance."}, {"type": "paragraph", "text": "Sample answer: Check tool condition. Explain the intended use."}, {"type": "paragraph", "text": "Why: Even simple hand tools can injure users if damaged or misused. Refer electrical, gas, structural, and other high-risk tasks to qualified professionals."}, {"type": "heading", "text": "Optional workplace activity"}, {"type": "bullet", "text": "None required."}]}, {"id": "c74fea21-118e-5192-bf01-5c42f708f919", "position": 5, "title": "Care for and Store Hand Tools", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Well-kept tools are easier to find and less likely to fail unexpectedly."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Clean and dry"}, {"type": "paragraph", "text": "Remove ordinary dirt after use using manufacturer-approved methods. Dry tools before storage when appropriate. Follow instructions for rust prevention."}, {"type": "heading", "text": "Protect edges and moving parts"}, {"type": "paragraph", "text": "Store sharp tools with guards when provided. Keep tools organized to prevent accidental contact and damage. Do not attempt repairs outside approved procedures."}, {"type": "heading", "text": "Know replacement signs"}, {"type": "paragraph", "text": "Damaged handles, cracked sockets, or badly worn drivers may need replacement. Manufacturer guidance determines whether repair is allowed."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer asks how to store hand tools in a damp shed. You suggest a dry, organized location and checking the tool maker’s care guidance for rust prevention."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Recommend a dry storage space."}, {"type": "bullet", "text": "Keep sharp edges protected."}, {"type": "bullet", "text": "Inspect tools before use."}, {"type": "bullet", "text": "Refer damaged tools to appropriate service guidance."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Leaving tools wet in a closed container."}, {"type": "bullet", "text": "Continuing to use a cracked tool."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a supervisor or manufacturer service contact about uncertain repairs or warranty questions."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Remove ordinary dirt after use using manufacturer-approved methods."}, {"type": "bullet", "text": "Recommend a dry storage space."}, {"type": "bullet", "text": "Ask a supervisor or manufacturer service contact about uncertain repairs or warranty questions."}, {"type": "heading", "text": "Unscored practice"}, {"type": "paragraph", "text": "HT-102-P05: Before recommending a product, what would you check in this situation? A customer asks how to store hand tools in a damp shed. You suggest a dry, organized location and checking the tool maker’s care guidance for rust prevention."}, {"type": "paragraph", "text": "Sample answer: Recommend a dry storage space. Keep sharp edges protected."}, {"type": "paragraph", "text": "Why: Well-kept tools are easier to find and less likely to fail unexpectedly. Ask a supervisor or manufacturer service contact about uncertain repairs or warranty questions."}, {"type": "heading", "text": "Optional workplace activity"}, {"type": "bullet", "text": "None required."}]}], "questions": [{"id": "0310389b-69a0-59d3-bf5a-56c0414ae795", "position": 1, "prompt": "Which tool family is commonly used to turn a hex nut?", "options": ["Level", "Wrench", "Tape measure", "Handsaw"], "correct_option": 1, "explanation": "Wrenches are designed to engage matching nut or bolt-head shapes."}, {"id": "c5f6e1ec-28fe-5b60-a68a-3d99be2147aa", "position": 2, "prompt": "A customer has a 10 mm hex-head fastener. What should you check?", "options": ["The matching wrench or socket size", "The most expensive screwdriver", "The hammer weight", "The tape measure color"], "correct_option": 0, "explanation": "Tool size must match the fastener."}, {"id": "a83c26ae-ea12-50f6-b055-e1f2d0ff2454", "position": 3, "prompt": "A customer says a board needs to be “24 long.” What should you ask?", "options": ["What is the price?", "Do you mean 24 inches or another unit?", "Do you need a hammer?", "What is your favorite brand?"], "correct_option": 1, "explanation": "A measurement without a unit is incomplete."}, {"id": "71321615-9bbf-50be-b4eb-415bb8f74bb1", "position": 4, "prompt": "A customer wants to use a standard screwdriver on live wiring. What is the safest response?", "options": ["Tell them it is fine", "Suggest turning the screwdriver faster", "Do not advise live work; refer to a qualified professional", "Recommend a larger screwdriver"], "correct_option": 2, "explanation": "Working on energized wiring presents serious hazards."}, {"id": "2bf793bc-f764-5a09-88b3-0c03add637ee", "position": 5, "prompt": "A hammer handle is cracked. What is the best action?", "options": ["Keep using it", "Tape it and guarantee safety", "Stop using it and follow repair or replacement guidance", "Store it with the crack hidden"], "correct_option": 2, "explanation": "A cracked handle can make a striking tool unsafe."}], "catalog": {"course_code": "HT-102", "skill_level": "foundations", "topics": ["Hand Tools"], "keywords": ["Know the Main Hand Tool Families", "Choose the Right Size and Fit", "Measure, Mark, and Check Work", "Explain Basic Hand Tool Safety", "Care for and Store Hand Tools", "Why this matters", "Lesson content", "Driving and turning", "Measuring and marking", "Cutting and striking", "Hardware-store example", "What to say or do", "Common mistakes", "When to ask for help", "Key takeaways", "Unscored practice", "Optional workplace activity", "Fit first", "Consider access", "Choose by job", "Measure carefully", "Keep things straight", "Communicate measurements", "Inspect before use", "Use tools as intended", "Know what not to advise", "Clean and dry", "Protect edges and moving parts", "Know replacement signs", "HT-102-", "P01", "P02", "P03", "P04", "P05"], "learning_paths": ["Sales Floor Associate"]}}$coursedata$::jsonb;
 c jsonb; l jsonb; q jsonb; target uuid;
begin
 c := payload->'course'; target := (c->>'id')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('coltrain-course:' || target::text, 0));
 if exists(select 1 from public.training_courses where id=target) then
  if not exists(select 1 from public.training_courses t where t.id=target
   and t.slug=c->>'slug' and t.version=(c->>'version')::integer
   and t.title=c->>'title' and t.description=c->>'description'
   and t.category=c->>'category' and t.passing_percent=(c->>'passing_percent')::integer
   and t.owner_organization_id is null) then
   raise exception 'HT-102 course differs; create a new version rather than overwrite';
  end if;
  if (select count(*) from public.training_lessons where course_id=target) <> jsonb_array_length(payload->'lessons')
   or (select count(*) from public.training_questions where course_id=target) <> jsonb_array_length(payload->'questions') then
   raise exception 'HT-102 content differs; draft import was not changed';
  end if;
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   if not exists(select 1 from public.training_lessons t where t.id=(l->>'id')::uuid
    and t.course_id=target and t.position=(l->>'position')::integer
    and t.title=l->>'title' and t.body=l->'body') then
    raise exception 'HT-102 lesson differs; draft import was not changed';
   end if;
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   if not exists(select 1 from public.training_questions t join private.training_answer_keys k on k.question_id=t.id
    where t.id=(q->>'id')::uuid and t.course_id=target and t.position=(q->>'position')::integer
    and t.prompt=q->>'prompt' and t.options=q->'options'
    and k.correct_option=(q->>'correct_option')::integer and k.explanation=q->>'explanation') then
    raise exception 'HT-102 question differs; draft import was not changed';
   end if;
  end loop;
 else
  insert into public.training_courses(id,slug,version,title,description,category,passing_percent,published)
   values(target,c->>'slug',(c->>'version')::integer,c->>'title',c->>'description',c->>'category',(c->>'passing_percent')::integer,false);
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   insert into public.training_lessons(id,course_id,position,title,body)
    values((l->>'id')::uuid,target,(l->>'position')::integer,l->>'title',l->'body');
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   insert into public.training_questions(id,course_id,position,prompt,options)
    values((q->>'id')::uuid,target,(q->>'position')::integer,q->>'prompt',q->'options');
   insert into private.training_answer_keys(question_id,correct_option,explanation)
    values((q->>'id')::uuid,(q->>'correct_option')::integer,q->>'explanation');
  end loop;
 end if;
 -- Optional metadata: imports remain compatible before the catalog migration.
 if to_regclass('public.training_course_catalog') is not null then
  insert into public.training_course_catalog(course_id,course_code,skill_level,topics,keywords,learning_paths)
  values(target,payload->'catalog'->>'course_code',payload->'catalog'->>'skill_level',
   array(select jsonb_array_elements_text(payload->'catalog'->'topics')),
   array(select jsonb_array_elements_text(payload->'catalog'->'keywords')),
   array(select jsonb_array_elements_text(payload->'catalog'->'learning_paths')))
  on conflict(course_id) do nothing;
 end if;
end;
