 payload jsonb := $coursedata${"course": {"id": "bbf2069f-95c3-5b39-8ce2-919dcb455eb8", "slug": "ht-103-power-tools-fundamentals", "version": 1, "title": "Power Tools Fundamentals", "description": "Recognize power tool categories, compare key features, and know essential safety boundaries.", "category": "Hardware & Tools", "passing_percent": 80}, "lessons": [{"id": "5892cbbd-7c52-5675-ab1e-826a6855b790", "position": 1, "title": "Recognize Common Power Tools", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Customers may ask for a tool by its appearance instead of the task it performs."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Drilling and driving"}, {"type": "paragraph", "text": "Drills create holes with suitable bits. Drivers install or remove compatible fasteners. Impact drivers are a distinct category with different operating characteristics."}, {"type": "heading", "text": "Cutting and shaping"}, {"type": "paragraph", "text": "Circular saws and jigsaws cut suitable materials with the correct blade. Sanders remove or smooth surface material. Grinders have different hazards and uses."}, {"type": "heading", "text": "Power sources"}, {"type": "paragraph", "text": "Corded tools use mains electricity. Cordless tools use compatible battery systems. Do not assume batteries, chargers, or accessories are interchangeable."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer wants a tool to assemble furniture. You ask what fasteners are included and whether the instructions recommend a hand tool or powered driver."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Ask what task the tool must perform."}, {"type": "bullet", "text": "Identify the material."}, {"type": "bullet", "text": "Check accessory and power requirements."}, {"type": "bullet", "text": "Show the relevant tool category."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Calling every driver a drill."}, {"type": "bullet", "text": "Assuming all batteries fit all tools."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Refer tool-specific operation and hazardous applications to manufacturer instructions or a qualified specialist."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Drills create holes with suitable bits."}, {"type": "bullet", "text": "Ask what task the tool must perform."}, {"type": "bullet", "text": "Refer tool-specific operation and hazardous applications to manufacturer instructions or a qualified specialist."}, {"type": "heading", "text": "Unscored practice"}, {"type": "paragraph", "text": "HT-103-P01: Before recommending a product, what would you check in this situation? A customer wants a tool to assemble furniture. You ask what fasteners are included and whether the instructions recommend a hand tool or powered driver."}, {"type": "paragraph", "text": "Sample answer: Ask what task the tool must perform. Identify the material."}, {"type": "paragraph", "text": "Why: Customers may ask for a tool by its appearance instead of the task it performs. Refer tool-specific operation and hazardous applications to manufacturer instructions or a qualified specialist."}, {"type": "heading", "text": "Optional workplace activity"}, {"type": "bullet", "text": "None required."}]}, {"id": "1dd86d0b-daf6-5fc1-8e5f-3924ad295db3", "position": 2, "title": "Compare Corded and Cordless Options", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "The best power source depends on the work area and the tool requirements."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Corded tools"}, {"type": "paragraph", "text": "Corded tools need an appropriate electrical supply and may suit work where a suitable outlet is available. Cord management is part of safe use."}, {"type": "heading", "text": "Cordless tools"}, {"type": "paragraph", "text": "Cordless tools use a battery and charger approved for the tool. Runtime varies by task, battery, and tool. Do not promise a fixed runtime without verified data."}, {"type": "heading", "text": "Ask useful questions"}, {"type": "paragraph", "text": "Where will the tool be used? Is power available? How often will it be used? Does the customer already own a compatible battery platform?"}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer needs a drill for projects around a large property. You ask whether outlets are nearby and whether they already own batteries in a particular tool system."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Ask about access to power."}, {"type": "bullet", "text": "Check existing battery systems."}, {"type": "bullet", "text": "Compare manufacturer-listed specifications."}, {"type": "bullet", "text": "Explain tradeoffs without making guarantees."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Assuming higher voltage always means the better tool."}, {"type": "bullet", "text": "Mixing unapproved batteries and chargers."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask for help with electrical supply, battery compatibility, or tool selection for hazardous environments."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Corded tools need an appropriate electrical supply and may suit work where a suitable outlet is available."}, {"type": "bullet", "text": "Ask about access to power."}, {"type": "bullet", "text": "Ask for help with electrical supply, battery compatibility, or tool selection for hazardous environments."}, {"type": "heading", "text": "Unscored practice"}, {"type": "paragraph", "text": "HT-103-P02: Before recommending a product, what would you check in this situation? A customer needs a drill for projects around a large property. You ask whether outlets are nearby and whether they already own batteries in a particular tool system."}, {"type": "paragraph", "text": "Sample answer: Ask about access to power. Check existing battery systems."}, {"type": "paragraph", "text": "Why: The best power source depends on the work area and the tool requirements. Ask for help with electrical supply, battery compatibility, or tool selection for hazardous environments."}, {"type": "heading", "text": "Optional workplace activity"}, {"type": "bullet", "text": "None required."}]}, {"id": "9b70841a-6f4a-580d-bf13-458051c2de86", "position": 3, "title": "Understand Bits, Blades, and Accessories", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "An incorrect accessory can damage a project or create serious injury risk."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Match the connection"}, {"type": "paragraph", "text": "Drill bits, saw blades, and other accessories use specific shanks, mounts, or arbor sizes. Check the tool and accessory documentation."}, {"type": "heading", "text": "Match the material"}, {"type": "paragraph", "text": "A blade or bit suitable for wood may not be suitable for masonry or metal. Verify intended materials and limitations on packaging."}, {"type": "heading", "text": "Check operating limits"}, {"type": "paragraph", "text": "Accessories may have speed or other ratings. Never recommend an accessory that exceeds or conflicts with tool instructions. Guards and safety devices must remain in place."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer brings a photo of a circular saw and asks for a blade. You ask for the exact model and check the blade diameter, arbor, material, and tool instructions."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Find the exact tool model."}, {"type": "bullet", "text": "Check mounting dimensions."}, {"type": "bullet", "text": "Verify intended material and operating limits."}, {"type": "bullet", "text": "Escalate uncertain matches."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Choosing a blade by diameter alone."}, {"type": "bullet", "text": "Suggesting removal of a guard to fit an accessory."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Escalate all unclear accessory fit, speed ratings, and guard questions to manufacturer documentation or a qualified specialist."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Drill bits, saw blades, and other accessories use specific shanks, mounts, or arbor sizes."}, {"type": "bullet", "text": "Find the exact tool model."}, {"type": "bullet", "text": "Escalate all unclear accessory fit, speed ratings, and guard questions to manufacturer documentation or a qualified specialist."}, {"type": "heading", "text": "Unscored practice"}, {"type": "paragraph", "text": "HT-103-P03: Before recommending a product, what would you check in this situation? A customer brings a photo of a circular saw and asks for a blade. You ask for the exact model and check the blade diameter, arbor, material, and tool instructions."}, {"type": "paragraph", "text": "Sample answer: Find the exact tool model. Check mounting dimensions."}, {"type": "paragraph", "text": "Why: An incorrect accessory can damage a project or create serious injury risk. Escalate all unclear accessory fit, speed ratings, and guard questions to manufacturer documentation or a qualified specialist."}, {"type": "heading", "text": "Optional workplace activity"}, {"type": "bullet", "text": "None required."}]}, {"id": "4255860e-79c5-5f0b-b2be-2912236ae69e", "position": 4, "title": "Teach Safety Before Features", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Power tools can cause serious injuries. Sales advice must not replace training or instructions."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Read instructions first"}, {"type": "paragraph", "text": "Manufacturer manuals explain guards, personal protective equipment, setup, and operation. Never tell customers to bypass safeguards."}, {"type": "heading", "text": "Prevent accidental starts"}, {"type": "paragraph", "text": "Tools must be handled according to manufacturer guidance when changing accessories, transporting, or storing them. Unplugging or removing the battery may be required depending on the tool and task."}, {"type": "heading", "text": "Recognize high-risk jobs"}, {"type": "paragraph", "text": "Electrical, structural, overhead, and unfamiliar cutting tasks may require qualified help. Retail associates should not provide unverified operating or installation instructions."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer asks whether they can remove a saw guard for a difficult cut. You explain that safety devices should not be bypassed and refer to the tool manual and a qualified professional."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Point customers to the manual."}, {"type": "bullet", "text": "Discuss required protective equipment as specified."}, {"type": "bullet", "text": "Never suggest defeating guards."}, {"type": "bullet", "text": "Stop and refer high-risk questions."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Demonstrating an unfamiliar tool without authorization."}, {"type": "bullet", "text": "Treating safety labels as optional."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a supervisor before any in-store demonstration; refer complex or high-risk operation to trained professionals."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Manufacturer manuals explain guards, personal protective equipment, setup, and operation."}, {"type": "bullet", "text": "Point customers to the manual."}, {"type": "bullet", "text": "Ask a supervisor before any in-store demonstration; refer complex or high-risk operation to trained professionals."}, {"type": "heading", "text": "Unscored practice"}, {"type": "paragraph", "text": "HT-103-P04: Before recommending a product, what would you check in this situation? A customer asks whether they can remove a saw guard for a difficult cut. You explain that safety devices should not be bypassed and refer to the tool manual and a qualified professional."}, {"type": "paragraph", "text": "Sample answer: Point customers to the manual. Discuss required protective equipment as specified."}, {"type": "paragraph", "text": "Why: Power tools can cause serious injuries. Sales advice must not replace training or instructions. Ask a supervisor before any in-store demonstration; refer complex or high-risk operation to trained professionals."}, {"type": "heading", "text": "Optional workplace activity"}, {"type": "bullet", "text": "None required."}]}, {"id": "628e7f27-9ef2-5933-adfb-9f0262a2e305", "position": 5, "title": "Help Customers Choose and Maintain Tools", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "A complete recommendation includes the tool, compatible accessories, and realistic care needs."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Match the project and frequency"}, {"type": "paragraph", "text": "Ask what tasks the customer will do and how often. Compare manufacturer-listed capacity and included items."}, {"type": "heading", "text": "Check the box"}, {"type": "paragraph", "text": "Some tools are sold without batteries or chargers. Verify package contents and compatible accessories before checkout."}, {"type": "heading", "text": "Support care and service"}, {"type": "paragraph", "text": "Explain that cleaning, storage, inspection, and maintenance follow the owner’s manual. Do not invent warranty coverage or service promises."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer selects a cordless drill kit. You check whether the box includes a battery, charger, and bits. You explain where to find the owner’s manual and store service information if applicable."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Ask about intended jobs."}, {"type": "bullet", "text": "Verify box contents."}, {"type": "bullet", "text": "Confirm compatible accessories."}, {"type": "bullet", "text": "Refer maintenance and warranty questions to verified documentation."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Assuming a battery is included."}, {"type": "bullet", "text": "Guaranteeing a warranty outcome."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Refer uncertain repairs, service eligibility, and warranty coverage to the store manager or manufacturer."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Ask what tasks the customer will do and how often."}, {"type": "bullet", "text": "Ask about intended jobs."}, {"type": "bullet", "text": "Refer uncertain repairs, service eligibility, and warranty coverage to the store manager or manufacturer."}, {"type": "heading", "text": "Unscored practice"}, {"type": "paragraph", "text": "HT-103-P05: Before recommending a product, what would you check in this situation? A customer selects a cordless drill kit. You check whether the box includes a battery, charger, and bits. You explain where to find the owner’s manual and store service information if applicable."}, {"type": "paragraph", "text": "Sample answer: Ask about intended jobs. Verify box contents."}, {"type": "paragraph", "text": "Why: A complete recommendation includes the tool, compatible accessories, and realistic care needs. Refer uncertain repairs, service eligibility, and warranty coverage to the store manager or manufacturer."}, {"type": "heading", "text": "Optional workplace activity"}, {"type": "bullet", "text": "None required."}]}], "questions": [{"id": "79f5b8c3-3998-542f-98b9-625740fe99fa", "position": 1, "prompt": "A customer wants to drill holes in wood. Which tool category is usually relevant?", "options": ["Drill with a suitable bit", "Paint roller", "Tape measure", "Garden rake"], "correct_option": 0, "explanation": "A drill with an appropriate bit is designed to create holes."}, {"id": "65621c76-2026-5073-82a6-7009598b408f", "position": 2, "prompt": "What is most important when choosing a replacement battery?", "options": ["Matching its color", "Manufacturer-approved compatibility with the tool and charger", "Buying the heaviest battery", "Choosing any battery with similar shape"], "correct_option": 1, "explanation": "Battery systems require verified compatibility."}, {"id": "903863c3-7a87-59fe-a3a9-2f2e15b49169", "position": 3, "prompt": "A customer needs a replacement saw blade. What should you verify?", "options": ["Only the blade color", "Tool model, blade size, arbor, and intended material", "The brand logo only", "Which blade is on sale"], "correct_option": 1, "explanation": "A safe accessory match needs several verified specifications."}, {"id": "474b5c80-ecf9-5c1a-9318-8fb106de526d", "position": 4, "prompt": "A customer wants to remove a saw guard. What should you say?", "options": ["Remove it carefully", "A guard is optional", "Do not bypass safety devices; follow the manual", "Use a bigger blade instead"], "correct_option": 2, "explanation": "Manufacturer safeguards must remain in use as directed."}, {"id": "899ea26b-277e-53c3-b56e-f0d1fd85def3", "position": 5, "prompt": "A customer chooses a cordless tool. What should you check before checkout?", "options": ["Only its color", "Whether the package includes the needed battery and charger", "Whether the box is large", "Whether the tool is the newest"], "correct_option": 1, "explanation": "Package contents and compatibility affect whether the customer can use the tool."}], "catalog": {"course_code": "HT-103", "skill_level": "foundations", "topics": ["Power Tools"], "keywords": ["Recognize Common Power Tools", "Compare Corded and Cordless Options", "Understand Bits, Blades, and Accessories", "Teach Safety Before Features", "Help Customers Choose and Maintain Tools", "Why this matters", "Lesson content", "Drilling and driving", "Cutting and shaping", "Power sources", "Hardware-store example", "What to say or do", "Common mistakes", "When to ask for help", "Key takeaways", "Unscored practice", "Optional workplace activity", "Corded tools", "Cordless tools", "Ask useful questions", "Match the connection", "Match the material", "Check operating limits", "Read instructions first", "Prevent accidental starts", "Recognize high-risk jobs", "Match the project and frequency", "Check the box", "Support care and service", "HT-103-", "P01", "P02", "P03", "P04", "P05"], "learning_paths": ["Sales Floor Associate"]}}$coursedata$::jsonb;
 c jsonb; l jsonb; q jsonb; target uuid;
begin
 c := payload->'course'; target := (c->>'id')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('coltrain-course:' || target::text, 0));
 if exists(select 1 from public.training_courses where id=target) then
  if not exists(select 1 from public.training_courses t where t.id=target
   and t.slug=c->>'slug' and t.version=(c->>'version')::integer
   and t.title=c->>'title' and t.description=c->>'description'
   and t.category=c->>'category' and t.passing_percent=(c->>'passing_percent')::integer
   and t.owner_organization_id is null) then
   raise exception 'HT-103 course differs; create a new version rather than overwrite';
  end if;
  if (select count(*) from public.training_lessons where course_id=target) <> jsonb_array_length(payload->'lessons')
   or (select count(*) from public.training_questions where course_id=target) <> jsonb_array_length(payload->'questions') then
   raise exception 'HT-103 content differs; draft import was not changed';
  end if;
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   if not exists(select 1 from public.training_lessons t where t.id=(l->>'id')::uuid
    and t.course_id=target and t.position=(l->>'position')::integer
    and t.title=l->>'title' and t.body=l->'body') then
    raise exception 'HT-103 lesson differs; draft import was not changed';
   end if;
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   if not exists(select 1 from public.training_questions t join private.training_answer_keys k on k.question_id=t.id
    where t.id=(q->>'id')::uuid and t.course_id=target and t.position=(q->>'position')::integer
    and t.prompt=q->>'prompt' and t.options=q->'options'
    and k.correct_option=(q->>'correct_option')::integer and k.explanation=q->>'explanation') then
    raise exception 'HT-103 question differs; draft import was not changed';
   end if;
  end loop;
 else
  insert into public.training_courses(id,slug,version,title,description,category,passing_percent,published)
   values(target,c->>'slug',(c->>'version')::integer,c->>'title',c->>'description',c->>'category',(c->>'passing_percent')::integer,false);
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   insert into public.training_lessons(id,course_id,position,title,body)
    values((l->>'id')::uuid,target,(l->>'position')::integer,l->>'title',l->'body');
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   insert into public.training_questions(id,course_id,position,prompt,options)
    values((q->>'id')::uuid,target,(q->>'position')::integer,q->>'prompt',q->'options');
   insert into private.training_answer_keys(question_id,correct_option,explanation)
    values((q->>'id')::uuid,(q->>'correct_option')::integer,q->>'explanation');
  end loop;
 end if;
 -- Optional metadata: imports remain compatible before the catalog migration.
 if to_regclass('public.training_course_catalog') is not null then
  insert into public.training_course_catalog(course_id,course_code,skill_level,topics,keywords,learning_paths)
  values(target,payload->'catalog'->>'course_code',payload->'catalog'->>'skill_level',
   array(select jsonb_array_elements_text(payload->'catalog'->'topics')),
   array(select jsonb_array_elements_text(payload->'catalog'->'keywords')),
   array(select jsonb_array_elements_text(payload->'catalog'->'learning_paths')))
  on conflict(course_id) do nothing;
 end if;
end;
$courseimport$;
do $courseimport$
declare
 payload jsonb := $coursedata${"course": {"id": "e4853d09-ac6f-59ca-8a10-252bd4c93fe6", "slug": "hb-101-electrical-lighting-fundamentals", "version": 1, "title": "Electrical & Lighting Fundamentals", "description": "Build basic retail product knowledge and safe customer guidance for electrical and lighting.", "category": "Home Systems & Building Materials", "passing_percent": 80}, "lessons": [{"id": "a6a8592d-d5ed-5b41-80fa-d7190716f524", "position": 1, "title": "Recognize Common Electrical Products", "body": [{"type": "paragraph", "text": "Why this matters: Customers often know what stopped working but not the name of the part."}, {"type": "heading", "text": "Know the basics"}, {"type": "paragraph", "text": "Electrical aisles may include switches, receptacles, cover plates, cords, connectors, breakers, and lighting products. A receptacle is the outlet where a plug connects. A switch controls a circuit or device. These items have different purposes."}, {"type": "heading", "text": "Check before recommending"}, {"type": "paragraph", "text": "Look for the product label and any rating printed on the package. A product that looks similar may have different electrical ratings or installation requirements. Do not assume that matching color or shape means matching function."}, {"type": "heading", "text": "Put it into practice"}, {"type": "paragraph", "text": "Your job is to identify the category and gather information. Never tell a customer to work on energized equipment or bypass a protective device."}, {"type": "paragraph", "text": "Hardware-store example: A customer asks for “the thing the lamp plugs into.” Ask whether they mean a wall receptacle, an extension cord, or a power strip before walking them to an aisle."}, {"type": "paragraph", "text": "What to say or do: Ask: “What are you connecting, and can you describe the part you need?” Show labeled product categories without claiming compatibility."}, {"type": "paragraph", "text": "Common mistakes: Handing over a look-alike electrical part without checking its label."}, {"type": "paragraph", "text": "When to ask for help: If the customer describes damaged wiring, sparking, heat, or repeated breaker trips, stop product matching and direct them to qualified help."}, {"type": "heading", "text": "Key takeaways:"}, {"type": "bullet", "text": "Electrical aisles may include switches, receptacles, cover plates, cords, connectors, breakers, and lighting products."}, {"type": "bullet", "text": "Look for the product label and any rating printed on the package."}, {"type": "bullet", "text": "Your job is to identify the category and gather information."}, {"type": "paragraph", "text": "Unscored practice HB-101-P01: Which detail best distinguishes a switch from a receptacle?"}, {"type": "bullet", "text": "A. A switch controls; a receptacle accepts a plug"}, {"type": "bullet", "text": "B. They are interchangeable"}, {"type": "bullet", "text": "C. A receptacle is always outdoors"}, {"type": "bullet", "text": "D. Both are types of light bulbs"}, {"type": "paragraph", "text": "Answer: A. Explanation: A switch controls a circuit or device. A receptacle provides a connection point for a plug."}]}, {"id": "459b1b96-ede1-5bf5-96c7-e894bc22cc7a", "position": 2, "title": "Read Electrical Labels Without Guessing", "body": [{"type": "paragraph", "text": "Why this matters: Similar-looking electrical products may be designed for different conditions."}, {"type": "heading", "text": "Know the basics"}, {"type": "paragraph", "text": "Packages may show voltage, amperage, wattage, location rating, or compatible equipment. Voltage describes electrical potential. Amperage relates to current. Wattage describes power use."}, {"type": "heading", "text": "Check before recommending"}, {"type": "paragraph", "text": "These values are not a license to choose a replacement by appearance. A correct choice also depends on the existing circuit, equipment, installation, and applicable codes."}, {"type": "heading", "text": "Put it into practice"}, {"type": "paragraph", "text": "Point to the label, read the exact wording, and compare it with verified requirements. If the customer cannot confirm those requirements, do not guess."}, {"type": "paragraph", "text": "Hardware-store example: A customer wants a replacement breaker based only on its color. Explain that the exact panel and manufacturer compatibility must be confirmed."}, {"type": "paragraph", "text": "What to say or do: Say: “Let’s find the model information and check the manufacturer’s listed compatibility.”"}, {"type": "paragraph", "text": "Common mistakes: Claiming that any breaker with the same amperage will fit."}, {"type": "paragraph", "text": "When to ask for help: Escalate breaker selection, wiring alterations, unclear ratings, and code questions to a qualified electrician or authorized specialist."}, {"type": "heading", "text": "Key takeaways:"}, {"type": "bullet", "text": "Packages may show voltage, amperage, wattage, location rating, or compatible equipment."}, {"type": "bullet", "text": "These values are not a license to choose a replacement by appearance."}, {"type": "bullet", "text": "Point to the label, read the exact wording, and compare it with verified requirements."}, {"type": "paragraph", "text": "Unscored practice HB-101-P02: What should you do when a customer knows only a breaker’s amperage?"}, {"type": "bullet", "text": "A. Choose any breaker with that number"}, {"type": "bullet", "text": "B. Match by color"}, {"type": "bullet", "text": "C. Verify the panel and manufacturer compatibility"}, {"type": "bullet", "text": "D. Recommend the least expensive option"}, {"type": "paragraph", "text": "Answer: C. Explanation: Amperage alone does not establish panel compatibility."}]}, {"id": "850e538d-60f3-57ab-8c32-8a25a9305c60", "position": 3, "title": "Understand Common Lighting Choices", "body": [{"type": "paragraph", "text": "Why this matters: A customer may need a specific light output, fit, or use location."}, {"type": "heading", "text": "Know the basics"}, {"type": "paragraph", "text": "Lighting labels often list lumens, watts, color temperature, and base type. Lumens describe light output. Watts describe energy use. Color temperature describes whether the light appears warmer or cooler."}, {"type": "heading", "text": "Check before recommending"}, {"type": "paragraph", "text": "Check the fixture label for bulb type, maximum permitted wattage, and other restrictions. A bulb must physically fit and meet the fixture’s instructions. An enclosed fixture may require a bulb rated for enclosed use."}, {"type": "heading", "text": "Put it into practice"}, {"type": "paragraph", "text": "Dimmable lamps and dimmer controls must be compatible. Outdoor or damp locations require products rated for that environment."}, {"type": "paragraph", "text": "Hardware-store example: A customer says their new LED bulb flickers on a dimmer. Ask for the bulb and dimmer models instead of promising that a different wattage will fix it."}, {"type": "paragraph", "text": "What to say or do: Ask: “Is this on a dimmer? Is the fixture enclosed? What base does your current bulb use?”"}, {"type": "paragraph", "text": "Common mistakes: Choosing a bulb using only the old bulb’s wattage."}, {"type": "paragraph", "text": "When to ask for help: Refer uncertain fixture restrictions or dimmer compatibility to manufacturer documentation or qualified help."}, {"type": "heading", "text": "Key takeaways:"}, {"type": "bullet", "text": "Lighting labels often list lumens, watts, color temperature, and base type."}, {"type": "bullet", "text": "Check the fixture label for bulb type, maximum permitted wattage, and other restrictions."}, {"type": "bullet", "text": "Dimmable lamps and dimmer controls must be compatible."}, {"type": "paragraph", "text": "Unscored practice HB-101-P03: Which label most directly describes how much light a bulb produces?"}, {"type": "bullet", "text": "A. Lumens"}, {"type": "bullet", "text": "B. Watts"}, {"type": "bullet", "text": "C. Package weight"}, {"type": "bullet", "text": "D. Brand color"}, {"type": "paragraph", "text": "Answer: A. Explanation: Lumens measure light output. Watts describe power use."}]}, {"id": "7f79ce12-f62f-5fd1-a55a-ce47192e64cc", "position": 4, "title": "Match Products to Location and Use", "body": [{"type": "paragraph", "text": "Why this matters: An indoor product may be unsafe in a wet or exposed location."}, {"type": "heading", "text": "Know the basics"}, {"type": "paragraph", "text": "Product packages may specify dry, damp, or wet locations. These labels are not interchangeable. Ask where the item will be installed and whether it will face rain, moisture, or other exposure."}, {"type": "heading", "text": "Check before recommending"}, {"type": "paragraph", "text": "Extension cords and power strips have intended uses and ratings. Do not suggest running cords through walls, hiding them under rugs, or using them as permanent wiring."}, {"type": "heading", "text": "Put it into practice"}, {"type": "paragraph", "text": "When a customer requests a solution for a bathroom, garage, porch, or outdoor project, the location matters as much as the product name."}, {"type": "paragraph", "text": "Hardware-store example: A customer wants a porch light. Ask whether the fixture will be directly exposed to rain and confirm the manufacturer’s location rating."}, {"type": "paragraph", "text": "What to say or do: Say: “Let’s check the package for the installation location it permits.”"}, {"type": "paragraph", "text": "Common mistakes: Assuming a product is outdoor-rated because it looks sturdy."}, {"type": "paragraph", "text": "When to ask for help: Ask a qualified electrician about wiring, circuit design, grounding, and code compliance."}, {"type": "heading", "text": "Key takeaways:"}, {"type": "bullet", "text": "Product packages may specify dry, damp, or wet locations."}, {"type": "bullet", "text": "Extension cords and power strips have intended uses and ratings."}, {"type": "bullet", "text": "When a customer requests a solution for a bathroom, garage, porch, or outdoor project, the location matters as much as the product name."}, {"type": "paragraph", "text": "Unscored practice HB-101-P04: What is the best first question about an outdoor light fixture?"}, {"type": "bullet", "text": "A. Which color sells most?"}, {"type": "bullet", "text": "B. Will the fixture be exposed to rain or moisture?"}, {"type": "bullet", "text": "C. Is it on sale?"}, {"type": "bullet", "text": "D. Can it use any bulb?"}, {"type": "paragraph", "text": "Answer: B. Explanation: Location exposure determines which manufacturer rating must be checked."}]}, {"id": "67a02b46-a797-5eac-a1fc-2bf77414710a", "position": 5, "title": "Know When Electrical Questions Need an Expert", "body": [{"type": "paragraph", "text": "Why this matters: Electrical mistakes can cause fire, shock, or injury."}, {"type": "heading", "text": "Know the basics"}, {"type": "paragraph", "text": "Employees can help locate packaged products and explain terms shown on labels. They should not diagnose live wiring, instruct customers to modify panels, or promise that a repair is code-compliant."}, {"type": "heading", "text": "Check before recommending"}, {"type": "paragraph", "text": "Listen for warning signs: burning smells, warm outlets, sparking, repeated tripping, water near electrical equipment, or exposed conductors. Do not suggest trial-and-error repairs."}, {"type": "heading", "text": "Put it into practice"}, {"type": "paragraph", "text": "Explain the limit without dismissing the customer. Summarize what you know and recommend a licensed electrician or appropriate emergency response for immediate danger."}, {"type": "paragraph", "text": "Hardware-store example: A customer reports an outlet that sparked and smells burned. Do not sell a replacement outlet as a complete solution."}, {"type": "paragraph", "text": "What to say or do: Say: “That could be hazardous. Please stop using it and contact a qualified electrician. If there is immediate danger, follow emergency guidance.”"}, {"type": "paragraph", "text": "Common mistakes: Treating a potentially dangerous symptom as a simple parts sale."}, {"type": "paragraph", "text": "When to ask for help: Escalate hazards immediately according to store policy; use emergency services for an active emergency."}, {"type": "heading", "text": "Key takeaways:"}, {"type": "bullet", "text": "Employees can help locate packaged products and explain terms shown on labels."}, {"type": "bullet", "text": "Listen for warning signs: burning smells, warm outlets, sparking, repeated tripping, water near electrical equipment, or exposed conductors."}, {"type": "bullet", "text": "Explain the limit without dismissing the customer."}, {"type": "paragraph", "text": "Unscored practice HB-101-P05: A customer reports a hot outlet with a burning smell. What is the best response?"}, {"type": "bullet", "text": "A. Suggest a larger power strip"}, {"type": "bullet", "text": "B. Tell them to keep testing it"}, {"type": "bullet", "text": "C. Advise stopping use and seeking qualified help"}, {"type": "bullet", "text": "D. Offer a bulb instead"}, {"type": "paragraph", "text": "Answer: C. Explanation: Heat and burning smells are warning signs; a retail employee should not diagnose or prescribe a repair."}]}], "questions": [{"id": "254c8707-8542-54e3-924e-5bee3d668916", "position": 1, "prompt": "Which response best follows this lesson when a customer needs help? Situation: A customer asks for “the thing the lamp plugs into.” Ask whether they mean a wall receptacle, an extension cord, or a power strip before walking them to an aisle.", "options": ["Choose by appearance without checking details.", "Promise compatibility without reading product instructions.", "Ask: “What are you connecting, and can you describe the part you need?” Show labeled product categories without claiming compatibility.", "Ignore the customer’s application and select a popular item."], "correct_option": 2, "explanation": "Ask: “What are you connecting, and can you describe the part you need?” Show labeled product categories without claiming compatibility. A switch controls a circuit or device. A receptacle provides a connection point for a plug. The other choices skip verification or necessary safety checks."}, {"id": "21f42eb6-750b-5945-8e68-bcf9c5b65513", "position": 2, "prompt": "What is the safest way to confirm the right product? Situation: A customer wants a replacement breaker based only on its color. Explain that the exact panel and manufacturer compatibility must be confirmed.", "options": ["Choose by appearance without checking details.", "Promise compatibility without reading product instructions.", "Ignore the customer’s application and select a popular item.", "Say: “Let’s find the model information and check the manufacturer’s listed compatibility.”"], "correct_option": 3, "explanation": "Say: “Let’s find the model information and check the manufacturer’s listed compatibility.” Amperage alone does not establish panel compatibility. The other choices skip verification or necessary safety checks."}, {"id": "dcaab8e0-9794-5e26-8670-4d912d3f87fe", "position": 3, "prompt": "Which approach best avoids a mistaken recommendation? Situation: A customer says their new LED bulb flickers on a dimmer. Ask for the bulb and dimmer models instead of promising that a different wattage will fix it.", "options": ["Ask: “Is this on a dimmer? Is the fixture enclosed? What base does your current bulb use?”", "Choose by appearance without checking details.", "Promise compatibility without reading product instructions.", "Ignore the customer’s application and select a popular item."], "correct_option": 0, "explanation": "Ask: “Is this on a dimmer? Is the fixture enclosed? What base does your current bulb use?” Lumens measure light output. Watts describe power use. The other choices skip verification or necessary safety checks."}, {"id": "08aaa50e-7e11-5b78-9cb9-8e805666e89f", "position": 4, "prompt": "What should an employee do when product requirements are uncertain? Situation: A customer wants a porch light. Ask whether the fixture will be directly exposed to rain and confirm the manufacturer’s location rating.", "options": ["Choose by appearance without checking details.", "Say: “Let’s check the package for the installation location it permits.”", "Promise compatibility without reading product instructions.", "Ignore the customer’s application and select a popular item."], "correct_option": 1, "explanation": "Say: “Let’s check the package for the installation location it permits.” Location exposure determines which manufacturer rating must be checked. The other choices skip verification or necessary safety checks."}, {"id": "2f301d58-6d34-56a8-9536-0185dbcb9664", "position": 5, "prompt": "Which response best demonstrates responsible customer service? Situation: A customer reports an outlet that sparked and smells burned. Do not sell a replacement outlet as a complete solution.", "options": ["Choose by appearance without checking details.", "Promise compatibility without reading product instructions.", "Say: “That could be hazardous. Please stop using it and contact a qualified electrician. If there is immediate danger, follow emergency guidance.”", "Ignore the customer’s application and select a popular item."], "correct_option": 2, "explanation": "Say: “That could be hazardous. Please stop using it and contact a qualified electrician. If there is immediate danger, follow emergency guidance.” Heat and burning smells are warning signs; a retail employee should not diagnose or prescribe a repair. The other choices skip verification or necessary safety checks."}], "catalog": {"course_code": "HB-101", "skill_level": "foundations", "topics": ["Electrical & Lighting"], "keywords": ["Recognize Common Electrical Products", "Read Electrical Labels Without Guessing", "Understand Common Lighting Choices", "Match Products to Location and Use", "Know When Electrical Questions Need an Expert", "Know the basics", "Check before recommending", "Put it into practice", "Key takeaways:", "HB-101-", "LED", "P01", "P02", "P03", "P04", "P05"], "learning_paths": ["Department Specialist"]}}$coursedata$::jsonb;
 c jsonb; l jsonb; q jsonb; target uuid;
begin
 c := payload->'course'; target := (c->>'id')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('coltrain-course:' || target::text, 0));
 if exists(select 1 from public.training_courses where id=target) then
  if not exists(select 1 from public.training_courses t where t.id=target
   and t.slug=c->>'slug' and t.version=(c->>'version')::integer
   and t.title=c->>'title' and t.description=c->>'description'
   and t.category=c->>'category' and t.passing_percent=(c->>'passing_percent')::integer
   and t.owner_organization_id is null) then
   raise exception 'HB-101 course differs; create a new version rather than overwrite';
  end if;
  if (select count(*) from public.training_lessons where course_id=target) <> jsonb_array_length(payload->'lessons')
   or (select count(*) from public.training_questions where course_id=target) <> jsonb_array_length(payload->'questions') then
   raise exception 'HB-101 content differs; draft import was not changed';
  end if;
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   if not exists(select 1 from public.training_lessons t where t.id=(l->>'id')::uuid
    and t.course_id=target and t.position=(l->>'position')::integer
    and t.title=l->>'title' and t.body=l->'body') then
    raise exception 'HB-101 lesson differs; draft import was not changed';
   end if;
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   if not exists(select 1 from public.training_questions t join private.training_answer_keys k on k.question_id=t.id
    where t.id=(q->>'id')::uuid and t.course_id=target and t.position=(q->>'position')::integer
    and t.prompt=q->>'prompt' and t.options=q->'options'
    and k.correct_option=(q->>'correct_option')::integer and k.explanation=q->>'explanation') then
    raise exception 'HB-101 question differs; draft import was not changed';
   end if;
  end loop;
 else
  insert into public.training_courses(id,slug,version,title,description,category,passing_percent,published)
   values(target,c->>'slug',(c->>'version')::integer,c->>'title',c->>'description',c->>'category',(c->>'passing_percent')::integer,false);
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   insert into public.training_lessons(id,course_id,position,title,body)
    values((l->>'id')::uuid,target,(l->>'position')::integer,l->>'title',l->'body');
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   insert into public.training_questions(id,course_id,position,prompt,options)
    values((q->>'id')::uuid,target,(q->>'position')::integer,q->>'prompt',q->'options');
   insert into private.training_answer_keys(question_id,correct_option,explanation)
    values((q->>'id')::uuid,(q->>'correct_option')::integer,q->>'explanation');
  end loop;
 end if;
 -- Optional metadata: imports remain compatible before the catalog migration.
 if to_regclass('public.training_course_catalog') is not null then
  insert into public.training_course_catalog(course_id,course_code,skill_level,topics,keywords,learning_paths)
  values(target,payload->'catalog'->>'course_code',payload->'catalog'->>'skill_level',
   array(select jsonb_array_elements_text(payload->'catalog'->'topics')),
   array(select jsonb_array_elements_text(payload->'catalog'->'keywords')),
   array(select jsonb_array_elements_text(payload->'catalog'->'learning_paths')))
  on conflict(course_id) do nothing;
 end if;
end;
$courseimport$;
do $courseimport$
declare
 payload jsonb := $coursedata${"course": {"id": "77594380-bd10-5b14-9fd0-6e94452702ff", "slug": "hb-102-plumbing-fundamentals", "version": 1, "title": "Plumbing Fundamentals", "description": "Build basic retail product knowledge and safe customer guidance for plumbing.", "category": "Home Systems & Building Materials", "passing_percent": 80}, "lessons": [{"id": "77384a96-317d-59a2-a89a-4bcad894f6ea", "position": 1, "title": "Recognize Common Plumbing Parts", "body": [{"type": "paragraph", "text": "Why this matters: Correct product identification begins with understanding what each part does."}, {"type": "heading", "text": "Know the basics"}, {"type": "paragraph", "text": "Pipes carry water or drain waste. Fittings join or change the direction of pipe runs. Valves control flow. Supply lines connect fixtures to water supplies."}, {"type": "heading", "text": "Check before recommending"}, {"type": "paragraph", "text": "Common fitting shapes include elbows, tees, couplings, and adapters. An elbow changes direction. A tee creates a branch. A coupling joins similar ends. An adapter changes connection types."}, {"type": "heading", "text": "Put it into practice"}, {"type": "paragraph", "text": "Names help locate a part, but do not prove that it fits. Size, material, pressure rating, connection type, and use must also match."}, {"type": "paragraph", "text": "Hardware-store example: A customer holds a curved fitting and asks for another. Identify it as an elbow, then ask what material and connection style the existing system uses."}, {"type": "paragraph", "text": "What to say or do: Say: “Is this for a water supply, drain, or another use? Do you have the old part or its markings?”"}, {"type": "paragraph", "text": "Common mistakes: Choosing a fitting by shape alone."}, {"type": "paragraph", "text": "When to ask for help: Escalate unclear applications, unusual materials, or safety-critical systems to an experienced specialist."}, {"type": "heading", "text": "Key takeaways:"}, {"type": "bullet", "text": "Pipes carry water or drain waste."}, {"type": "bullet", "text": "Common fitting shapes include elbows, tees, couplings, and adapters."}, {"type": "bullet", "text": "Names help locate a part, but do not prove that it fits."}, {"type": "paragraph", "text": "Unscored practice HB-102-P01: What does a plumbing elbow primarily do?"}, {"type": "bullet", "text": "A. Measure pressure"}, {"type": "bullet", "text": "B. Change pipe direction"}, {"type": "bullet", "text": "C. Stop all leaks"}, {"type": "bullet", "text": "D. Heat water"}, {"type": "paragraph", "text": "Answer: B. Explanation: An elbow changes the direction of a pipe run."}]}, {"id": "8ac50205-abcf-5353-9898-22e06dfe256d", "position": 2, "title": "Understand Pipe Materials and Connections", "body": [{"type": "paragraph", "text": "Why this matters: A fitting must suit the pipe material and connection method."}, {"type": "heading", "text": "Know the basics"}, {"type": "paragraph", "text": "Common plumbing materials include copper, PEX, PVC, and CPVC. Their permitted uses and joining methods differ. Do not assume all plastic pipes are interchangeable."}, {"type": "heading", "text": "Check before recommending"}, {"type": "paragraph", "text": "Connections may be threaded, solvent-welded, crimped, clamped, compression, or push-to-connect. Each system has manufacturer instructions, compatible components, and limits."}, {"type": "heading", "text": "Put it into practice"}, {"type": "paragraph", "text": "Identify the material and read the product labeling before making a recommendation. Local code requirements and installation conditions may also apply."}, {"type": "paragraph", "text": "Hardware-store example: A customer asks for glue to connect two pieces of plastic pipe. Ask whether the pipe is PVC or CPVC and check the product instructions rather than choosing by bottle color."}, {"type": "paragraph", "text": "What to say or do: Ask: “What material is printed on the pipe, and is this for supply water or drainage?”"}, {"type": "paragraph", "text": "Common mistakes: Assuming one cement or fitting works for every plastic pipe."}, {"type": "paragraph", "text": "When to ask for help: Ask a qualified plumber or manufacturer support about unmarked pipe, transitions, or code-restricted uses."}, {"type": "heading", "text": "Key takeaways:"}, {"type": "bullet", "text": "Common plumbing materials include copper, PEX, PVC, and CPVC."}, {"type": "bullet", "text": "Connections may be threaded, solvent-welded, crimped, clamped, compression, or push-to-connect."}, {"type": "bullet", "text": "Identify the material and read the product labeling before making a recommendation."}, {"type": "paragraph", "text": "Unscored practice HB-102-P02: Why should you check the pipe material before selecting a connector?"}, {"type": "bullet", "text": "A. All pipe materials use the same connection"}, {"type": "bullet", "text": "B. Materials and joining methods have different requirements"}, {"type": "bullet", "text": "C. Only the pipe color matters"}, {"type": "bullet", "text": "D. Any connector works if tightened"}, {"type": "paragraph", "text": "Answer: B. Explanation: Different pipe systems require compatible fittings and installation methods."}]}, {"id": "95a1c1d9-d5a5-5626-a141-b70d9f29ea82", "position": 3, "title": "Measure Plumbing Parts Correctly", "body": [{"type": "paragraph", "text": "Why this matters: Nominal pipe sizes and actual dimensions can differ."}, {"type": "heading", "text": "Know the basics"}, {"type": "paragraph", "text": "Plumbing parts may use nominal sizes. The number on the label may not equal a ruler measurement across the outside of the pipe. Different systems use different sizing conventions."}, {"type": "heading", "text": "Check before recommending"}, {"type": "paragraph", "text": "Check the printed size and material markings when possible. Ask for the old fitting or a clear photo showing markings. A measured outside diameter can help identify a system but should not be the only evidence."}, {"type": "heading", "text": "Put it into practice"}, {"type": "paragraph", "text": "Connections also vary by male or female threads and thread style. A size match without the correct connection style can still fail."}, {"type": "paragraph", "text": "Hardware-store example: A customer measures a pipe with a tape and requests a fitting. Ask for pipe markings and the connection type before choosing."}, {"type": "paragraph", "text": "What to say or do: Say: “Pipe sizes can be named differently from their measured diameter. Let’s confirm the system.”"}, {"type": "paragraph", "text": "Common mistakes: Treating a ruler measurement as the product’s nominal size."}, {"type": "paragraph", "text": "When to ask for help: Escalate uncertain thread types, mixed materials, and specialty connections."}, {"type": "heading", "text": "Key takeaways:"}, {"type": "bullet", "text": "Plumbing parts may use nominal sizes."}, {"type": "bullet", "text": "Check the printed size and material markings when possible."}, {"type": "bullet", "text": "Connections also vary by male or female threads and thread style."}, {"type": "paragraph", "text": "Unscored practice HB-102-P03: What is the safest way to use a customer’s measured pipe diameter?"}, {"type": "bullet", "text": "A. Treat it as the only sizing detail"}, {"type": "bullet", "text": "B. Use it as one clue and confirm markings and system"}, {"type": "bullet", "text": "C. Ignore all markings"}, {"type": "bullet", "text": "D. Choose the closest-looking fitting"}, {"type": "paragraph", "text": "Answer: B. Explanation: Measured diameter helps identification but does not replace system and size verification."}]}, {"id": "f079acba-da9e-5ff9-a394-3388b5838f69", "position": 4, "title": "Help With Common Fixture Questions", "body": [{"type": "paragraph", "text": "Why this matters: A leak symptom may have several possible causes."}, {"type": "heading", "text": "Know the basics"}, {"type": "paragraph", "text": "Customers may ask about faucets, toilets, showerheads, drains, and supply connections. Ask which fixture is involved, where the issue appears, and whether the customer has the model number."}, {"type": "heading", "text": "Check before recommending"}, {"type": "paragraph", "text": "A running toilet might involve more than one component. A dripping faucet may use a specific cartridge. Replacement parts can be model-specific."}, {"type": "heading", "text": "Put it into practice"}, {"type": "paragraph", "text": "Do not promise a repair based on symptoms alone. Help identify a likely product category and verify the manufacturer’s compatibility guidance."}, {"type": "paragraph", "text": "Hardware-store example: A customer needs a faucet cartridge. Ask for the faucet brand and model or a photo of the existing cartridge."}, {"type": "paragraph", "text": "What to say or do: Say: “Many cartridges look alike. Let’s identify the fixture before selecting one.”"}, {"type": "paragraph", "text": "Common mistakes: Promising a universal cartridge will fit."}, {"type": "paragraph", "text": "When to ask for help: Refer uncertain repairs, hidden leaks, or water damage to a qualified plumber."}, {"type": "heading", "text": "Key takeaways:"}, {"type": "bullet", "text": "Customers may ask about faucets, toilets, showerheads, drains, and supply connections."}, {"type": "bullet", "text": "A running toilet might involve more than one component."}, {"type": "bullet", "text": "Do not promise a repair based on symptoms alone."}, {"type": "paragraph", "text": "Unscored practice HB-102-P04: What detail most helps select a faucet cartridge?"}, {"type": "bullet", "text": "A. The sink color"}, {"type": "bullet", "text": "B. Faucet brand and model"}, {"type": "bullet", "text": "C. The customer’s age"}, {"type": "bullet", "text": "D. The aisle number"}, {"type": "paragraph", "text": "Answer: B. Explanation: Cartridges are often specific to the fixture model."}]}, {"id": "1788af8a-a38f-5710-84d6-45d6e26c77d5", "position": 5, "title": "Recognize Plumbing Safety and Escalation", "body": [{"type": "paragraph", "text": "Why this matters: Some plumbing problems risk flooding, contamination, or injury."}, {"type": "heading", "text": "Know the basics"}, {"type": "paragraph", "text": "Active leaks, sewage backups, possible cross-connections, and water-heater issues may require prompt professional attention. Gas lines and gas-fired appliances are not general retail repair topics."}, {"type": "heading", "text": "Check before recommending"}, {"type": "paragraph", "text": "Employees should not advise customers to defeat safety devices or use products outside their listed applications. Potable-water products need appropriate approval for drinking-water contact."}, {"type": "heading", "text": "Put it into practice"}, {"type": "paragraph", "text": "Help customers find information and qualified support. For urgent flooding or immediate hazards, follow emergency and store procedures."}, {"type": "paragraph", "text": "Hardware-store example: A customer reports water flowing from a ceiling near a light fixture. Recognize both water and electrical hazards; do not give do-it-yourself instructions."}, {"type": "paragraph", "text": "What to say or do: Say: “That situation may be unsafe. Please seek qualified help promptly rather than trying a part at random.”"}, {"type": "paragraph", "text": "Common mistakes: Focusing on selling a fitting while ignoring a serious hazard."}, {"type": "paragraph", "text": "When to ask for help: Escalate gas, sewage, water-heater safety, backflow, and combined electrical/water hazards."}, {"type": "heading", "text": "Key takeaways:"}, {"type": "bullet", "text": "Active leaks, sewage backups, possible cross-connections, and water-heater issues may require prompt professional attention."}, {"type": "bullet", "text": "Employees should not advise customers to defeat safety devices or use products outside their listed applications."}, {"type": "bullet", "text": "Help customers find information and qualified support."}, {"type": "paragraph", "text": "Unscored practice HB-102-P05: Which issue should be referred for urgent qualified assistance?"}, {"type": "bullet", "text": "A. Choosing a faucet finish"}, {"type": "bullet", "text": "B. Comparing showerhead styles"}, {"type": "bullet", "text": "C. Water leaking near an electrical fixture"}, {"type": "bullet", "text": "D. Locating a hose washer"}, {"type": "paragraph", "text": "Answer: C. Explanation: Water near electrical equipment creates a potentially serious hazard."}]}], "questions": [{"id": "9df76248-3ce3-5960-a940-46266a6af2b4", "position": 1, "prompt": "Which response best follows this lesson when a customer needs help? Situation: A customer holds a curved fitting and asks for another. Identify it as an elbow, then ask what material and connection style the existing system uses.", "options": ["Choose by appearance without checking details.", "Promise compatibility without reading product instructions.", "Say: “Is this for a water supply, drain, or another use? Do you have the old part or its markings?”", "Ignore the customer’s application and select a popular item."], "correct_option": 2, "explanation": "Say: “Is this for a water supply, drain, or another use? Do you have the old part or its markings?” An elbow changes the direction of a pipe run. The other choices skip verification or necessary safety checks."}, {"id": "9ddf3f2a-32f6-56e3-b319-3f7928c82f3e", "position": 2, "prompt": "What is the safest way to confirm the right product? Situation: A customer asks for glue to connect two pieces of plastic pipe. Ask whether the pipe is PVC or CPVC and check the product instructions rather than choosing by bottle color.", "options": ["Choose by appearance without checking details.", "Promise compatibility without reading product instructions.", "Ignore the customer’s application and select a popular item.", "Ask: “What material is printed on the pipe, and is this for supply water or drainage?”"], "correct_option": 3, "explanation": "Ask: “What material is printed on the pipe, and is this for supply water or drainage?” Different pipe systems require compatible fittings and installation methods. The other choices skip verification or necessary safety checks."}, {"id": "ea8b14ac-08d7-5922-90d6-fed773cdfb35", "position": 3, "prompt": "Which approach best avoids a mistaken recommendation? Situation: A customer measures a pipe with a tape and requests a fitting. Ask for pipe markings and the connection type before choosing.", "options": ["Say: “Pipe sizes can be named differently from their measured diameter. Let’s confirm the system.”", "Choose by appearance without checking details.", "Promise compatibility without reading product instructions.", "Ignore the customer’s application and select a popular item."], "correct_option": 0, "explanation": "Say: “Pipe sizes can be named differently from their measured diameter. Let’s confirm the system.” Measured diameter helps identification but does not replace system and size verification. The other choices skip verification or necessary safety checks."}, {"id": "c1cda529-5b14-590a-aee5-d46fa225618a", "position": 4, "prompt": "What should an employee do when product requirements are uncertain? Situation: A customer needs a faucet cartridge. Ask for the faucet brand and model or a photo of the existing cartridge.", "options": ["Choose by appearance without checking details.", "Say: “Many cartridges look alike. Let’s identify the fixture before selecting one.”", "Promise compatibility without reading product instructions.", "Ignore the customer’s application and select a popular item."], "correct_option": 1, "explanation": "Say: “Many cartridges look alike. Let’s identify the fixture before selecting one.” Cartridges are often specific to the fixture model. The other choices skip verification or necessary safety checks."}, {"id": "3243e58e-e08b-5a2f-8dec-c03c69a562dd", "position": 5, "prompt": "Which response best demonstrates responsible customer service? Situation: A customer reports water flowing from a ceiling near a light fixture. Recognize both water and electrical hazards; do not give do-it-yourself instructions.", "options": ["Choose by appearance without checking details.", "Promise compatibility without reading product instructions.", "Say: “That situation may be unsafe. Please seek qualified help promptly rather than trying a part at random.”", "Ignore the customer’s application and select a popular item."], "correct_option": 2, "explanation": "Say: “That situation may be unsafe. Please seek qualified help promptly rather than trying a part at random.” Water near electrical equipment creates a potentially serious hazard. The other choices skip verification or necessary safety checks."}], "catalog": {"course_code": "HB-102", "skill_level": "foundations", "topics": ["Plumbing"], "keywords": ["Recognize Common Plumbing Parts", "Understand Pipe Materials and Connections", "Measure Plumbing Parts Correctly", "Help With Common Fixture Questions", "Recognize Plumbing Safety and Escalation", "Know the basics", "Check before recommending", "Put it into practice", "Key takeaways:", "CPVC", "HB-102-", "P01", "P02", "P03", "P04", "P05", "PEX", "PVC"], "learning_paths": ["Department Specialist"]}}$coursedata$::jsonb;
 c jsonb; l jsonb; q jsonb; target uuid;
begin
 c := payload->'course'; target := (c->>'id')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('coltrain-course:' || target::text, 0));
 if exists(select 1 from public.training_courses where id=target) then
  if not exists(select 1 from public.training_courses t where t.id=target
   and t.slug=c->>'slug' and t.version=(c->>'version')::integer
   and t.title=c->>'title' and t.description=c->>'description'
   and t.category=c->>'category' and t.passing_percent=(c->>'passing_percent')::integer
   and t.owner_organization_id is null) then
   raise exception 'HB-102 course differs; create a new version rather than overwrite';
  end if;
  if (select count(*) from public.training_lessons where course_id=target) <> jsonb_array_length(payload->'lessons')
   or (select count(*) from public.training_questions where course_id=target) <> jsonb_array_length(payload->'questions') then
   raise exception 'HB-102 content differs; draft import was not changed';
  end if;
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   if not exists(select 1 from public.training_lessons t where t.id=(l->>'id')::uuid
    and t.course_id=target and t.position=(l->>'position')::integer
    and t.title=l->>'title' and t.body=l->'body') then
    raise exception 'HB-102 lesson differs; draft import was not changed';
   end if;
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   if not exists(select 1 from public.training_questions t join private.training_answer_keys k on k.question_id=t.id
    where t.id=(q->>'id')::uuid and t.course_id=target and t.position=(q->>'position')::integer
    and t.prompt=q->>'prompt' and t.options=q->'options'
    and k.correct_option=(q->>'correct_option')::integer and k.explanation=q->>'explanation') then
    raise exception 'HB-102 question differs; draft import was not changed';
   end if;
  end loop;
 else
  insert into public.training_courses(id,slug,version,title,description,category,passing_percent,published)
   values(target,c->>'slug',(c->>'version')::integer,c->>'title',c->>'description',c->>'category',(c->>'passing_percent')::integer,false);
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   insert into public.training_lessons(id,course_id,position,title,body)
    values((l->>'id')::uuid,target,(l->>'position')::integer,l->>'title',l->'body');
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   insert into public.training_questions(id,course_id,position,prompt,options)
    values((q->>'id')::uuid,target,(q->>'position')::integer,q->>'prompt',q->'options');
   insert into private.training_answer_keys(question_id,correct_option,explanation)
    values((q->>'id')::uuid,(q->>'correct_option')::integer,q->>'explanation');
  end loop;
 end if;
 -- Optional metadata: imports remain compatible before the catalog migration.
 if to_regclass('public.training_course_catalog') is not null then
  insert into public.training_course_catalog(course_id,course_code,skill_level,topics,keywords,learning_paths)
  values(target,payload->'catalog'->>'course_code',payload->'catalog'->>'skill_level',
   array(select jsonb_array_elements_text(payload->'catalog'->'topics')),
   array(select jsonb_array_elements_text(payload->'catalog'->'keywords')),
   array(select jsonb_array_elements_text(payload->'catalog'->'learning_paths')))
  on conflict(course_id) do nothing;
 end if;
end;
$courseimport$;
do $courseimport$
declare
 payload jsonb := $coursedata${"course": {"id": "80c00da5-4a42-5791-acbf-f7ec6655cef7", "slug": "hb-103-heating-cooling-fundamentals", "version": 1, "title": "Heating & Cooling Fundamentals", "description": "Build basic retail product knowledge and safe customer guidance for heating and cooling.", "category": "Home Systems & Building Materials", "passing_percent": 80}, "lessons": [{"id": "bb67a7eb-3368-511a-b3ce-437dbe46eb94", "position": 1, "title": "Understand Basic Heating and Cooling Systems", "body": [{"type": "paragraph", "text": "Why this matters: Customers may describe comfort problems without knowing their equipment type."}, {"type": "heading", "text": "Know the basics"}, {"type": "paragraph", "text": "Heating and cooling systems move or produce heat to control indoor comfort. Common systems include furnaces, heat pumps, air conditioners, and portable room units."}, {"type": "heading", "text": "Check before recommending"}, {"type": "paragraph", "text": "A thermostat controls temperature settings for compatible equipment. Air filters help capture particles in systems designed for them. Ventilation moves air between spaces or outdoors."}, {"type": "heading", "text": "Put it into practice"}, {"type": "paragraph", "text": "Product names do not establish system compatibility. Start by asking what equipment the customer owns and what task they are trying to complete."}, {"type": "paragraph", "text": "Hardware-store example: A customer asks for a “heater filter.” Ask whether they have a furnace, heat pump air handler, or portable unit."}, {"type": "paragraph", "text": "What to say or do: Say: “Do you know the equipment model, or can you show the filter label?”"}, {"type": "paragraph", "text": "Common mistakes: Assuming every heating system uses the same filter."}, {"type": "paragraph", "text": "When to ask for help: Escalate unfamiliar equipment, combustion systems, or mechanical problems to a qualified technician."}, {"type": "heading", "text": "Key takeaways:"}, {"type": "bullet", "text": "Heating and cooling systems move or produce heat to control indoor comfort."}, {"type": "bullet", "text": "A thermostat controls temperature settings for compatible equipment."}, {"type": "bullet", "text": "Product names do not establish system compatibility."}, {"type": "paragraph", "text": "Unscored practice HB-103-P01: Which detail best helps identify a replacement HVAC accessory?"}, {"type": "bullet", "text": "A. Equipment model and existing accessory label"}, {"type": "bullet", "text": "B. House paint color"}, {"type": "bullet", "text": "C. Customer ZIP code alone"}, {"type": "bullet", "text": "D. Package popularity"}, {"type": "paragraph", "text": "Answer: A. Explanation: Equipment and accessory labels help establish the correct category and compatibility."}]}, {"id": "55da59da-3273-5810-88d0-e85cd848a380", "position": 2, "title": "Help Customers Select Air Filters", "body": [{"type": "paragraph", "text": "Why this matters: The wrong filter may not fit or suit the equipment."}, {"type": "heading", "text": "Know the basics"}, {"type": "paragraph", "text": "Filter labels often list a nominal size and an actual size. These can differ. Compare the existing filter markings and equipment instructions."}, {"type": "heading", "text": "Check before recommending"}, {"type": "paragraph", "text": "Filter performance may be described using MERV ratings. Higher numbers generally indicate greater particle capture under the rating method, but not every system can use every filter."}, {"type": "heading", "text": "Put it into practice"}, {"type": "paragraph", "text": "Airflow requirements matter. Do not claim that the highest-rated filter is always best. Check manufacturer guidance when performance or compatibility is unclear."}, {"type": "paragraph", "text": "Hardware-store example: A customer wants the thickest, highest-rated filter available. Ask for the system’s recommended size and filter specifications first."}, {"type": "paragraph", "text": "What to say or do: Say: “Let’s match the size and check what your equipment allows.”"}, {"type": "paragraph", "text": "Common mistakes: Choosing solely by MERV rating or nominal dimensions."}, {"type": "paragraph", "text": "When to ask for help: Escalate airflow complaints or uncertainty about approved filters to HVAC support."}, {"type": "heading", "text": "Key takeaways:"}, {"type": "bullet", "text": "Filter labels often list a nominal size and an actual size."}, {"type": "bullet", "text": "Filter performance may be described using MERV ratings."}, {"type": "bullet", "text": "Airflow requirements matter."}, {"type": "paragraph", "text": "Unscored practice HB-103-P02: Why is the highest MERV rating not automatically the best choice?"}, {"type": "bullet", "text": "A. It is always the wrong size"}, {"type": "bullet", "text": "B. Equipment airflow requirements may limit suitable filters"}, {"type": "bullet", "text": "C. It only measures color"}, {"type": "bullet", "text": "D. It cannot capture particles"}, {"type": "paragraph", "text": "Answer: B. Explanation: Filter selection must consider the equipment’s airflow requirements."}]}, {"id": "6109cef8-52a9-5c00-bd0e-5a8da2cbe5d4", "position": 3, "title": "Recognize Thermostat and Control Differences", "body": [{"type": "paragraph", "text": "Why this matters: A thermostat that looks similar may not work with a particular system."}, {"type": "heading", "text": "Know the basics"}, {"type": "paragraph", "text": "Thermostats vary by supported equipment type, voltage, wiring, and features. Some systems use proprietary controls. A basic thermostat is not automatically compatible with a heat pump or multistage system."}, {"type": "heading", "text": "Check before recommending"}, {"type": "paragraph", "text": "Ask for the HVAC equipment model and the existing thermostat model. Manufacturer compatibility tools can help, but wiring questions belong to qualified support."}, {"type": "heading", "text": "Put it into practice"}, {"type": "paragraph", "text": "Never instruct a customer to connect unknown wires or bypass a safety control. Do not assume wire color alone identifies its function."}, {"type": "paragraph", "text": "Hardware-store example: A customer wants a smart thermostat for a heat pump. Ask for model details and point them to the manufacturer’s compatibility process."}, {"type": "paragraph", "text": "What to say or do: Say: “We need to confirm your system and wiring requirements before recommending a thermostat.”"}, {"type": "paragraph", "text": "Common mistakes: Claiming compatibility based on thermostat appearance."}, {"type": "paragraph", "text": "When to ask for help: Escalate unknown wiring, line-voltage controls, and system modifications."}, {"type": "heading", "text": "Key takeaways:"}, {"type": "bullet", "text": "Thermostats vary by supported equipment type, voltage, wiring, and features."}, {"type": "bullet", "text": "Ask for the HVAC equipment model and the existing thermostat model."}, {"type": "bullet", "text": "Never instruct a customer to connect unknown wires or bypass a safety control."}, {"type": "paragraph", "text": "Unscored practice HB-103-P03: What should an associate avoid when helping with thermostat selection?"}, {"type": "bullet", "text": "A. Checking model numbers"}, {"type": "bullet", "text": "B. Reviewing official compatibility guidance"}, {"type": "bullet", "text": "C. Guessing wire functions by color"}, {"type": "bullet", "text": "D. Referring complex wiring to a professional"}, {"type": "paragraph", "text": "Answer: C. Explanation: Wire colors are not a reliable substitute for verified wiring information."}]}, {"id": "916117e3-0090-5d80-a751-43406234d139", "position": 4, "title": "Compare Portable Comfort Products", "body": [{"type": "paragraph", "text": "Why this matters: Portable heaters and fans have different limitations and hazards."}, {"type": "heading", "text": "Know the basics"}, {"type": "paragraph", "text": "Fans move air but do not necessarily lower the room’s air temperature. Portable air conditioners require appropriate venting and electrical supply. Dehumidifiers remove moisture from air."}, {"type": "heading", "text": "Check before recommending"}, {"type": "paragraph", "text": "Portable heaters require careful attention to manufacturer clearances, electrical ratings, and use restrictions. They should not be recommended with extension cords or power strips unless the manufacturer explicitly permits the setup."}, {"type": "heading", "text": "Put it into practice"}, {"type": "paragraph", "text": "Ask about room size, moisture, outlet availability, and intended location. Do not promise a particular temperature change without verified product data."}, {"type": "paragraph", "text": "Hardware-store example: A customer wants a space heater for a small workshop. Discuss the listed room application and safety clearances, then review the manufacturer instructions."}, {"type": "paragraph", "text": "What to say or do: Ask: “Where will you use it, and what does the product label say about the space and power supply?”"}, {"type": "paragraph", "text": "Common mistakes: Recommending a heater based only on advertised wattage."}, {"type": "paragraph", "text": "When to ask for help: Escalate unsafe wiring, fuel-burning heaters, or unusual installation needs."}, {"type": "heading", "text": "Key takeaways:"}, {"type": "bullet", "text": "Fans move air but do not necessarily lower the room’s air temperature."}, {"type": "bullet", "text": "Portable heaters require careful attention to manufacturer clearances, electrical ratings, and use restrictions."}, {"type": "bullet", "text": "Ask about room size, moisture, outlet availability, and intended location."}, {"type": "paragraph", "text": "Unscored practice HB-103-P04: Which product is intended primarily to remove moisture from indoor air?"}, {"type": "bullet", "text": "A. Fan"}, {"type": "bullet", "text": "B. Dehumidifier"}, {"type": "bullet", "text": "C. Thermostat"}, {"type": "bullet", "text": "D. Air filter"}, {"type": "paragraph", "text": "Answer: B. Explanation: A dehumidifier is designed to remove moisture from the air."}]}, {"id": "7de6f881-dba6-50e6-819b-2dc451834e34", "position": 5, "title": "Recognize HVAC Warning Signs", "body": [{"type": "paragraph", "text": "Why this matters: Some comfort complaints indicate safety issues, not accessory needs."}, {"type": "heading", "text": "Know the basics"}, {"type": "paragraph", "text": "Gas odors, carbon monoxide alarm activation, suspected refrigerant leaks, and electrical burning smells are not routine retail troubleshooting questions."}, {"type": "heading", "text": "Check before recommending"}, {"type": "paragraph", "text": "Carbon monoxide is a dangerous gas that people cannot reliably detect by smell. A CO alarm requires following emergency guidance and contacting appropriate responders. Never suggest ignoring or disabling an alarm."}, {"type": "heading", "text": "Put it into practice"}, {"type": "paragraph", "text": "Employees can identify packaged accessories and explain labels. They should not diagnose combustion equipment, handle refrigerants, or coach unsafe repairs."}, {"type": "paragraph", "text": "Hardware-store example: A customer says a carbon monoxide alarm sounded near a gas furnace. Do not recommend a new filter as the solution."}, {"type": "paragraph", "text": "What to say or do: Say: “Follow the alarm’s emergency instructions and contact emergency services or the appropriate utility or qualified professional.”"}, {"type": "paragraph", "text": "Common mistakes: Treating a CO alarm as a minor equipment nuisance."}, {"type": "paragraph", "text": "When to ask for help: Escalate gas, CO, refrigerant, combustion, and serious electrical concerns immediately."}, {"type": "heading", "text": "Key takeaways:"}, {"type": "bullet", "text": "Gas odors, carbon monoxide alarm activation, suspected refrigerant leaks, and electrical burning smells are not routine retail troubleshooting questions."}, {"type": "bullet", "text": "Carbon monoxide is a dangerous gas that people cannot reliably detect by smell."}, {"type": "bullet", "text": "Employees can identify packaged accessories and explain labels."}, {"type": "paragraph", "text": "Unscored practice HB-103-P05: A customer reports a carbon monoxide alarm. What should you recommend?"}, {"type": "bullet", "text": "A. Ignore it if the house feels warm"}, {"type": "bullet", "text": "B. Follow emergency guidance and seek appropriate help"}, {"type": "bullet", "text": "C. Change the thermostat setting"}, {"type": "bullet", "text": "D. Cover the alarm"}, {"type": "paragraph", "text": "Answer: B. Explanation: A CO alarm is a safety warning requiring appropriate emergency action."}]}], "questions": [{"id": "54cc58bb-7b39-52ad-a33a-439ba79a65ca", "position": 1, "prompt": "Which response best follows this lesson when a customer needs help? Situation: A customer asks for a “heater filter.” Ask whether they have a furnace, heat pump air handler, or portable unit.", "options": ["Choose by appearance without checking details.", "Promise compatibility without reading product instructions.", "Say: “Do you know the equipment model, or can you show the filter label?”", "Ignore the customer’s application and select a popular item."], "correct_option": 2, "explanation": "Say: “Do you know the equipment model, or can you show the filter label?” Equipment and accessory labels help establish the correct category and compatibility. The other choices skip verification or necessary safety checks."}, {"id": "90cb53dc-e728-5eec-aff8-949e19301559", "position": 2, "prompt": "What is the safest way to confirm the right product? Situation: A customer wants the thickest, highest-rated filter available. Ask for the system’s recommended size and filter specifications first.", "options": ["Choose by appearance without checking details.", "Promise compatibility without reading product instructions.", "Ignore the customer’s application and select a popular item.", "Say: “Let’s match the size and check what your equipment allows.”"], "correct_option": 3, "explanation": "Say: “Let’s match the size and check what your equipment allows.” Filter selection must consider the equipment’s airflow requirements. The other choices skip verification or necessary safety checks."}, {"id": "2674454b-212b-5d97-9dd8-39f3912ae6d6", "position": 3, "prompt": "Which approach best avoids a mistaken recommendation? Situation: A customer wants a smart thermostat for a heat pump. Ask for model details and point them to the manufacturer’s compatibility process.", "options": ["Say: “We need to confirm your system and wiring requirements before recommending a thermostat.”", "Choose by appearance without checking details.", "Promise compatibility without reading product instructions.", "Ignore the customer’s application and select a popular item."], "correct_option": 0, "explanation": "Say: “We need to confirm your system and wiring requirements before recommending a thermostat.” Wire colors are not a reliable substitute for verified wiring information. The other choices skip verification or necessary safety checks."}, {"id": "999f8201-b0ce-5d8e-88e7-a6f585e6d0a9", "position": 4, "prompt": "What should an employee do when product requirements are uncertain? Situation: A customer wants a space heater for a small workshop. Discuss the listed room application and safety clearances, then review the manufacturer instructions.", "options": ["Choose by appearance without checking details.", "Ask: “Where will you use it, and what does the product label say about the space and power supply?”", "Promise compatibility without reading product instructions.", "Ignore the customer’s application and select a popular item."], "correct_option": 1, "explanation": "Ask: “Where will you use it, and what does the product label say about the space and power supply?” A dehumidifier is designed to remove moisture from the air. The other choices skip verification or necessary safety checks."}, {"id": "577503cd-a07f-5592-8d11-b3b14316a7f3", "position": 5, "prompt": "Which response best demonstrates responsible customer service? Situation: A customer says a carbon monoxide alarm sounded near a gas furnace. Do not recommend a new filter as the solution.", "options": ["Choose by appearance without checking details.", "Promise compatibility without reading product instructions.", "Say: “Follow the alarm’s emergency instructions and contact emergency services or the appropriate utility or qualified professional.”", "Ignore the customer’s application and select a popular item."], "correct_option": 2, "explanation": "Say: “Follow the alarm’s emergency instructions and contact emergency services or the appropriate utility or qualified professional.” A CO alarm is a safety warning requiring appropriate emergency action. The other choices skip verification or necessary safety checks."}], "catalog": {"course_code": "HB-103", "skill_level": "foundations", "topics": ["Heating & Cooling"], "keywords": ["Understand Basic Heating and Cooling Systems", "Help Customers Select Air Filters", "Recognize Thermostat and Control Differences", "Compare Portable Comfort Products", "Recognize HVAC Warning Signs", "Know the basics", "Check before recommending", "Put it into practice", "Key takeaways:", "CO", "HB-103-", "HVAC", "MERV", "P01", "P02", "P03", "P04", "P05", "ZIP"], "learning_paths": ["Department Specialist"]}}$coursedata$::jsonb;
