do $courseimport$
declare
 payload jsonb := $coursedata${"course": {"id": "60bdd288-ff46-59d1-9465-d3510c8e97ed", "slug": "hb-104-lumber-building-materials-fundamentals", "version": 1, "title": "Lumber & Building Materials Fundamentals", "description": "Build basic retail product knowledge and safe customer guidance for lumber and building materials.", "category": "Home Systems & Building Materials", "passing_percent": 80}, "lessons": [{"id": "bd9954e9-9de5-5719-a639-b860fd94f811", "position": 1, "title": "Recognize Lumber and Sheet Goods", "body": [{"type": "paragraph", "text": "Why this matters: Customers need help locating the correct material before comparing options."}, {"type": "heading", "text": "Know the basics"}, {"type": "paragraph", "text": "Dimensional lumber, plywood, OSB, MDF, and treated lumber are common categories. Plywood uses bonded layers of wood veneer. OSB uses bonded wood strands. MDF is made from wood fibers and resin."}, {"type": "heading", "text": "Check before recommending"}, {"type": "paragraph", "text": "Products differ in intended use, finish, moisture resistance, and structural ratings. A sheet that looks similar may not have the same approved application."}, {"type": "heading", "text": "Put it into practice"}, {"type": "paragraph", "text": "Use shelf tags and grade stamps or manufacturer labels to identify products. Do not describe all sheet goods as interchangeable."}, {"type": "paragraph", "text": "Hardware-store example: A customer asks for “a four-by-eight board.” Ask whether they mean plywood, OSB, or another sheet material and what the project requires."}, {"type": "paragraph", "text": "What to say or do: Ask: “Will this be indoors or outdoors? Is it decorative or part of a structure?”"}, {"type": "paragraph", "text": "Common mistakes: Assuming every 4-by-8 sheet has the same strength or moisture rating."}, {"type": "paragraph", "text": "When to ask for help: Refer structural and code-related selections to qualified guidance."}, {"type": "heading", "text": "Key takeaways:"}, {"type": "bullet", "text": "Dimensional lumber, plywood, OSB, MDF, and treated lumber are common categories."}, {"type": "bullet", "text": "Products differ in intended use, finish, moisture resistance, and structural ratings."}, {"type": "bullet", "text": "Use shelf tags and grade stamps or manufacturer labels to identify products."}, {"type": "paragraph", "text": "Unscored practice HB-104-P01: Which material is commonly made from bonded wood strands?"}, {"type": "bullet", "text": "A. OSB"}, {"type": "bullet", "text": "B. Glass"}, {"type": "bullet", "text": "C. Copper pipe"}, {"type": "bullet", "text": "D. Concrete block"}, {"type": "paragraph", "text": "Answer: A. Explanation: OSB is manufactured from bonded wood strands."}]}, {"id": "a561c10f-b3fc-5113-864d-3eec8ec50711", "position": 2, "title": "Understand Nominal and Actual Lumber Sizes", "body": [{"type": "paragraph", "text": "Why this matters: A lumber size on a shelf tag may differ from its measured dimensions."}, {"type": "heading", "text": "Know the basics"}, {"type": "paragraph", "text": "Dimensional lumber often uses nominal names such as 2×4. A typical surfaced 2×4 has actual dimensions of about 1.5 by 3.5 inches, but product standards and local stock must be checked."}, {"type": "heading", "text": "Check before recommending"}, {"type": "paragraph", "text": "Length is another dimension and should be confirmed separately. Sheet goods also have thickness and size labels. Do not confuse nominal thickness with actual thickness."}, {"type": "heading", "text": "Put it into practice"}, {"type": "paragraph", "text": "Customers may need exact finished dimensions for cabinetry or other close-fitting projects. Encourage measuring and checking the actual product."}, {"type": "paragraph", "text": "Hardware-store example: A customer wants a board exactly two inches thick. Explain that a typical surfaced 2×4 is not two inches thick and help check the actual size."}, {"type": "paragraph", "text": "What to say or do: Say: “That is the nominal size. Let’s verify the actual dimensions for your project.”"}, {"type": "paragraph", "text": "Common mistakes: Promising a nominal 2×4 measures exactly 2 by 4 inches."}, {"type": "paragraph", "text": "When to ask for help: Escalate precision, engineered materials, and structural sizing questions."}, {"type": "heading", "text": "Key takeaways:"}, {"type": "bullet", "text": "Dimensional lumber often uses nominal names such as 2×4."}, {"type": "bullet", "text": "Length is another dimension and should be confirmed separately."}, {"type": "bullet", "text": "Customers may need exact finished dimensions for cabinetry or other close-fitting projects."}, {"type": "paragraph", "text": "Unscored practice HB-104-P02: What is the typical actual thickness of a surfaced nominal 2×4?"}, {"type": "bullet", "text": "A. 2 inches"}, {"type": "bullet", "text": "B. 1.5 inches"}, {"type": "bullet", "text": "C. 4 inches"}, {"type": "bullet", "text": "D. 0.5 inch"}, {"type": "paragraph", "text": "Answer: B. Explanation: A typical surfaced nominal 2×4 is about 1.5 inches thick; verify local product specifications."}]}, {"id": "67f3746c-f0c9-5c56-aaee-37f5e0388eee", "position": 3, "title": "Match Material to Environment", "body": [{"type": "paragraph", "text": "Why this matters: Moisture and ground contact can change material requirements."}, {"type": "heading", "text": "Know the basics"}, {"type": "paragraph", "text": "Pressure-treated lumber is made for specific exposure conditions. Not all treated boards are rated for ground contact. The treatment label describes permitted uses and may identify fastener compatibility needs."}, {"type": "heading", "text": "Check before recommending"}, {"type": "paragraph", "text": "Exterior-rated and interior-only sheet goods also differ. Paint or a protective coating does not automatically make an interior-only material suitable outdoors."}, {"type": "heading", "text": "Put it into practice"}, {"type": "paragraph", "text": "Ask whether the material will touch soil, be exposed to rain, or remain dry. Confirm product markings and applicable building requirements."}, {"type": "paragraph", "text": "Hardware-store example: A customer needs lumber for a raised garden bed. Ask about soil contact and read the treatment label rather than assuming every treated board is the same."}, {"type": "paragraph", "text": "What to say or do: Say: “Let’s check whether this material is labeled for the exposure you described.”"}, {"type": "paragraph", "text": "Common mistakes: Assuming any pressure-treated board is ground-contact rated."}, {"type": "paragraph", "text": "When to ask for help: Escalate structural outdoor projects, unusual exposure, and compatibility with fasteners."}, {"type": "heading", "text": "Key takeaways:"}, {"type": "bullet", "text": "Pressure-treated lumber is made for specific exposure conditions."}, {"type": "bullet", "text": "Exterior-rated and interior-only sheet goods also differ."}, {"type": "bullet", "text": "Ask whether the material will touch soil, be exposed to rain, or remain dry."}, {"type": "paragraph", "text": "Unscored practice HB-104-P03: What should determine whether treated lumber is suitable for ground contact?"}, {"type": "bullet", "text": "A. Board color alone"}, {"type": "bullet", "text": "B. Treatment use-category labeling"}, {"type": "bullet", "text": "C. Price alone"}, {"type": "bullet", "text": "D. How smooth it feels"}, {"type": "paragraph", "text": "Answer: B. Explanation: The treatment label identifies the intended exposure conditions."}]}, {"id": "63267936-13ff-552f-9e0f-b0830d5fa4c8", "position": 4, "title": "Identify Basic Building Materials", "body": [{"type": "paragraph", "text": "Why this matters: A complete project may involve more than lumber."}, {"type": "heading", "text": "Know the basics"}, {"type": "paragraph", "text": "Building material aisles may include drywall, cement board, insulation, masonry products, adhesives, and sealants. Each category has a different purpose."}, {"type": "heading", "text": "Check before recommending"}, {"type": "paragraph", "text": "Drywall is commonly used for interior wall surfaces. Cement board may serve as a substrate in specified tile assemblies. Insulation products vary by type and application."}, {"type": "heading", "text": "Put it into practice"}, {"type": "paragraph", "text": "Manufacturer instructions and local codes govern installation and suitability. Do not substitute one material for another based only on appearance or price."}, {"type": "paragraph", "text": "Hardware-store example: A customer asks for a board behind shower tile. Ask for the planned assembly and direct them to the approved system instructions rather than recommending ordinary drywall."}, {"type": "paragraph", "text": "What to say or do: Say: “The wall system matters. Let’s check the installation requirements for that application.”"}, {"type": "paragraph", "text": "Common mistakes: Treating drywall and cement board as equivalent in wet areas."}, {"type": "paragraph", "text": "When to ask for help: Escalate fire ratings, waterproofing, insulation requirements, and structural assemblies."}, {"type": "heading", "text": "Key takeaways:"}, {"type": "bullet", "text": "Building material aisles may include drywall, cement board, insulation, masonry products, adhesives, and sealants."}, {"type": "bullet", "text": "Drywall is commonly used for interior wall surfaces."}, {"type": "bullet", "text": "Manufacturer instructions and local codes govern installation and suitability."}, {"type": "paragraph", "text": "Unscored practice HB-104-P04: Why should an associate verify the intended assembly before suggesting a building panel?"}, {"type": "bullet", "text": "A. Panels are always interchangeable"}, {"type": "bullet", "text": "B. Installation and exposure requirements differ"}, {"type": "bullet", "text": "C. Only color matters"}, {"type": "bullet", "text": "D. Every panel is waterproof"}, {"type": "paragraph", "text": "Answer: B. Explanation: Panels have different approved uses and installation requirements."}]}, {"id": "6f1d7bfd-c6e9-55d0-b68e-f271ddf7015e", "position": 5, "title": "Help Customers Plan a Safe Materials Purchase", "body": [{"type": "paragraph", "text": "Why this matters: Good questions prevent wasted trips and unsafe substitutions."}, {"type": "heading", "text": "Know the basics"}, {"type": "paragraph", "text": "Ask for project purpose, dimensions, exposure, finish requirements, and any plans or material lists. Distinguish rough estimates from verified specifications."}, {"type": "heading", "text": "Check before recommending"}, {"type": "paragraph", "text": "You can help count items on a customer-provided list and identify labeled products. Do not invent beam spans, load capacities, structural designs, or building-code approvals."}, {"type": "heading", "text": "Put it into practice"}, {"type": "paragraph", "text": "Large sheet goods and long boards may require safe handling and transport. Follow store procedures for lifting, cutting services, and vehicle loading."}, {"type": "paragraph", "text": "Hardware-store example: A customer building a deck asks which joist size is safe. Explain that structural sizing depends on loads, spans, materials, and code. Offer to help locate items from a verified plan."}, {"type": "paragraph", "text": "What to say or do: Say: “I can help find materials from your approved list. Structural sizing should be confirmed by a qualified professional.”"}, {"type": "paragraph", "text": "Common mistakes: Guessing structural member sizes based on another customer’s project."}, {"type": "paragraph", "text": "When to ask for help: Escalate load-bearing design, cutting equipment, and unsafe loading situations."}, {"type": "heading", "text": "Key takeaways:"}, {"type": "bullet", "text": "Ask for project purpose, dimensions, exposure, finish requirements, and any plans or material lists."}, {"type": "bullet", "text": "You can help count items on a customer-provided list and identify labeled products."}, {"type": "bullet", "text": "Large sheet goods and long boards may require safe handling and transport."}, {"type": "paragraph", "text": "Unscored practice HB-104-P05: What is the safest response to a request for an unverified deck joist size?"}, {"type": "bullet", "text": "A. Guess based on common stock"}, {"type": "bullet", "text": "B. Use the cheapest board"}, {"type": "bullet", "text": "C. Request qualified structural guidance and help with a verified list"}, {"type": "bullet", "text": "D. Promise any treated board will work"}, {"type": "paragraph", "text": "Answer: C. Explanation: Structural sizing requires verified design and code considerations."}]}], "questions": [{"id": "3c13b2ee-1cd4-5bd9-bd3b-e9fd6b2807e7", "position": 1, "prompt": "Which response best follows this lesson when a customer needs help? Situation: A customer asks for “a four-by-eight board.” Ask whether they mean plywood, OSB, or another sheet material and what the project requires.", "options": ["Choose by appearance without checking details.", "Promise compatibility without reading product instructions.", "Ask: “Will this be indoors or outdoors? Is it decorative or part of a structure?”", "Ignore the customer’s application and select a popular item."], "correct_option": 2, "explanation": "Ask: “Will this be indoors or outdoors? Is it decorative or part of a structure?” OSB is manufactured from bonded wood strands. The other choices skip verification or necessary safety checks."}, {"id": "542c9171-938b-500c-b4d2-7617e569ecc0", "position": 2, "prompt": "What is the safest way to confirm the right product? Situation: A customer wants a board exactly two inches thick. Explain that a typical surfaced 2×4 is not two inches thick and help check the actual size.", "options": ["Choose by appearance without checking details.", "Promise compatibility without reading product instructions.", "Ignore the customer’s application and select a popular item.", "Say: “That is the nominal size. Let’s verify the actual dimensions for your project.”"], "correct_option": 3, "explanation": "Say: “That is the nominal size. Let’s verify the actual dimensions for your project.” A typical surfaced nominal 2×4 is about 1.5 inches thick; verify local product specifications. The other choices skip verification or necessary safety checks."}, {"id": "51a616e6-853f-5392-93b7-9e14b793452e", "position": 3, "prompt": "Which approach best avoids a mistaken recommendation? Situation: A customer needs lumber for a raised garden bed. Ask about soil contact and read the treatment label rather than assuming every treated board is the same.", "options": ["Say: “Let’s check whether this material is labeled for the exposure you described.”", "Choose by appearance without checking details.", "Promise compatibility without reading product instructions.", "Ignore the customer’s application and select a popular item."], "correct_option": 0, "explanation": "Say: “Let’s check whether this material is labeled for the exposure you described.” The treatment label identifies the intended exposure conditions. The other choices skip verification or necessary safety checks."}, {"id": "1e2b78da-9086-58ac-9ffc-a6ab5b477018", "position": 4, "prompt": "What should an employee do when product requirements are uncertain? Situation: A customer asks for a board behind shower tile. Ask for the planned assembly and direct them to the approved system instructions rather than recommending ordinary drywall.", "options": ["Choose by appearance without checking details.", "Say: “The wall system matters. Let’s check the installation requirements for that application.”", "Promise compatibility without reading product instructions.", "Ignore the customer’s application and select a popular item."], "correct_option": 1, "explanation": "Say: “The wall system matters. Let’s check the installation requirements for that application.” Panels have different approved uses and installation requirements. The other choices skip verification or necessary safety checks."}, {"id": "36993b9a-5df7-551e-948e-1c0d06549591", "position": 5, "prompt": "Which response best demonstrates responsible customer service? Situation: A customer building a deck asks which joist size is safe. Explain that structural sizing depends on loads, spans, materials, and code. Offer to help locate items from a verified plan.", "options": ["Choose by appearance without checking details.", "Promise compatibility without reading product instructions.", "Say: “I can help find materials from your approved list. Structural sizing should be confirmed by a qualified professional.”", "Ignore the customer’s application and select a popular item."], "correct_option": 2, "explanation": "Say: “I can help find materials from your approved list. Structural sizing should be confirmed by a qualified professional.” Structural sizing requires verified design and code considerations. The other choices skip verification or necessary safety checks."}], "catalog": {"course_code": "HB-104", "skill_level": "foundations", "topics": ["Lumber & Building Materials"], "keywords": ["Recognize Lumber and Sheet Goods", "Understand Nominal and Actual Lumber Sizes", "Match Material to Environment", "Identify Basic Building Materials", "Help Customers Plan a Safe Materials Purchase", "Know the basics", "Check before recommending", "Put it into practice", "Key takeaways:", "HB-104-", "MDF", "OSB", "P01", "P02", "P03", "P04", "P05"], "learning_paths": ["Department Specialist"]}}$coursedata$::jsonb;
 c jsonb; l jsonb; q jsonb; target uuid;
begin
 c := payload->'course'; target := (c->>'id')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('coltrain-course:' || target::text, 0));
 if exists(select 1 from public.training_courses where id=target) then
  if not exists(select 1 from public.training_courses t where t.id=target
   and t.slug=c->>'slug' and t.version=(c->>'version')::integer
   and t.title=c->>'title' and t.description=c->>'description'
   and t.category=c->>'category' and t.passing_percent=(c->>'passing_percent')::integer
   and t.owner_organization_id is null) then
   raise exception 'HB-104 course differs; create a new version rather than overwrite';
  end if;
  if (select count(*) from public.training_lessons where course_id=target) <> jsonb_array_length(payload->'lessons')
   or (select count(*) from public.training_questions where course_id=target) <> jsonb_array_length(payload->'questions') then
   raise exception 'HB-104 content differs; draft import was not changed';
  end if;
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   if not exists(select 1 from public.training_lessons t where t.id=(l->>'id')::uuid
    and t.course_id=target and t.position=(l->>'position')::integer
    and t.title=l->>'title' and t.body=l->'body') then
    raise exception 'HB-104 lesson differs; draft import was not changed';
   end if;
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   if not exists(select 1 from public.training_questions t join private.training_answer_keys k on k.question_id=t.id
    where t.id=(q->>'id')::uuid and t.course_id=target and t.position=(q->>'position')::integer
    and t.prompt=q->>'prompt' and t.options=q->'options'
    and k.correct_option=(q->>'correct_option')::integer and k.explanation=q->>'explanation') then
    raise exception 'HB-104 question differs; draft import was not changed';
   end if;
  end loop;
 else
  insert into public.training_courses(id,slug,version,title,description,category,passing_percent,published)
   values(target,c->>'slug',(c->>'version')::integer,c->>'title',c->>'description',c->>'category',(c->>'passing_percent')::integer,false);
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   insert into public.training_lessons(id,course_id,position,title,body)
    values((l->>'id')::uuid,target,(l->>'position')::integer,l->>'title',l->'body');
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   insert into public.training_questions(id,course_id,position,prompt,options)
    values((q->>'id')::uuid,target,(q->>'position')::integer,q->>'prompt',q->'options');
   insert into private.training_answer_keys(question_id,correct_option,explanation)
    values((q->>'id')::uuid,(q->>'correct_option')::integer,q->>'explanation');
  end loop;
 end if;
 -- Optional metadata: imports remain compatible before the catalog migration.
 if to_regclass('public.training_course_catalog') is not null then
  insert into public.training_course_catalog(course_id,course_code,skill_level,topics,keywords,learning_paths)
  values(target,payload->'catalog'->>'course_code',payload->'catalog'->>'skill_level',
   array(select jsonb_array_elements_text(payload->'catalog'->'topics')),
   array(select jsonb_array_elements_text(payload->'catalog'->'keywords')),
   array(select jsonb_array_elements_text(payload->'catalog'->'learning_paths')))
  on conflict(course_id) do nothing;
 end if;
end;
