do $courseimport$
declare
 payload jsonb := $coursedata${"course": {"id": "dd9e2966-3774-567f-8e22-ba592b95ba4f", "slug": "pd-101-paint-fundamentals", "version": 1, "title": "Paint Fundamentals", "description": "Recognize common paint products, read labels, and guide customers toward an informed paint selection without guessing.", "category": "Paint & Decorating", "passing_percent": 80}, "lessons": [{"id": "601f632f-0e5b-535e-8bec-fdead547d6ca", "position": 1, "title": "Know the Main Coating Types", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Customers may call every can of coating “paint.” The right product depends on the surface and the desired result."}, {"type": "heading", "text": "Paint and primer"}, {"type": "paragraph", "text": "Paint adds color and a protective finish. Primer prepares certain surfaces for a topcoat. Some paints advertise built-in priming features, but that does not mean they replace a separate primer in every situation."}, {"type": "heading", "text": "Stain and clear finishes"}, {"type": "paragraph", "text": "Stain changes the appearance of wood while allowing some grain to show. Clear finishes protect or change the sheen without adding an opaque color. Products vary by intended surface and exposure."}, {"type": "heading", "text": "Start with the project"}, {"type": "paragraph", "text": "Ask what the customer is coating, whether it is indoors or outdoors, and whether the existing surface is bare, painted, or stained. Read the product label before recommending a category."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer asks for “paint” to keep a new wooden bench looking natural. A clear exterior-rated finish or appropriate stain may be closer to the goal than opaque wall paint."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Ask: “Do you want to see the wood grain, or cover it with color?” Then compare only products labeled for that surface and use."}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Treating primer as a finish coat; assuming every clear finish works outdoors."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a paint specialist when the surface or previous coating is unknown, or when product labels conflict."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Paint adds color and a protective finish."}, {"type": "bullet", "text": "Stain changes the appearance of wood while allowing some grain to show."}, {"type": "bullet", "text": "Ask what the customer is coating, whether it is indoors or outdoors, and whether the existing surface is bare, painted, or stained."}, {"type": "heading", "text": "Optional unscored practice"}, {"type": "paragraph", "text": "PD-101-L01-P01. Which product category is most likely to preserve visible wood grain?"}, {"type": "bullet", "text": "A. Opaque wall paint"}, {"type": "bullet", "text": "B. Wood stain or a suitable clear finish"}, {"type": "bullet", "text": "C. Drywall primer"}, {"type": "bullet", "text": "D. Ceiling paint"}, {"type": "paragraph", "text": "Answer: B. A stain or clear finish can preserve the appearance of wood grain. The exact product must be suitable for the project."}]}, {"id": "6c3bbe8e-ae1e-540b-b699-f5c54b15e50d", "position": 2, "title": "Choose Interior or Exterior Products", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Products designed for one setting may not be appropriate for another."}, {"type": "heading", "text": "Location comes first"}, {"type": "paragraph", "text": "Ask whether the surface is indoors, outdoors, or in a special setting such as a porch floor. A covered porch still has temperature and moisture exposure."}, {"type": "heading", "text": "Exposure matters"}, {"type": "paragraph", "text": "Sunlight, moisture, foot traffic, and frequent cleaning affect the product choice. A wall coating and a floor coating are not interchangeable."}, {"type": "heading", "text": "Use label language"}, {"type": "paragraph", "text": "Look for the approved surfaces and uses on the label. Never promise weather resistance, washability, or durability beyond the product instructions."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer wants leftover interior wall paint for outdoor shutters. You explain that exterior exposure calls for a coating labeled for that use."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Ask: “Where is the surface, and what will it be exposed to?” Show the intended-use section on the can."}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Assuming all paint works on all surfaces; treating a covered outdoor space as indoor."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Escalate unusual substrates, high moisture, or coatings with special handling instructions."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Ask whether the surface is indoors, outdoors, or in a special setting such as a porch floor."}, {"type": "bullet", "text": "Sunlight, moisture, foot traffic, and frequent cleaning affect the product choice."}, {"type": "bullet", "text": "Look for the approved surfaces and uses on the label."}, {"type": "heading", "text": "Optional unscored practice"}, {"type": "paragraph", "text": "PD-101-L02-P01. A customer is painting an exterior door. What should you check first?"}, {"type": "bullet", "text": "A. The most popular color"}, {"type": "bullet", "text": "B. The intended-use label for exterior doors and the door material"}, {"type": "bullet", "text": "C. The largest container"}, {"type": "bullet", "text": "D. The lowest sheen"}, {"type": "paragraph", "text": "Answer: B. Confirm the product is labeled for the surface and exposure before discussing appearance."}]}, {"id": "56719a49-e489-5994-81f6-64b02bff0387", "position": 3, "title": "Understand Paint Sheen", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Sheen changes how a painted surface looks and how visible surface flaws may appear."}, {"type": "heading", "text": "Sheen is the finish appearance"}, {"type": "paragraph", "text": "Flat and matte finishes reflect less light. Eggshell and satin show more reflection. Semi-gloss and gloss reflect more light."}, {"type": "heading", "text": "Compare tradeoffs"}, {"type": "paragraph", "text": "Higher-sheen finishes may make surface imperfections more noticeable. Cleaning performance varies by product formulation, not just sheen."}, {"type": "heading", "text": "Match the room and preference"}, {"type": "paragraph", "text": "Ask about lighting, surface condition, traffic, and desired look. Use the actual product sample and label rather than assuming every brand performs alike."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer wants a low-shine bedroom wall but also asks about cleaning marks. You compare the manufacturer’s available finishes and washability information."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Say: “Let’s compare the look and the cleaning claims on these two specific products.”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Claiming that every satin paint is washable; recommending gloss without asking about wall condition."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Seek help if a customer needs specialized scrubbability, commercial, or moisture-performance claims."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Flat and matte finishes reflect less light."}, {"type": "bullet", "text": "Higher-sheen finishes may make surface imperfections more noticeable."}, {"type": "bullet", "text": "Ask about lighting, surface condition, traffic, and desired look."}, {"type": "heading", "text": "Optional unscored practice"}, {"type": "paragraph", "text": "PD-101-L03-P01. What is the best way to explain sheen?"}, {"type": "bullet", "text": "A. All sheens clean equally"}, {"type": "bullet", "text": "B. Sheen changes light reflection; performance also depends on the product"}, {"type": "bullet", "text": "C. Gloss hides every flaw"}, {"type": "bullet", "text": "D. Flat is always best for kitchens"}, {"type": "paragraph", "text": "Answer: B. Sheen affects appearance. Product-specific claims determine cleaning and durability."}]}, {"id": "5d495cb2-1e8a-5302-88d8-19b161eb9f0e", "position": 4, "title": "Read the Paint Can", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "A product label is more reliable than memory when requirements vary."}, {"type": "heading", "text": "Look for intended surfaces"}, {"type": "paragraph", "text": "Check approved substrates, interior or exterior use, and any exclusions."}, {"type": "heading", "text": "Find preparation and application directions"}, {"type": "paragraph", "text": "Labels may specify cleaning, sanding, priming, application temperature, dry time, recoat time, and ventilation. Follow the specific product instructions."}, {"type": "heading", "text": "Know the difference between dry and recoat"}, {"type": "paragraph", "text": "Dry-to-touch does not necessarily mean ready for another coat, washing, or heavy use. Explain the exact label timing."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer wants to repaint a table tonight and use it tomorrow morning. You check the label for recoat and return-to-service guidance instead of guessing."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Point to the label section that supports your answer. If the directions are unclear, consult the manufacturer’s technical data."}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Making up cure times; overlooking ventilation and surface restrictions."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Escalate questions about hazardous coatings, old coatings of unknown origin, or unusual application conditions."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Check approved substrates, interior or exterior use, and any exclusions."}, {"type": "bullet", "text": "Labels may specify cleaning, sanding, priming, application temperature, dry time, recoat time, and ventilation."}, {"type": "bullet", "text": "Dry-to-touch does not necessarily mean ready for another coat, washing, or heavy use."}, {"type": "heading", "text": "Optional unscored practice"}, {"type": "paragraph", "text": "PD-101-L04-P01. Which statement is safest when a customer asks when they can use a painted surface?"}, {"type": "bullet", "text": "A. All paint cures overnight"}, {"type": "bullet", "text": "B. Dry-to-touch means fully cured"}, {"type": "bullet", "text": "C. Check the specific product’s use and cure guidance"}, {"type": "bullet", "text": "D. Always wait exactly one hour"}, {"type": "paragraph", "text": "Answer: C. Drying, recoating, and full use may have different timing requirements."}]}, {"id": "a66cd935-d17f-52c9-a961-30c1710ef64f", "position": 5, "title": "Ask the Right Paint Questions", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "A few clear questions prevent a wrong purchase and unnecessary returns."}, {"type": "heading", "text": "Five questions"}, {"type": "paragraph", "text": "Ask: What surface? Indoors or outdoors? Existing finish and condition? Desired appearance? How will the surface be used?"}, {"type": "heading", "text": "Do not skip preparation"}, {"type": "paragraph", "text": "Peeling paint, dirt, grease, and damp surfaces can affect results. Customers may need cleaning, repairs, or a separate primer."}, {"type": "heading", "text": "Confirm before checkout"}, {"type": "paragraph", "text": "Repeat the project and product choice. Identify supplies that are genuinely needed, without pressuring the customer."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer says, “I need a gallon of white paint.” You learn it is for a stained exterior railing and pause to check preparation and product compatibility."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Say: “Before we choose the can, can I ask what you are painting and what is on it now?”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Selecting only by color; assuming the customer knows the existing finish."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask for assistance with lead-paint concerns, mold, major moisture problems, or unfamiliar coating systems."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Ask: What surface? Indoors or outdoors? Existing finish and condition? Desired appearance? How will the surface be used?."}, {"type": "bullet", "text": "Peeling paint, dirt, grease, and damp surfaces can affect results."}, {"type": "bullet", "text": "Repeat the project and product choice."}, {"type": "heading", "text": "Optional unscored practice"}, {"type": "paragraph", "text": "PD-101-L05-P01. What should happen before choosing paint based only on color?"}, {"type": "bullet", "text": "A. Ask about surface, location, condition, and use"}, {"type": "bullet", "text": "B. Pick the highest-price paint"}, {"type": "bullet", "text": "C. Assume the surface is drywall"}, {"type": "bullet", "text": "D. Skip preparation questions"}, {"type": "paragraph", "text": "Answer: A. A short project assessment helps select an appropriate coating and preparation steps."}]}], "questions": [{"id": "bf2d1e7b-d59c-5c72-ad01-49b6faf4c71d", "position": 1, "prompt": "A customer wants to keep the wood grain visible on an outdoor bench. What should you do first?", "options": ["Recommend interior wall paint", "Ask about exposure and compare suitable exterior-rated stains or clear finishes", "Recommend primer as the final coat", "Choose by color alone"], "correct_option": 1, "explanation": "A stain or clear finish can preserve the appearance of wood grain. The exact product must be suitable for the project."}, {"id": "45d1cf03-554c-57ec-b6e1-580f1036fd05", "position": 2, "prompt": "A customer wants to use interior paint on an exterior door. What is the best response?", "options": ["Approve it because the door is covered", "Check a product labeled for the door material and exterior exposure", "Suggest any gloss paint", "Tell them all paint is weatherproof"], "correct_option": 1, "explanation": "Confirm the product is labeled for the surface and exposure before discussing appearance."}, {"id": "9c177006-fc0c-5bda-b2d4-82adbd0486dc", "position": 3, "prompt": "Which statement about sheen is most accurate?", "options": ["Gloss always hides imperfections", "All satin products have identical washability", "Sheen changes reflected light; cleaning claims depend on the product", "Flat finishes always clean best"], "correct_option": 2, "explanation": "Sheen affects appearance. Product-specific claims determine cleaning and durability."}, {"id": "b1e8c0e3-92a9-55ad-b35b-a14486a9a7ed", "position": 4, "prompt": "A customer asks when a newly painted table can be used. What should you check?", "options": ["Only the dry-to-touch time", "The product’s recoat and return-to-service instructions", "The container size", "A universal 24-hour rule"], "correct_option": 1, "explanation": "Drying, recoating, and full use may have different timing requirements."}, {"id": "3fa82b90-1529-5170-a902-e3f24206aa81", "position": 5, "prompt": "What is the strongest first step when a customer asks for white paint?", "options": ["Choose the most popular can", "Ask about surface, location, condition, and use", "Sell a gallon immediately", "Skip the existing finish question"], "correct_option": 1, "explanation": "A short project assessment helps select an appropriate coating and preparation steps."}], "catalog": {"course_code": "PD-101", "skill_level": "foundations", "topics": ["Paint"], "keywords": ["Know the Main Coating Types", "Choose Interior or Exterior Products", "Understand Paint Sheen", "Read the Paint Can", "Ask the Right Paint Questions", "Why this matters", "Paint and primer", "Stain and clear finishes", "Start with the project", "Hardware-store example", "What to say or do", "Common mistakes", "When to ask for help", "Key takeaways", "Optional unscored practice", "Location comes first", "Exposure matters", "Use label language", "Sheen is the finish appearance", "Compare tradeoffs", "Match the room and preference", "Look for intended surfaces", "Find preparation and application directions", "Know the difference between dry and recoat", "Five questions", "Do not skip preparation", "Confirm before checkout", "L01-P01", "L02-P01", "L03-P01", "L04-P01", "L05-P01", "PD-101-"], "learning_paths": ["Department Specialist"]}}$coursedata$::jsonb;
 c jsonb; l jsonb; q jsonb; target uuid;
begin
 c := payload->'course'; target := (c->>'id')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('coltrain-course:' || target::text, 0));
 if exists(select 1 from public.training_courses where id=target) then
  if not exists(select 1 from public.training_courses t where t.id=target
   and t.slug=c->>'slug' and t.version=(c->>'version')::integer
   and t.title=c->>'title' and t.description=c->>'description'
   and t.category=c->>'category' and t.passing_percent=(c->>'passing_percent')::integer
   and t.owner_organization_id is null) then
   raise exception 'PD-101 course differs; create a new version rather than overwrite';
  end if;
  if (select count(*) from public.training_lessons where course_id=target) <> jsonb_array_length(payload->'lessons')
   or (select count(*) from public.training_questions where course_id=target) <> jsonb_array_length(payload->'questions') then
   raise exception 'PD-101 content differs; draft import was not changed';
  end if;
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   if not exists(select 1 from public.training_lessons t where t.id=(l->>'id')::uuid
    and t.course_id=target and t.position=(l->>'position')::integer
    and t.title=l->>'title' and t.body=l->'body') then
    raise exception 'PD-101 lesson differs; draft import was not changed';
   end if;
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   if not exists(select 1 from public.training_questions t join private.training_answer_keys k on k.question_id=t.id
    where t.id=(q->>'id')::uuid and t.course_id=target and t.position=(q->>'position')::integer
    and t.prompt=q->>'prompt' and t.options=q->'options'
    and k.correct_option=(q->>'correct_option')::integer and k.explanation=q->>'explanation') then
    raise exception 'PD-101 question differs; draft import was not changed';
   end if;
  end loop;
 else
  insert into public.training_courses(id,slug,version,title,description,category,passing_percent,published)
   values(target,c->>'slug',(c->>'version')::integer,c->>'title',c->>'description',c->>'category',(c->>'passing_percent')::integer,false);
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   insert into public.training_lessons(id,course_id,position,title,body)
    values((l->>'id')::uuid,target,(l->>'position')::integer,l->>'title',l->'body');
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   insert into public.training_questions(id,course_id,position,prompt,options)
    values((q->>'id')::uuid,target,(q->>'position')::integer,q->>'prompt',q->'options');
   insert into private.training_answer_keys(question_id,correct_option,explanation)
    values((q->>'id')::uuid,(q->>'correct_option')::integer,q->>'explanation');
  end loop;
 end if;
 -- Optional metadata: imports remain compatible before the catalog migration.
 if to_regclass('public.training_course_catalog') is not null then
  insert into public.training_course_catalog(course_id,course_code,skill_level,topics,keywords,learning_paths)
  values(target,payload->'catalog'->>'course_code',payload->'catalog'->>'skill_level',
   array(select jsonb_array_elements_text(payload->'catalog'->'topics')),
   array(select jsonb_array_elements_text(payload->'catalog'->'keywords')),
   array(select jsonb_array_elements_text(payload->'catalog'->'learning_paths')))
  on conflict(course_id) do nothing;
 end if;
end;
$courseimport$;
do $courseimport$
declare
 payload jsonb := $coursedata${"course": {"id": "29b6998d-8c0d-52fd-a62b-881dbbee91fc", "slug": "pd-102-paint-sales-customer-consultation", "version": 1, "title": "Paint Sales & Customer Consultation", "description": "Guide a customer from a paint project question to a practical product-and-supplies plan.", "category": "Paint & Decorating", "passing_percent": 80}, "lessons": [{"id": "36ba4311-c592-5e1d-bbe4-dabe8acb73b7", "position": 1, "title": "Discover the Project Before the Product", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "The customer may ask for a specific product before describing the actual job."}, {"type": "heading", "text": "Begin with the surface"}, {"type": "paragraph", "text": "Ask what is being painted, whether it is new or previously coated, and whether it is indoors or outdoors."}, {"type": "heading", "text": "Understand the result"}, {"type": "paragraph", "text": "Ask what matters most: appearance, cleaning, exposure, timing, or budget. Do not assume the most expensive option is best."}, {"type": "heading", "text": "Confirm constraints"}, {"type": "paragraph", "text": "Find out whether the customer has tools, how soon the area must be used, and whether there are damaged or damp surfaces."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer requests “bathroom paint.” You learn the issue is recurring moisture and peeling. You avoid promising paint alone will fix the cause."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Ask: “What is happening on the wall now, and has the moisture problem been addressed?”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Starting with price; recommending a coating before asking about surface condition."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Refer unresolved moisture, suspected mold, or unknown previous coatings to appropriate help."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Ask what is being painted, whether it is new or previously coated, and whether it is indoors or outdoors."}, {"type": "bullet", "text": "Ask what matters most: appearance, cleaning, exposure, timing, or budget."}, {"type": "bullet", "text": "Find out whether the customer has tools, how soon the area must be used, and whether there are damaged or damp surfaces."}, {"type": "heading", "text": "Optional unscored practice"}, {"type": "paragraph", "text": "PD-102-L01-P01. Which question is the strongest opening?"}, {"type": "bullet", "text": "A. How much do you want to spend?"}, {"type": "bullet", "text": "B. What surface are you painting and what is on it now?"}, {"type": "bullet", "text": "C. Would you like our most expensive paint?"}, {"type": "bullet", "text": "D. Do you want two gallons?"}, {"type": "paragraph", "text": "Answer: B. The surface and current condition determine the useful next questions."}]}, {"id": "01751abe-b612-5ab5-9a0d-d6261f8bc88a", "position": 2, "title": "Estimate Paint Quantities Responsibly", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Too little paint delays a project. Too much may create unnecessary expense."}, {"type": "heading", "text": "Measure the area"}, {"type": "paragraph", "text": "For a rectangular wall, multiply width by height to estimate square footage. Add wall areas for the full project. Openings can be accounted for when practical."}, {"type": "heading", "text": "Check product coverage"}, {"type": "paragraph", "text": "Use the coverage range printed on the chosen product or its official calculator. Surface texture, porosity, application method, and number of coats affect the result."}, {"type": "heading", "text": "Explain the estimate"}, {"type": "paragraph", "text": "A coverage figure is an estimate, not a promise. Round purchases based on available container sizes and the customer’s project needs."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer has two walls measuring 10 feet wide by 8 feet high. You calculate 160 square feet before considering doors, windows, and coats. You then check the selected product’s coverage."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Say: “This is the wall area. Let’s check this paint’s stated coverage and the number of coats your project needs.”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Using one universal coverage rate; forgetting multiple coats; guaranteeing the estimate."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a specialist for unusual textures, spray application, or large commercial estimates."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "For a rectangular wall, multiply width by height to estimate square footage."}, {"type": "bullet", "text": "Use the coverage range printed on the chosen product or its official calculator."}, {"type": "bullet", "text": "A coverage figure is an estimate, not a promise."}, {"type": "heading", "text": "Optional unscored practice"}, {"type": "paragraph", "text": "PD-102-L02-P01. Two 10-by-8-foot walls have what combined area before openings?"}, {"type": "bullet", "text": "A. 80 sq ft"}, {"type": "bullet", "text": "B. 100 sq ft"}, {"type": "bullet", "text": "C. 160 sq ft"}, {"type": "bullet", "text": "D. 200 sq ft"}, {"type": "paragraph", "text": "Answer: C. Each wall is 10 × 8 = 80 square feet. Two walls total 160 square feet."}]}, {"id": "9af4cd6f-7c7d-54af-89b1-d061c4c45878", "position": 3, "title": "Compare Paint Options Without Pressure", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Customers benefit from a clear explanation of value, not a sales pitch."}, {"type": "heading", "text": "Compare relevant features"}, {"type": "paragraph", "text": "Review intended use, sheen options, preparation requirements, coverage, and manufacturer-stated performance."}, {"type": "heading", "text": "Explain price in context"}, {"type": "paragraph", "text": "A lower shelf price may not reflect the full project cost if preparation or extra coats differ. Do not promise fewer coats unless the specific product supports that claim."}, {"type": "heading", "text": "Offer a choice"}, {"type": "paragraph", "text": "Present two appropriate options and explain a meaningful difference. Let the customer decide."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer is repainting a high-traffic hallway. You compare two suitable wall paints using their published cleaning guidance and prices."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Say: “Both are labeled for interior walls. This one has a different cleaning claim. Would you like to compare the label details?”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Calling one product “best” without context; inventing durability claims."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Escalate warranty, special-use, and performance claims you cannot verify."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Review intended use, sheen options, preparation requirements, coverage, and manufacturer-stated performance."}, {"type": "bullet", "text": "A lower shelf price may not reflect the full project cost if preparation or extra coats differ."}, {"type": "bullet", "text": "Present two appropriate options and explain a meaningful difference."}, {"type": "heading", "text": "Optional unscored practice"}, {"type": "paragraph", "text": "PD-102-L03-P01. What makes a responsible product comparison?"}, {"type": "bullet", "text": "A. A claim that expensive paint is always better"}, {"type": "bullet", "text": "B. A comparison based on customer needs and verified product information"}, {"type": "bullet", "text": "C. A promise of no future touch-ups"}, {"type": "bullet", "text": "D. A guarantee that one coat always works"}, {"type": "paragraph", "text": "Answer: B. Use the customer’s project and the selected products’ documented claims."}]}, {"id": "6496d694-2844-59d4-a509-7872891fc6ef", "position": 4, "title": "Build the Right Supply List", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "A good sale helps the customer complete the project without avoidable return trips."}, {"type": "heading", "text": "Think through the steps"}, {"type": "paragraph", "text": "Consider cleaning, repairs, masking, protecting nearby surfaces, priming if needed, applying, and cleaning up."}, {"type": "heading", "text": "Match tools to the task"}, {"type": "paragraph", "text": "Brushes, rollers, trays, extension poles, drop cloths, tape, and abrasives vary by job. Use the coating label for compatible applicators."}, {"type": "heading", "text": "Recommend, do not bundle blindly"}, {"type": "paragraph", "text": "Explain why each item may be useful. Check what the customer already owns."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer buys paint for a small bedroom and already owns a roller frame. You ask whether they have the right cover, a tray, a brush for edges, and surface protection."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Say: “What tools do you already have? We can fill in only what is missing.”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Adding unrelated items; forgetting cleanup or surface protection."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask for help with specialty coatings, spray equipment, or respiratory protection requirements."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Consider cleaning, repairs, masking, protecting nearby surfaces, priming if needed, applying, and cleaning up."}, {"type": "bullet", "text": "Brushes, rollers, trays, extension poles, drop cloths, tape, and abrasives vary by job."}, {"type": "bullet", "text": "Explain why each item may be useful."}, {"type": "heading", "text": "Optional unscored practice"}, {"type": "paragraph", "text": "PD-102-L04-P01. What is the best way to recommend add-on supplies?"}, {"type": "bullet", "text": "A. Include every accessory in the department"}, {"type": "bullet", "text": "B. Ask what the customer has and explain supplies needed for the steps"}, {"type": "bullet", "text": "C. Avoid discussing preparation"}, {"type": "bullet", "text": "D. Sell only the paint"}, {"type": "paragraph", "text": "Answer: B. Relevant supplies support project success; unnecessary items do not."}]}, {"id": "40c445da-ac87-5ada-a432-bf23e2109826", "position": 5, "title": "Close with a Project Recap", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "A clear final recap reduces confusion after the customer gets home."}, {"type": "heading", "text": "Repeat the plan"}, {"type": "paragraph", "text": "Summarize the surface, selected product, estimated quantity, key preparation, and application guidance."}, {"type": "heading", "text": "Point to trusted instructions"}, {"type": "paragraph", "text": "Show the label or official technical guidance for timing, ventilation, and cleanup. Do not replace those instructions with guesses."}, {"type": "heading", "text": "Invite follow-up"}, {"type": "paragraph", "text": "Tell the customer how to get more help if an unexpected condition appears before application."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer chooses paint for a previously painted door. You recap cleaning, checking for damage, label-based prep, and appropriate application tools."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Say: “Before you go, here is what we selected and what the label says to do first.”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Ending immediately after payment; promising a specific finish result."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Escalate if the customer describes bubbling, widespread peeling, or unexplained dampness."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Summarize the surface, selected product, estimated quantity, key preparation, and application guidance."}, {"type": "bullet", "text": "Show the label or official technical guidance for timing, ventilation, and cleanup."}, {"type": "bullet", "text": "Tell the customer how to get more help if an unexpected condition appears before application."}, {"type": "heading", "text": "Optional unscored practice"}, {"type": "paragraph", "text": "PD-102-L05-P01. What is the strongest final step in a paint consultation?"}, {"type": "bullet", "text": "A. Guarantee the result"}, {"type": "bullet", "text": "B. Review the plan and point out product instructions"}, {"type": "bullet", "text": "C. Add more products without asking"}, {"type": "bullet", "text": "D. Tell the customer to search online"}, {"type": "paragraph", "text": "Answer: B. A recap helps the customer understand the purchase and the next steps."}]}], "questions": [{"id": "39ffd389-3370-57f3-a7f2-921aeea515be", "position": 1, "prompt": "A customer requests paint for a peeling bathroom wall. What is the best first action?", "options": ["Offer the most expensive can", "Ask about surface condition and moisture before selecting a coating", "Promise paint will stop moisture", "Recommend gloss without questions"], "correct_option": 1, "explanation": "The surface and current condition determine the useful next questions."}, {"id": "79bcd886-cf56-56dc-8dc3-2ed332fffce1", "position": 2, "prompt": "Two walls are each 10 feet by 8 feet. What is their combined area before openings?", "options": ["80 square feet", "120 square feet", "160 square feet", "200 square feet"], "correct_option": 2, "explanation": "Each wall is 10 × 8 = 80 square feet. Two walls total 160 square feet."}, {"id": "fd19c39a-e3bc-5f6e-b359-521319fed11e", "position": 3, "prompt": "Which is the most responsible way to compare two paints?", "options": ["Say the costliest always lasts longest", "Use the customer’s priorities and verified product claims", "Guarantee one coat", "Ignore the surface"], "correct_option": 1, "explanation": "Use the customer’s project and the selected products’ documented claims."}, {"id": "5a33c605-e79b-50ff-b84c-0efd6eae3979", "position": 4, "prompt": "A customer already owns a roller frame. How should you discuss accessories?", "options": ["Sell a second frame anyway", "Ask what else they own and identify supplies needed for the project", "Add every accessory", "Avoid preparation questions"], "correct_option": 1, "explanation": "Relevant supplies support project success; unnecessary items do not."}, {"id": "c6590755-44df-5307-9a0e-e46c47471bdb", "position": 5, "prompt": "Before the customer leaves, what should the associate do?", "options": ["Guarantee the outcome", "Recap the selected product, preparation, and label directions", "Change the product without asking", "Skip instructions"], "correct_option": 1, "explanation": "A recap helps the customer understand the purchase and the next steps."}], "catalog": {"course_code": "PD-102", "skill_level": "foundations", "topics": ["Paint Sales & Customer Consultation"], "keywords": ["Discover the Project Before the Product", "Estimate Paint Quantities Responsibly", "Compare Paint Options Without Pressure", "Build the Right Supply List", "Close with a Project Recap", "Why this matters", "Begin with the surface", "Understand the result", "Confirm constraints", "Hardware-store example", "What to say or do", "Common mistakes", "When to ask for help", "Key takeaways", "Optional unscored practice", "Measure the area", "Check product coverage", "Explain the estimate", "Compare relevant features", "Explain price in context", "Offer a choice", "Think through the steps", "Match tools to the task", "Recommend, do not bundle blindly", "Repeat the plan", "Point to trusted instructions", "Invite follow-up", "L01-P01", "L02-P01", "L03-P01", "L04-P01", "L05-P01", "PD-102-"], "learning_paths": ["Department Specialist"]}}$coursedata$::jsonb;
 c jsonb; l jsonb; q jsonb; target uuid;
begin
 c := payload->'course'; target := (c->>'id')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('coltrain-course:' || target::text, 0));
 if exists(select 1 from public.training_courses where id=target) then
  if not exists(select 1 from public.training_courses t where t.id=target
   and t.slug=c->>'slug' and t.version=(c->>'version')::integer
   and t.title=c->>'title' and t.description=c->>'description'
   and t.category=c->>'category' and t.passing_percent=(c->>'passing_percent')::integer
   and t.owner_organization_id is null) then
   raise exception 'PD-102 course differs; create a new version rather than overwrite';
  end if;
  if (select count(*) from public.training_lessons where course_id=target) <> jsonb_array_length(payload->'lessons')
   or (select count(*) from public.training_questions where course_id=target) <> jsonb_array_length(payload->'questions') then
   raise exception 'PD-102 content differs; draft import was not changed';
  end if;
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   if not exists(select 1 from public.training_lessons t where t.id=(l->>'id')::uuid
    and t.course_id=target and t.position=(l->>'position')::integer
    and t.title=l->>'title' and t.body=l->'body') then
    raise exception 'PD-102 lesson differs; draft import was not changed';
   end if;
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   if not exists(select 1 from public.training_questions t join private.training_answer_keys k on k.question_id=t.id
    where t.id=(q->>'id')::uuid and t.course_id=target and t.position=(q->>'position')::integer
    and t.prompt=q->>'prompt' and t.options=q->'options'
    and k.correct_option=(q->>'correct_option')::integer and k.explanation=q->>'explanation') then
    raise exception 'PD-102 question differs; draft import was not changed';
   end if;
  end loop;
 else
  insert into public.training_courses(id,slug,version,title,description,category,passing_percent,published)
   values(target,c->>'slug',(c->>'version')::integer,c->>'title',c->>'description',c->>'category',(c->>'passing_percent')::integer,false);
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   insert into public.training_lessons(id,course_id,position,title,body)
    values((l->>'id')::uuid,target,(l->>'position')::integer,l->>'title',l->'body');
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   insert into public.training_questions(id,course_id,position,prompt,options)
    values((q->>'id')::uuid,target,(q->>'position')::integer,q->>'prompt',q->'options');
   insert into private.training_answer_keys(question_id,correct_option,explanation)
    values((q->>'id')::uuid,(q->>'correct_option')::integer,q->>'explanation');
  end loop;
 end if;
 -- Optional metadata: imports remain compatible before the catalog migration.
 if to_regclass('public.training_course_catalog') is not null then
  insert into public.training_course_catalog(course_id,course_code,skill_level,topics,keywords,learning_paths)
  values(target,payload->'catalog'->>'course_code',payload->'catalog'->>'skill_level',
   array(select jsonb_array_elements_text(payload->'catalog'->'topics')),
   array(select jsonb_array_elements_text(payload->'catalog'->'keywords')),
   array(select jsonb_array_elements_text(payload->'catalog'->'learning_paths')))
  on conflict(course_id) do nothing;
 end if;
end;
$courseimport$;
do $courseimport$
declare
 payload jsonb := $coursedata${"course": {"id": "f8a15599-d0cc-55dc-82fd-db01b5fb85aa", "slug": "pd-103-surface-preparation-painting-tools", "version": 1, "title": "Surface Preparation & Painting Tools", "description": "Identify common preparation steps and application tools so customers can prepare and paint more effectively.", "category": "Paint & Decorating", "passing_percent": 80}, "lessons": [{"id": "c09d9908-f25c-57c2-895a-d57f22fc1f72", "position": 1, "title": "Start with a Clean, Sound Surface", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Even a good coating can fail when the surface is dirty, loose, or wet."}, {"type": "heading", "text": "Inspect before coating"}, {"type": "paragraph", "text": "Look for dust, grease, loose paint, damaged areas, and moisture. The customer should identify and correct underlying problems before painting."}, {"type": "heading", "text": "Clean as directed"}, {"type": "paragraph", "text": "Cleaning methods vary by surface and coating. Use manufacturer instructions and allow required drying time."}, {"type": "heading", "text": "Do not paint over a problem"}, {"type": "paragraph", "text": "Paint is not a fix for leaks, structural damage, or active mold. Old coatings may need special precautions."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer wants to paint over peeling paint on a damp wall. You recommend investigating the moisture cause before buying a new topcoat."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Ask: “Is the wall dry now, and do you know why the paint is peeling?”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Assuming primer solves moisture; coating over loose material."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Escalate suspected lead paint, mold, persistent dampness, and structural damage. Do not advise disturbing unknown older coatings."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Look for dust, grease, loose paint, damaged areas, and moisture."}, {"type": "bullet", "text": "Cleaning methods vary by surface and coating."}, {"type": "bullet", "text": "Paint is not a fix for leaks, structural damage, or active mold."}, {"type": "heading", "text": "Optional unscored practice"}, {"type": "paragraph", "text": "PD-103-L01-P01. What should happen when paint is peeling because a wall stays damp?"}, {"type": "bullet", "text": "A. Paint immediately"}, {"type": "bullet", "text": "B. Cover it with another coat"}, {"type": "bullet", "text": "C. Address the moisture and loose coating before repainting"}, {"type": "bullet", "text": "D. Use a larger roller"}, {"type": "paragraph", "text": "Answer: C. The underlying condition must be addressed before repainting."}]}, {"id": "b42007b4-b1f2-594f-8c6b-33ab980955af", "position": 2, "title": "Understand Patching and Sanding", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Small defects may need repair before the final finish is applied."}, {"type": "heading", "text": "Match repair material to damage"}, {"type": "paragraph", "text": "Spackling products, fillers, and patch materials have different intended uses. Confirm the surface, depth, and manufacturer directions."}, {"type": "heading", "text": "Sanding has a purpose"}, {"type": "paragraph", "text": "Sanding can smooth a repair or prepare a surface when the coating instructions call for it. Grit numbers indicate abrasive coarseness; lower numbers are generally coarser."}, {"type": "heading", "text": "Control dust and exposure"}, {"type": "paragraph", "text": "Follow product safety instructions. Do not recommend sanding suspected lead-containing paint or unknown hazardous coatings."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer has a small nail hole in painted drywall. You help them locate a patching product labeled for small interior wall repairs and the recommended finishing supplies."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Say: “How large is the hole, and is the surface drywall, wood, or something else?”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Using wood filler for every wall repair; recommending sanding without checking hazards."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask for help with large cracks, water damage, structural issues, or suspected lead coatings."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Spackling products, fillers, and patch materials have different intended uses."}, {"type": "bullet", "text": "Sanding can smooth a repair or prepare a surface when the coating instructions call for it."}, {"type": "bullet", "text": "Follow product safety instructions."}, {"type": "heading", "text": "Optional unscored practice"}, {"type": "paragraph", "text": "PD-103-L02-P01. Why ask about the surface before selecting filler?"}, {"type": "bullet", "text": "A. All fillers are identical"}, {"type": "bullet", "text": "B. Repair materials are intended for different surfaces and defects"}, {"type": "bullet", "text": "C. Filler is only for outdoor work"}, {"type": "bullet", "text": "D. Sanding replaces filler"}, {"type": "paragraph", "text": "Answer: B. Surface type and damage size guide the repair product choice."}]}, {"id": "05af2b3f-8dd6-5cd9-b5f0-4848cac24a75", "position": 3, "title": "Mask and Protect the Work Area", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Preparation saves cleanup time and protects the customer’s belongings."}, {"type": "heading", "text": "Cover what should not be painted"}, {"type": "paragraph", "text": "Drop cloths and protective coverings help protect floors, furniture, and fixtures. Select materials suitable for the location."}, {"type": "heading", "text": "Use tape correctly"}, {"type": "paragraph", "text": "Painter’s tapes differ in surface compatibility and removal timing. Check the package instructions; some delicate surfaces need special care."}, {"type": "heading", "text": "Plan safe access"}, {"type": "paragraph", "text": "Use appropriate access equipment and follow its instructions. Do not suggest unsafe ladder setups or work near electrical hazards."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer plans to paint trim beside a finished wood floor. You discuss floor protection and tape labeled for the adjoining surfaces."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Ask: “What surfaces need protection, and are any freshly painted or delicate?”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Using any tape on any surface; forgetting floor protection."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Escalate high work areas, damaged ladders, or work around exposed wiring."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Drop cloths and protective coverings help protect floors, furniture, and fixtures."}, {"type": "bullet", "text": "Painter’s tapes differ in surface compatibility and removal timing."}, {"type": "bullet", "text": "Use appropriate access equipment and follow its instructions."}, {"type": "heading", "text": "Optional unscored practice"}, {"type": "paragraph", "text": "PD-103-L03-P01. Why check painter’s tape packaging?"}, {"type": "bullet", "text": "A. Tape color predicts the finish"}, {"type": "bullet", "text": "B. Surface compatibility and removal directions vary"}, {"type": "bullet", "text": "C. All tapes can stay on indefinitely"}, {"type": "bullet", "text": "D. Tape replaces surface cleaning"}, {"type": "paragraph", "text": "Answer: B. Tape selection and removal should follow the product instructions."}]}, {"id": "43fd5442-5723-56d4-b52c-1a47bc8e0fc7", "position": 4, "title": "Select Brushes and Rollers", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "The right tool makes application easier and can improve consistency."}, {"type": "heading", "text": "Brushes for control"}, {"type": "paragraph", "text": "Brushes are useful for edges, trim, and smaller areas. Bristle material and shape should match the coating and task per product guidance."}, {"type": "heading", "text": "Rollers for broad areas"}, {"type": "paragraph", "text": "Roller cover nap, material, and width affect application. Textured surfaces may need a different cover than smooth walls."}, {"type": "heading", "text": "Accessories matter"}, {"type": "paragraph", "text": "Trays, grids, extension poles, and compatible applicators support the job. Always check the coating label for recommended tools."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer is painting a smooth interior wall and rough masonry. You explain why the same roller cover may not be ideal for both."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Say: “Is the surface smooth or textured? Let’s check the paint’s recommended applicator.”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Assuming one roller works everywhere; choosing only by price."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a specialist about specialty coatings, spraying, or incompatible applicator materials."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Brushes are useful for edges, trim, and smaller areas."}, {"type": "bullet", "text": "Roller cover nap, material, and width affect application."}, {"type": "bullet", "text": "Trays, grids, extension poles, and compatible applicators support the job."}, {"type": "heading", "text": "Optional unscored practice"}, {"type": "paragraph", "text": "PD-103-L04-P01. What is a useful factor when choosing a roller cover?"}, {"type": "bullet", "text": "A. Only the color of the handle"}, {"type": "bullet", "text": "B. Surface texture and coating directions"}, {"type": "bullet", "text": "C. The largest package"}, {"type": "bullet", "text": "D. The brand name alone"}, {"type": "paragraph", "text": "Answer: B. Surface texture and product directions guide roller-cover choice."}]}, {"id": "36afa483-e0b1-59af-8bfa-8db8c9535477", "position": 5, "title": "Plan Application and Cleanup", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "The project continues after the first coat is applied."}, {"type": "heading", "text": "Follow application conditions"}, {"type": "paragraph", "text": "Product directions may set temperature, humidity, ventilation, and recoating requirements. Check them rather than using a universal rule."}, {"type": "heading", "text": "Separate recoat from full use"}, {"type": "paragraph", "text": "A surface may be ready for another coat before it is ready for cleaning or heavy use."}, {"type": "heading", "text": "Clean up by product instructions"}, {"type": "paragraph", "text": "Water-based and solvent-based products can require different cleanup and disposal practices. Follow the label and local disposal rules; never advise pouring leftover coatings or solvents into drains."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer asks whether they can wash a newly painted wall tomorrow. You check the specific paint’s return-to-service and cleaning guidance."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Say: “Let’s read this product’s instructions for recoating, cleaning, and disposal.”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Guessing dry times; suggesting disposal down a sink; ignoring ventilation."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Escalate solvent hazards, spray applications, disposal uncertainty, or symptoms from exposure."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Product directions may set temperature, humidity, ventilation, and recoating requirements."}, {"type": "bullet", "text": "A surface may be ready for another coat before it is ready for cleaning or heavy use."}, {"type": "bullet", "text": "Water-based and solvent-based products can require different cleanup and disposal practices."}, {"type": "heading", "text": "Optional unscored practice"}, {"type": "paragraph", "text": "PD-103-L05-P01. What is the best cleanup advice?"}, {"type": "bullet", "text": "A. Pour unused paint down the drain"}, {"type": "bullet", "text": "B. Use one method for all coatings"}, {"type": "bullet", "text": "C. Follow the product label and local disposal requirements"}, {"type": "bullet", "text": "D. Store solvent near a heater"}, {"type": "paragraph", "text": "Answer: C. Cleanup and disposal depend on the coating and local rules."}]}], "questions": [{"id": "a96b1ecd-bc42-55fa-b8bf-2b2b397d006c", "position": 1, "prompt": "A wall is damp and peeling. What should happen before repainting?", "options": ["Apply another topcoat", "Cover with tape", "Investigate and address moisture and loose material", "Use a larger brush"], "correct_option": 2, "explanation": "The underlying condition must be addressed before repainting."}, {"id": "98949f34-e346-506c-a172-f8c75d482d76", "position": 2, "prompt": "Why ask whether a hole is in drywall or wood?", "options": ["All fillers work on everything", "Repair materials have different intended uses", "Wood never needs repair", "The surface does not matter"], "correct_option": 1, "explanation": "Surface type and damage size guide the repair product choice."}, {"id": "c5ec6bcf-ff5c-5da3-a602-863646f28623", "position": 3, "prompt": "Why should an associate check the painter’s tape label?", "options": ["Color determines performance", "Surface compatibility and removal timing vary", "All tape is permanent", "Tape replaces cleaning"], "correct_option": 1, "explanation": "Tape selection and removal should follow the product instructions."}, {"id": "33e2084d-eee7-56a2-a4c6-845828266a22", "position": 4, "prompt": "A customer paints smooth drywall and rough masonry. What affects roller-cover selection?", "options": ["Handle color", "Surface texture and coating directions", "Package artwork", "Shelf position"], "correct_option": 1, "explanation": "Surface texture and product directions guide roller-cover choice."}, {"id": "878c0515-8372-5d9d-b160-99ab2d9119fb", "position": 5, "prompt": "A customer asks how to dispose of leftover coating. What should the associate do?", "options": ["Recommend pouring it into a drain", "Follow product instructions and local disposal requirements", "Say all paint can go in household trash", "Recommend mixing with solvent"], "correct_option": 1, "explanation": "Cleanup and disposal depend on the coating and local rules."}], "catalog": {"course_code": "PD-103", "skill_level": "foundations", "topics": ["Surface Preparation & Painting Tools"], "keywords": ["Start with a Clean, Sound Surface", "Understand Patching and Sanding", "Mask and Protect the Work Area", "Select Brushes and Rollers", "Plan Application and Cleanup", "Why this matters", "Inspect before coating", "Clean as directed", "Do not paint over a problem", "Hardware-store example", "What to say or do", "Common mistakes", "When to ask for help", "Key takeaways", "Optional unscored practice", "Match repair material to damage", "Sanding has a purpose", "Control dust and exposure", "Cover what should not be painted", "Use tape correctly", "Plan safe access", "Brushes for control", "Rollers for broad areas", "Accessories matter", "Follow application conditions", "Separate recoat from full use", "Clean up by product instructions", "L01-P01", "L02-P01", "L03-P01", "L04-P01", "L05-P01", "PD-103-"], "learning_paths": ["Department Specialist"]}}$coursedata$::jsonb;
 c jsonb; l jsonb; q jsonb; target uuid;
begin
 c := payload->'course'; target := (c->>'id')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('coltrain-course:' || target::text, 0));
 if exists(select 1 from public.training_courses where id=target) then
  if not exists(select 1 from public.training_courses t where t.id=target
   and t.slug=c->>'slug' and t.version=(c->>'version')::integer
   and t.title=c->>'title' and t.description=c->>'description'
   and t.category=c->>'category' and t.passing_percent=(c->>'passing_percent')::integer
   and t.owner_organization_id is null) then
   raise exception 'PD-103 course differs; create a new version rather than overwrite';
  end if;
  if (select count(*) from public.training_lessons where course_id=target) <> jsonb_array_length(payload->'lessons')
   or (select count(*) from public.training_questions where course_id=target) <> jsonb_array_length(payload->'questions') then
   raise exception 'PD-103 content differs; draft import was not changed';
  end if;
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   if not exists(select 1 from public.training_lessons t where t.id=(l->>'id')::uuid
    and t.course_id=target and t.position=(l->>'position')::integer
    and t.title=l->>'title' and t.body=l->'body') then
    raise exception 'PD-103 lesson differs; draft import was not changed';
   end if;
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   if not exists(select 1 from public.training_questions t join private.training_answer_keys k on k.question_id=t.id
    where t.id=(q->>'id')::uuid and t.course_id=target and t.position=(q->>'position')::integer
    and t.prompt=q->>'prompt' and t.options=q->'options'
    and k.correct_option=(q->>'correct_option')::integer and k.explanation=q->>'explanation') then
    raise exception 'PD-103 question differs; draft import was not changed';
   end if;
  end loop;
 else
  insert into public.training_courses(id,slug,version,title,description,category,passing_percent,published)
   values(target,c->>'slug',(c->>'version')::integer,c->>'title',c->>'description',c->>'category',(c->>'passing_percent')::integer,false);
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   insert into public.training_lessons(id,course_id,position,title,body)
    values((l->>'id')::uuid,target,(l->>'position')::integer,l->>'title',l->'body');
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   insert into public.training_questions(id,course_id,position,prompt,options)
    values((q->>'id')::uuid,target,(q->>'position')::integer,q->>'prompt',q->'options');
   insert into private.training_answer_keys(question_id,correct_option,explanation)
    values((q->>'id')::uuid,(q->>'correct_option')::integer,q->>'explanation');
  end loop;
 end if;
 -- Optional metadata: imports remain compatible before the catalog migration.
 if to_regclass('public.training_course_catalog') is not null then
  insert into public.training_course_catalog(course_id,course_code,skill_level,topics,keywords,learning_paths)
  values(target,payload->'catalog'->>'course_code',payload->'catalog'->>'skill_level',
   array(select jsonb_array_elements_text(payload->'catalog'->'topics')),
   array(select jsonb_array_elements_text(payload->'catalog'->'keywords')),
   array(select jsonb_array_elements_text(payload->'catalog'->'learning_paths')))
  on conflict(course_id) do nothing;
 end if;
end;
