declare
 payload jsonb := $coursedata${"course": {"id": "b278715e-e454-5f4a-bfb7-fa2dd7dee8ee", "slug": "lg-102-outdoor-power-equipment-fundamentals", "version": 1, "title": "Outdoor Power Equipment Fundamentals", "description": "Recognize common outdoor power equipment, gather customer needs, compare power sources, and use manufacturer guidance for safe product consultation.", "category": "Lawn, Garden & Outdoor Power", "passing_percent": 80}, "lessons": [{"id": "37b9f6f6-8965-519e-aba9-c27c4dc76dbc", "position": 1, "title": "Recognize Common Outdoor Power Equipment", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "A customer may know the task but not the tool name."}, {"type": "heading", "text": "Equipment families"}, {"type": "paragraph", "text": "Mowers cut grass. String trimmers cut grass near obstacles. Edgers define edges. Blowers move loose debris. Hedge trimmers shape hedges. Chainsaws cut wood within their intended use."}, {"type": "heading", "text": "Ask about the job"}, {"type": "paragraph", "text": "Find out the material, area size, terrain, and frequency of use. A tool built for a small residential task may not suit a large property or heavy use."}, {"type": "heading", "text": "Respect operating limits"}, {"type": "paragraph", "text": "Every machine has intended uses and restrictions. Do not suggest removing guards, defeating safety devices, or using attachments the manufacturer has not approved."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer says they need something to clear grass around fence posts. Ask whether they mean grass trimming or edging before showing options."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Ask: “What are you cutting, and where will you use the machine?”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Recommending a chainsaw for trimming grass; confusing a string trimmer with a hedge trimmer."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Refer unclear or hazardous cutting tasks to an experienced equipment specialist."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Mowers cut grass."}, {"type": "bullet", "text": "Find out the material, area size, terrain, and frequency of use."}, {"type": "bullet", "text": "Every machine has intended uses and restrictions."}, {"type": "heading", "text": "Optional unscored practice"}, {"type": "paragraph", "text": "LG-102-L01-P01. Which machine is designed mainly to trim grass around obstacles?"}, {"type": "bullet", "text": "A. String trimmer"}, {"type": "bullet", "text": "B. Hedge trimmer"}, {"type": "bullet", "text": "C. Leaf blower"}, {"type": "bullet", "text": "D. Pressure washer"}, {"type": "paragraph", "text": "Answer: A. A string trimmer is commonly used for grass near obstacles."}]}, {"id": "8808db49-2565-5e30-a0fc-473518fedf84", "position": 2, "title": "Compare Battery, Corded, and Engine Power", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Power source affects convenience, runtime, noise, upkeep, and where equipment can be used."}, {"type": "heading", "text": "Battery equipment"}, {"type": "paragraph", "text": "Battery tools need a compatible battery and charger. Runtime depends on the model, battery, workload, and conditions. Batteries are not necessarily interchangeable between brands or systems."}, {"type": "heading", "text": "Corded equipment"}, {"type": "paragraph", "text": "Corded tools require a suitable electrical supply and properly rated cords when allowed by the manufacturer. The cord limits range and introduces trip and damage hazards."}, {"type": "heading", "text": "Engine equipment"}, {"type": "paragraph", "text": "Gasoline-powered equipment has fuel, exhaust, noise, and maintenance requirements. Never operate combustion-engine equipment indoors or in enclosed spaces due to carbon monoxide risk."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer wants a blower for a small patio and asks if any battery will fit. Explain that compatibility must be verified for the specific tool system."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Say: “Let’s check the model, compatible battery, and expected use.”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Claiming every battery fits every tool; promising a fixed runtime for all conditions."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a specialist about battery compatibility, charging faults, fuel requirements, or electrical supply questions."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Battery tools need a compatible battery and charger."}, {"type": "bullet", "text": "Corded tools require a suitable electrical supply and properly rated cords when allowed by the manufacturer."}, {"type": "bullet", "text": "Gasoline-powered equipment has fuel, exhaust, noise, and maintenance requirements."}, {"type": "heading", "text": "Optional unscored practice"}, {"type": "paragraph", "text": "LG-102-L02-P01. What should you verify when selling a cordless trimmer?"}, {"type": "bullet", "text": "A. Only the handle color"}, {"type": "bullet", "text": "B. Battery and charger compatibility"}, {"type": "bullet", "text": "C. Whether any battery fits"}, {"type": "bullet", "text": "D. The longest advertised runtime as a guarantee"}, {"type": "paragraph", "text": "Answer: B. Battery and charger compatibility depends on the equipment system."}]}, {"id": "3d557051-1d2f-5b4a-8b48-952acea494dc", "position": 3, "title": "Match Equipment to the Customer’s Property", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "The wrong size or feature set can make a job difficult or unsafe."}, {"type": "heading", "text": "Measure the job"}, {"type": "paragraph", "text": "Ask about property size, slope, obstacles, storage space, and how often the equipment will be used. Avoid promising that one machine suits every yard."}, {"type": "heading", "text": "Compare relevant features"}, {"type": "paragraph", "text": "For mowers, compare cutting width and manufacturer-approved terrain limitations. For blowers, look at the published performance specifications and intended application. For saws, do not treat bar length alone as a measure of safe capability."}, {"type": "heading", "text": "Confirm accessories"}, {"type": "paragraph", "text": "Check which batteries, chargers, cutting attachments, protective equipment, and replacement parts are included or sold separately. Use the manufacturer’s compatibility list."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer wants a mower for a sloped yard. Ask about the slope and compare only models whose manuals support the intended conditions."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Ask: “How large is the area? Is it flat or sloped? Are there gates or tight spaces?”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Choosing by horsepower or price alone; ignoring slope limitations and included accessories."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Escalate steep terrain, large trees, overhead hazards, and unclear equipment limits."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Ask about property size, slope, obstacles, storage space, and how often the equipment will be used."}, {"type": "bullet", "text": "For mowers, compare cutting width and manufacturer-approved terrain limitations."}, {"type": "bullet", "text": "Check which batteries, chargers, cutting attachments, protective equipment, and replacement parts are included or sold separately."}, {"type": "heading", "text": "Optional unscored practice"}, {"type": "paragraph", "text": "LG-102-L03-P01. What matters when a customer has a steep yard?"}, {"type": "bullet", "text": "A. Only the mower color"}, {"type": "bullet", "text": "B. Manufacturer terrain limits and property conditions"}, {"type": "bullet", "text": "C. The biggest mower available"}, {"type": "bullet", "text": "D. The lowest price"}, {"type": "paragraph", "text": "Answer: B. Terrain and model-specific operating limits are essential."}]}, {"id": "52cfb0f5-884c-5a64-bff9-83fddd28e009", "position": 4, "title": "Explain Maintenance and Storage Safely", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Correct maintenance helps equipment work reliably and prevents avoidable hazards."}, {"type": "heading", "text": "Start with the manual"}, {"type": "paragraph", "text": "Maintenance varies by engine, battery system, and tool model. Refer to the operator manual for cleaning, inspection, service intervals, and approved parts."}, {"type": "heading", "text": "Storage matters"}, {"type": "paragraph", "text": "Customers should follow manufacturer guidance for battery storage, fuel handling, and seasonal storage. Never invent a fuel mix ratio or recommend storing fuel near heat or ignition sources."}, {"type": "heading", "text": "Know your role"}, {"type": "paragraph", "text": "Retail employees may help locate approved parts and manuals. Repairs, blade servicing, and other hazardous work should be handled by trained authorized personnel as appropriate."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer asks what fuel mixture to use in a trimmer. Ask for the exact model and check the manufacturer manual instead of giving a universal ratio."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Say: “Fuel requirements vary. Let’s verify the exact model instructions before you add anything.”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Assuming all two-stroke engines use the same fuel ratio; handling sharp blades without training."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Refer repairs, battery damage, leaking fuel, and complex maintenance to trained service personnel."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Maintenance varies by engine, battery system, and tool model."}, {"type": "bullet", "text": "Customers should follow manufacturer guidance for battery storage, fuel handling, and seasonal storage."}, {"type": "bullet", "text": "Retail employees may help locate approved parts and manuals."}, {"type": "heading", "text": "Optional unscored practice"}, {"type": "paragraph", "text": "LG-102-L04-P01. A customer asks for a fuel mix ratio without a model number. What should you do?"}, {"type": "bullet", "text": "A. Guess a common ratio"}, {"type": "bullet", "text": "B. Check the exact model and manual"}, {"type": "bullet", "text": "C. Tell them all machines use straight gasoline"}, {"type": "bullet", "text": "D. Recommend extra oil"}, {"type": "paragraph", "text": "Answer: B. Fuel requirements vary by model and must be verified."}]}, {"id": "ebf3b1cd-2759-54c2-bfc9-dc97044056c3", "position": 5, "title": "Recognize Equipment Safety and Service Limits", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Outdoor power tools can cause serious injuries when used incorrectly."}, {"type": "heading", "text": "Personal protection"}, {"type": "paragraph", "text": "Manufacturer instructions may require eye, hearing, hand, foot, or other protection depending on the machine. Follow the specific manual and store policy."}, {"type": "heading", "text": "Keep guards in place"}, {"type": "paragraph", "text": "Do not recommend bypassing interlocks, removing guards, using damaged batteries, or operating a tool with a missing safety component."}, {"type": "heading", "text": "Escalate risky work"}, {"type": "paragraph", "text": "Tree work near power lines, damaged electrical equipment, unstable slopes, fuel leaks, and active mechanical faults are not routine retail consultations. Direct customers to qualified professionals and appropriate emergency help when needed."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer asks how to disable a mower safety switch that keeps stopping the engine. Decline to give bypass instructions and refer them to authorized service."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Say: “That safety device must stay functional. Let’s find the approved service option.”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Giving instructions to defeat a guard or switch; offering unverified repair steps."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Escalate immediately when there is leaking fuel, a swollen battery, an electrical hazard, or unsafe cutting conditions."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Manufacturer instructions may require eye, hearing, hand, foot, or other protection depending on the machine."}, {"type": "bullet", "text": "Do not recommend bypassing interlocks, removing guards, using damaged batteries, or operating a tool with a missing safety component."}, {"type": "bullet", "text": "Tree work near power lines, damaged electrical equipment, unstable slopes, fuel leaks, and active mechanical faults are not routine retail consultations."}, {"type": "heading", "text": "Optional unscored practice"}, {"type": "paragraph", "text": "LG-102-L05-P01. A customer asks how to bypass a safety switch. What should you do?"}, {"type": "bullet", "text": "A. Explain how to bypass it"}, {"type": "bullet", "text": "B. Refer to authorized service and keep the safety feature intact"}, {"type": "bullet", "text": "C. Recommend removing the guard"}, {"type": "bullet", "text": "D. Suggest testing while running"}, {"type": "paragraph", "text": "Answer: B. Safety devices should not be defeated; service concerns require qualified support."}]}], "questions": [{"id": "99511734-b91d-5218-97f3-68f7df61233d", "position": 1, "prompt": "Which machine is designed mainly to trim grass around obstacles?", "options": ["String trimmer", "Hedge trimmer", "Leaf blower", "Pressure washer"], "correct_option": 0, "explanation": "A string trimmer is commonly used for grass near obstacles."}, {"id": "30672a5e-ffcb-5829-a9e9-f8b12206fdd9", "position": 2, "prompt": "What should you verify when selling a cordless trimmer?", "options": ["Only the handle color", "Battery and charger compatibility", "Whether any battery fits", "The longest advertised runtime as a guarantee"], "correct_option": 1, "explanation": "Battery and charger compatibility depends on the equipment system."}, {"id": "26bf4696-4128-51c9-b072-42ce1405aa9e", "position": 3, "prompt": "What matters when a customer has a steep yard?", "options": ["Only the mower color", "Manufacturer terrain limits and property conditions", "The biggest mower available", "The lowest price"], "correct_option": 1, "explanation": "Terrain and model-specific operating limits are essential."}, {"id": "a2778989-88c0-5a4a-b1c3-f41bfb7c5875", "position": 4, "prompt": "A customer asks for a fuel mix ratio without a model number. What should you do?", "options": ["Guess a common ratio", "Check the exact model and manual", "Tell them all machines use straight gasoline", "Recommend extra oil"], "correct_option": 1, "explanation": "Fuel requirements vary by model and must be verified."}, {"id": "92f969b6-42fe-5954-bb38-ba8a3ea9e317", "position": 5, "prompt": "A customer asks how to bypass a safety switch. What should you do?", "options": ["Explain how to bypass it", "Refer to authorized service and keep the safety feature intact", "Recommend removing the guard", "Suggest testing while running"], "correct_option": 1, "explanation": "Safety devices should not be defeated; service concerns require qualified support."}], "catalog": {"course_code": "LG-102", "skill_level": "foundations", "topics": ["Outdoor Power Equipment"], "keywords": ["Recognize Common Outdoor Power Equipment", "Compare Battery, Corded, and Engine Power", "Match Equipment to the Customer’s Property", "Explain Maintenance and Storage Safely", "Recognize Equipment Safety and Service Limits", "Why this matters", "Equipment families", "Ask about the job", "Respect operating limits", "Hardware-store example", "What to say or do", "Common mistakes", "When to ask for help", "Key takeaways", "Optional unscored practice", "Battery equipment", "Corded equipment", "Engine equipment", "Measure the job", "Compare relevant features", "Confirm accessories", "Start with the manual", "Storage matters", "Know your role", "Personal protection", "Keep guards in place", "Escalate risky work", "L01-P01", "L02-P01", "L03-P01", "L04-P01", "L05-P01", "LG-102-"], "learning_paths": ["Department Specialist"]}}$coursedata$::jsonb;
 c jsonb; l jsonb; q jsonb; target uuid;
begin
 c := payload->'course'; target := (c->>'id')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('coltrain-course:' || target::text, 0));
 if exists(select 1 from public.training_courses where id=target) then
  if not exists(select 1 from public.training_courses t where t.id=target
   and t.slug=c->>'slug' and t.version=(c->>'version')::integer
   and t.title=c->>'title' and t.description=c->>'description'
   and t.category=c->>'category' and t.passing_percent=(c->>'passing_percent')::integer
   and t.owner_organization_id is null) then
   raise exception 'LG-102 course differs; create a new version rather than overwrite';
  end if;
  if (select count(*) from public.training_lessons where course_id=target) <> jsonb_array_length(payload->'lessons')
   or (select count(*) from public.training_questions where course_id=target) <> jsonb_array_length(payload->'questions') then
   raise exception 'LG-102 content differs; draft import was not changed';
  end if;
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   if not exists(select 1 from public.training_lessons t where t.id=(l->>'id')::uuid
    and t.course_id=target and t.position=(l->>'position')::integer
    and t.title=l->>'title' and t.body=l->'body') then
    raise exception 'LG-102 lesson differs; draft import was not changed';
   end if;
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   if not exists(select 1 from public.training_questions t join private.training_answer_keys k on k.question_id=t.id
    where t.id=(q->>'id')::uuid and t.course_id=target and t.position=(q->>'position')::integer
    and t.prompt=q->>'prompt' and t.options=q->'options'
    and k.correct_option=(q->>'correct_option')::integer and k.explanation=q->>'explanation') then
    raise exception 'LG-102 question differs; draft import was not changed';
   end if;
  end loop;
 else
  insert into public.training_courses(id,slug,version,title,description,category,passing_percent,published)
   values(target,c->>'slug',(c->>'version')::integer,c->>'title',c->>'description',c->>'category',(c->>'passing_percent')::integer,false);
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   insert into public.training_lessons(id,course_id,position,title,body)
    values((l->>'id')::uuid,target,(l->>'position')::integer,l->>'title',l->'body');
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   insert into public.training_questions(id,course_id,position,prompt,options)
    values((q->>'id')::uuid,target,(q->>'position')::integer,q->>'prompt',q->'options');
   insert into private.training_answer_keys(question_id,correct_option,explanation)
    values((q->>'id')::uuid,(q->>'correct_option')::integer,q->>'explanation');
  end loop;
 end if;
 -- Optional metadata: imports remain compatible before the catalog migration.
 if to_regclass('public.training_course_catalog') is not null then
  insert into public.training_course_catalog(course_id,course_code,skill_level,topics,keywords,learning_paths)
  values(target,payload->'catalog'->>'course_code',payload->'catalog'->>'skill_level',
   array(select jsonb_array_elements_text(payload->'catalog'->'topics')),
   array(select jsonb_array_elements_text(payload->'catalog'->'keywords')),
   array(select jsonb_array_elements_text(payload->'catalog'->'learning_paths')))
  on conflict(course_id) do nothing;
 end if;
end;
$courseimport$;
do $courseimport$
declare
 payload jsonb := $coursedata${"course": {"id": "b960cca0-4b26-5787-9bcb-72dedb8256b0", "slug": "bl-101-retail-pricing-fundamentals", "version": 1, "title": "Retail Pricing Fundamentals", "description": "Understand retail price, cost, gross profit, margin, markup, promotions, and responsible price communication.", "category": "Business Operations & Leadership", "passing_percent": 80}, "lessons": [{"id": "7b8d5d65-f631-5143-bbce-93eba70e6d63", "position": 1, "title": "Understand Price, Cost, and Gross Profit", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "A selling price does not tell you how much a store earns."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Start with the selling price"}, {"type": "paragraph", "text": "Retail price is the amount charged to the customer before applicable taxes. Product cost is what the business pays for an item under its accounting method. The two amounts are not the same."}, {"type": "heading", "text": "Calculate gross profit"}, {"type": "paragraph", "text": "For a simple single-item example, gross profit dollars equal selling price minus item cost. A $20 item that costs $12 produces $8 of gross profit before other expenses."}, {"type": "heading", "text": "Know what is missing"}, {"type": "paragraph", "text": "Gross profit is not net profit. Rent, wages, payment fees, freight treatment, shrink, and other expenses affect the business. Stores may account for costs differently."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A manager sees a $20 shelf price and assumes the store earns $20. The item cost is $12, so the simple gross profit is $8, not $20."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Say: “Let’s look at selling price and item cost before discussing profitability.”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Confusing revenue with profit; assuming gross profit pays every expense."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask the owner or finance lead when item costs, freight allocations, or accounting definitions are unclear."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Retail price is the amount charged to the customer before applicable taxes."}, {"type": "bullet", "text": "For a simple single-item example, gross profit dollars equal selling price minus item cost."}, {"type": "bullet", "text": "Gross profit is not net profit."}, {"type": "heading", "text": "Optional practice — unscored"}, {"type": "paragraph", "text": "BL-101-L01-P01: A $20 sale with a $12 item cost has how many dollars of gross profit?"}, {"type": "bullet", "text": "A. $20"}, {"type": "bullet", "text": "B. $12"}, {"type": "bullet", "text": "C. $8"}, {"type": "bullet", "text": "D. $32"}, {"type": "paragraph", "text": "Answer: C. $20 minus $12 equals $8 before other expenses."}]}, {"id": "f972dab6-30d6-5459-b5db-dac450d67d43", "position": 2, "title": "Separate Margin from Markup", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "These percentages look similar but answer different questions."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Gross margin"}, {"type": "paragraph", "text": "Gross margin percentage is gross profit divided by selling price, multiplied by 100. For a $20 sale and $12 cost, $8 ÷ $20 = 40%."}, {"type": "heading", "text": "Markup"}, {"type": "paragraph", "text": "Markup percentage is gross profit divided by cost, multiplied by 100. For the same item, $8 ÷ $12 is about 66.7%."}, {"type": "heading", "text": "Avoid mix-ups"}, {"type": "paragraph", "text": "A 40% margin is not a 40% markup. Verify which measure your POS or report uses before comparing numbers."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A department lead says the item has a 40% markup. You review the $20 price and $12 cost and explain that it has a 40% margin and about a 66.7% markup."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Say: “Margin divides by selling price; markup divides by cost.”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Using cost as the margin denominator; comparing markup with margin reports."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Escalate when reports use different cost definitions or include returns and discounts differently."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Gross margin percentage is gross profit divided by selling price, multiplied by 100."}, {"type": "bullet", "text": "Markup percentage is gross profit divided by cost, multiplied by 100."}, {"type": "bullet", "text": "A 40% margin is not a 40% markup."}, {"type": "heading", "text": "Optional practice — unscored"}, {"type": "paragraph", "text": "BL-101-L02-P01: An item sells for $20 and costs $12. What is its gross margin?"}, {"type": "bullet", "text": "A. 20%"}, {"type": "bullet", "text": "B. 40%"}, {"type": "bullet", "text": "C. 66.7%"}, {"type": "bullet", "text": "D. 80%"}, {"type": "paragraph", "text": "Answer: B. ($20 − $12) ÷ $20 = 40%."}]}, {"id": "6c80c4d3-a3c3-5c9f-a873-62bf035398c8", "position": 3, "title": "See How Discounts Change Profit", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "A small price change can create a large change in gross profit."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Run the numbers"}, {"type": "paragraph", "text": "If an item sells for $20 and costs $12, gross profit is $8. Discount the selling price to $16 and gross profit falls to $4, assuming cost stays the same."}, {"type": "heading", "text": "Look beyond one item"}, {"type": "paragraph", "text": "A promotion may increase unit sales or bring in related purchases. Those results are not guaranteed. Compare sales, gross profit, and the promotion goal."}, {"type": "heading", "text": "Check the full offer"}, {"type": "paragraph", "text": "Coupons, bundles, vendor support, and loyalty discounts may change the effective price or cost. Follow approved promotion rules and confirm the actual terms."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer asks for 20% off a $20 item. You calculate the new price as $16 and recognize that gross profit drops from $8 to $4 at the assumed $12 cost."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Say: “Before approving a discount, I need to check the promotion rules and its impact.”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Treating 20% off as a 20% reduction in profit; promising unapproved discounts."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a manager or pricing owner before overriding prices or stacking offers."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "If an item sells for $20 and costs $12, gross profit is $8."}, {"type": "bullet", "text": "A promotion may increase unit sales or bring in related purchases."}, {"type": "bullet", "text": "Coupons, bundles, vendor support, and loyalty discounts may change the effective price or cost."}, {"type": "heading", "text": "Optional practice — unscored"}, {"type": "paragraph", "text": "BL-101-L03-P01: A $20 item costing $12 is discounted to $16. What is the new gross profit?"}, {"type": "bullet", "text": "A. $8"}, {"type": "bullet", "text": "B. $4"}, {"type": "bullet", "text": "C. $12"}, {"type": "bullet", "text": "D. $16"}, {"type": "paragraph", "text": "Answer: B. $16 minus $12 equals $4."}]}, {"id": "ea0db2fa-a4db-54f5-9494-8bf4a026464c", "position": 4, "title": "Investigate Price Differences", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "A mismatch can frustrate customers and undermine trust."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Check the evidence"}, {"type": "paragraph", "text": "Confirm the product identifier, package size, shelf label, advertised offer, and register entry. Similar-looking items may have different prices."}, {"type": "heading", "text": "Follow store policy"}, {"type": "paragraph", "text": "Do not invent a price-match or adjustment policy. Escalate corrections and customer resolutions to the authorized person."}, {"type": "heading", "text": "Fix the cause"}, {"type": "paragraph", "text": "Once the immediate customer issue is addressed, report the mismatch so the shelf tag, system record, or promotion sign can be corrected."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer points to a $9.99 shelf label, but the register shows $12.99. Verify the SKU and promotion details, then follow the store’s price-discrepancy procedure."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Say: “Thank you for showing me. I’ll check the item and shelf label, then get the right person to resolve it.”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Blaming the customer; changing a price without authority; leaving a wrong shelf tag in place."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Escalate disputed promotions, tax issues, and overrides beyond your authorization."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Confirm the product identifier, package size, shelf label, advertised offer, and register entry."}, {"type": "bullet", "text": "Do not invent a price-match or adjustment policy."}, {"type": "bullet", "text": "Once the immediate customer issue is addressed, report the mismatch so the shelf tag, system record, or promotion sign can be corrected."}, {"type": "heading", "text": "Optional practice — unscored"}, {"type": "paragraph", "text": "BL-101-L04-P01: What should you do first when a shelf price and register price disagree?"}, {"type": "bullet", "text": "A. Assume the register is always right"}, {"type": "bullet", "text": "B. Verify the item and signage, then follow store policy"}, {"type": "bullet", "text": "C. Remove the shelf label without reporting it"}, {"type": "bullet", "text": "D. Promise any price the customer wants"}, {"type": "paragraph", "text": "Answer: B. Verification and approved resolution protect the customer and store."}]}, {"id": "57f9f839-c697-528d-a1e9-9e9a0548ec9f", "position": 5, "title": "Explain Pricing Clearly and Fairly", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Clear pricing builds trust even when customers decide not to buy."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Describe the offer"}, {"type": "paragraph", "text": "State the actual selling price, promotion conditions, quantity limits, and dates when applicable. Verify advertised details before making a claim."}, {"type": "heading", "text": "Discuss value"}, {"type": "paragraph", "text": "Compare useful differences such as pack quantity, durability, included accessories, and warranty terms when supported by the product information."}, {"type": "heading", "text": "Stay within authority"}, {"type": "paragraph", "text": "Do not promise competitor matching, future pricing, tax treatment, or special discounts without confirmation. Avoid claims that an item is “the best” without a clear basis."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer compares two packs of screws. One costs more but contains twice as many pieces. You compare the unit count and price per piece before recommending a choice."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Say: “Let’s compare what is included and the cost per piece.”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Using vague “better quality” claims; omitting offer conditions; making unauthorized promises."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Refer unusual price requests, complaints about advertising, and unclear warranty terms to management."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "State the actual selling price, promotion conditions, quantity limits, and dates when applicable."}, {"type": "bullet", "text": "Compare useful differences such as pack quantity, durability, included accessories, and warranty terms when supported by the product information."}, {"type": "bullet", "text": "Do not promise competitor matching, future pricing, tax treatment, or special discounts without confirmation."}, {"type": "heading", "text": "Optional practice — unscored"}, {"type": "paragraph", "text": "BL-101-L05-P01: What is the best way to explain a two-pack price difference?"}, {"type": "bullet", "text": "A. Focus only on the more expensive sticker"}, {"type": "bullet", "text": "B. Compare quantity, features, and verified terms"}, {"type": "bullet", "text": "C. Promise a discount"}, {"type": "bullet", "text": "D. Say the cheaper product is always worse"}, {"type": "paragraph", "text": "Answer: B. A clear comparison helps customers judge value for their project."}]}], "questions": [{"id": "07348781-7f19-5ccc-a229-7dbc8639b62b", "position": 1, "prompt": "A $20 sale with a $12 item cost has how many dollars of gross profit?", "options": ["$20", "$12", "$8", "$32"], "correct_option": 2, "explanation": "$20 minus $12 equals $8 before other expenses."}, {"id": "e7241607-267c-59d9-bf2f-cde4e0dc5e2a", "position": 2, "prompt": "An item sells for $20 and costs $12. What is its gross margin?", "options": ["20%", "40%", "66.7%", "80%"], "correct_option": 1, "explanation": "($20 − $12) ÷ $20 = 40%."}, {"id": "57a0bf3c-3762-5638-9a88-30a407090c76", "position": 3, "prompt": "A $20 item costing $12 is discounted to $16. What is the new gross profit?", "options": ["$8", "$4", "$12", "$16"], "correct_option": 1, "explanation": "$16 minus $12 equals $4."}, {"id": "c9754f9a-3047-5a38-8ba9-1ba64cb6f197", "position": 4, "prompt": "What should you do first when a shelf price and register price disagree?", "options": ["Assume the register is always right", "Verify the item and signage, then follow store policy", "Remove the shelf label without reporting it", "Promise any price the customer wants"], "correct_option": 1, "explanation": "Verification and approved resolution protect the customer and store."}, {"id": "aeeb02e6-17c6-595f-af42-cbd18de127ad", "position": 5, "prompt": "What is the best way to explain a two-pack price difference?", "options": ["Focus only on the more expensive sticker", "Compare quantity, features, and verified terms", "Promise a discount", "Say the cheaper product is always worse"], "correct_option": 1, "explanation": "A clear comparison helps customers judge value for their project."}], "catalog": {"course_code": "BL-101", "skill_level": "foundations", "topics": ["Retail Pricing"], "keywords": ["Understand Price, Cost, and Gross Profit", "Separate Margin from Markup", "See How Discounts Change Profit", "Investigate Price Differences", "Explain Pricing Clearly and Fairly", "Why this matters", "Lesson content", "Start with the selling price", "Calculate gross profit", "Know what is missing", "Hardware-store example", "What to say or do", "Common mistakes", "When to ask for help", "Key takeaways", "Optional practice — unscored", "Gross margin", "Markup", "Avoid mix-ups", "Run the numbers", "Look beyond one item", "Check the full offer", "Check the evidence", "Follow store policy", "Fix the cause", "Describe the offer", "Discuss value", "Stay within authority", "BL-101-", "L01-P01", "L02-P01", "L03-P01", "L04-P01", "L05-P01", "POS", "SKU"], "learning_paths": ["Department Lead/Supervisor", "Store Manager/Owner"]}}$coursedata$::jsonb;
 c jsonb; l jsonb; q jsonb; target uuid;
begin
 c := payload->'course'; target := (c->>'id')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('coltrain-course:' || target::text, 0));
 if exists(select 1 from public.training_courses where id=target) then
  if not exists(select 1 from public.training_courses t where t.id=target
   and t.slug=c->>'slug' and t.version=(c->>'version')::integer
   and t.title=c->>'title' and t.description=c->>'description'
   and t.category=c->>'category' and t.passing_percent=(c->>'passing_percent')::integer
   and t.owner_organization_id is null) then
   raise exception 'BL-101 course differs; create a new version rather than overwrite';
  end if;
  if (select count(*) from public.training_lessons where course_id=target) <> jsonb_array_length(payload->'lessons')
   or (select count(*) from public.training_questions where course_id=target) <> jsonb_array_length(payload->'questions') then
   raise exception 'BL-101 content differs; draft import was not changed';
  end if;
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   if not exists(select 1 from public.training_lessons t where t.id=(l->>'id')::uuid
    and t.course_id=target and t.position=(l->>'position')::integer
    and t.title=l->>'title' and t.body=l->'body') then
    raise exception 'BL-101 lesson differs; draft import was not changed';
   end if;
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   if not exists(select 1 from public.training_questions t join private.training_answer_keys k on k.question_id=t.id
    where t.id=(q->>'id')::uuid and t.course_id=target and t.position=(q->>'position')::integer
    and t.prompt=q->>'prompt' and t.options=q->'options'
    and k.correct_option=(q->>'correct_option')::integer and k.explanation=q->>'explanation') then
    raise exception 'BL-101 question differs; draft import was not changed';
   end if;
  end loop;
 else
  insert into public.training_courses(id,slug,version,title,description,category,passing_percent,published)
   values(target,c->>'slug',(c->>'version')::integer,c->>'title',c->>'description',c->>'category',(c->>'passing_percent')::integer,false);
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   insert into public.training_lessons(id,course_id,position,title,body)
    values((l->>'id')::uuid,target,(l->>'position')::integer,l->>'title',l->'body');
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   insert into public.training_questions(id,course_id,position,prompt,options)
    values((q->>'id')::uuid,target,(q->>'position')::integer,q->>'prompt',q->'options');
   insert into private.training_answer_keys(question_id,correct_option,explanation)
    values((q->>'id')::uuid,(q->>'correct_option')::integer,q->>'explanation');
  end loop;
 end if;
 -- Optional metadata: imports remain compatible before the catalog migration.
 if to_regclass('public.training_course_catalog') is not null then
  insert into public.training_course_catalog(course_id,course_code,skill_level,topics,keywords,learning_paths)
  values(target,payload->'catalog'->>'course_code',payload->'catalog'->>'skill_level',
   array(select jsonb_array_elements_text(payload->'catalog'->'topics')),
   array(select jsonb_array_elements_text(payload->'catalog'->'keywords')),
   array(select jsonb_array_elements_text(payload->'catalog'->'learning_paths')))
  on conflict(course_id) do nothing;
 end if;
end;
$courseimport$;
do $courseimport$
declare
 payload jsonb := $coursedata${"course": {"id": "36e11a14-abb4-5e23-9946-e55a868b8d09", "slug": "bl-102-leadership-managing-a-retail-team", "version": 1, "title": "Leadership & Managing a Retail Team", "description": "Build foundational skills in expectations, coaching, delegation, scheduling communication, and respectful team leadership.", "category": "Business Operations & Leadership", "passing_percent": 80}, "lessons": [{"id": "b408663c-f2d0-50cb-9c70-86230925fc0f", "position": 1, "title": "Set Clear Expectations", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Employees cannot reliably meet expectations they have not heard or understood."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Make work observable"}, {"type": "paragraph", "text": "Replace “keep the store nice” with specific tasks such as checking shelf labels, removing empty cartons, and clearing aisle hazards."}, {"type": "heading", "text": "Define the standard"}, {"type": "paragraph", "text": "Explain what needs doing, when it is due, and how to know it is complete. Ask employees to repeat the plan in their own words when helpful."}, {"type": "heading", "text": "Keep standards consistent"}, {"type": "paragraph", "text": "Use the same core expectations for similar roles. Adjust tasks for training, ability, accommodation, and authorized responsibilities as appropriate."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "Before opening, a supervisor asks an associate to check the fastener aisle, remove empty packaging, and report missing shelf labels by 9:30."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Say: “Please check the fastener aisle before 9:30 and tell me which labels need replacing.”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Giving vague instructions; assuming understanding; changing priorities without telling the team."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask the store manager or HR contact about accommodations, policy interpretation, or unclear job responsibilities."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Replace “keep the store nice” with specific tasks such as checking shelf labels, removing empty cartons, and clearing aisle hazards."}, {"type": "bullet", "text": "Explain what needs doing, when it is due, and how to know it is complete."}, {"type": "bullet", "text": "Use the same core expectations for similar roles."}, {"type": "heading", "text": "Optional practice — unscored"}, {"type": "paragraph", "text": "BL-102-L01-P01: Which instruction is clearest?"}, {"type": "bullet", "text": "A. Make the store look better"}, {"type": "bullet", "text": "B. Check aisle three for missing shelf labels and report them by 10 a.m."}, {"type": "bullet", "text": "C. Stay busy"}, {"type": "bullet", "text": "D. Do what you think is best"}, {"type": "paragraph", "text": "Answer: B. The instruction identifies the task, location, and deadline."}]}, {"id": "a8db1463-4a9a-56d3-945c-4be2b076d5bc", "position": 2, "title": "Coach in the Moment", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Small corrections made early are easier to act on than vague criticism later."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Describe what happened"}, {"type": "paragraph", "text": "Focus on observable behavior rather than labels about a person. “The customer waited while you searched” is more useful than “You are careless.”"}, {"type": "heading", "text": "Explain the effect"}, {"type": "paragraph", "text": "Connect the behavior to safety, customer experience, or team workflow. Invite the employee to describe what happened."}, {"type": "heading", "text": "Agree on a next step"}, {"type": "paragraph", "text": "Demonstrate the expected action, invite practice, and follow up. Recognize improvement when you see it."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "An employee leaves a customer without explaining they are checking inventory. A supervisor privately models a short update and practices it with the employee."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Say: “When you need to check stock, tell the customer what you are doing and when you’ll return.”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Correcting someone publicly when privacy is possible; making assumptions about intent; offering no next step."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Use established HR procedures for repeated misconduct, discrimination concerns, or serious safety violations."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Focus on observable behavior rather than labels about a person."}, {"type": "bullet", "text": "Connect the behavior to safety, customer experience, or team workflow."}, {"type": "bullet", "text": "Demonstrate the expected action, invite practice, and follow up."}, {"type": "heading", "text": "Optional practice — unscored"}, {"type": "paragraph", "text": "BL-102-L02-P01: Which feedback is most useful?"}, {"type": "bullet", "text": "A. You always do this wrong"}, {"type": "bullet", "text": "B. Next time, tell the customer you are checking stock before you walk away"}, {"type": "bullet", "text": "C. Everyone knows better"}, {"type": "bullet", "text": "D. Try harder"}, {"type": "paragraph", "text": "Answer: B. Specific feedback gives the employee an action to practice."}]}, {"id": "3b30df25-2404-5296-8122-8538c2faa382", "position": 3, "title": "Delegate with Follow-Through", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Delegation creates capacity only when employees have the information and authority to succeed."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Match task and readiness"}, {"type": "paragraph", "text": "Consider training, workload, and safety authorization. Do not delegate regulated or hazardous work to an unqualified employee."}, {"type": "heading", "text": "Clarify the handoff"}, {"type": "paragraph", "text": "State the outcome, deadline, resources, decision limits, and check-in time. Give employees room to complete the task within those boundaries."}, {"type": "heading", "text": "Close the loop"}, {"type": "paragraph", "text": "Review completion, remove obstacles, and recognize progress. Avoid repeatedly taking the task back unless safety or urgency requires it."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A manager delegates an endcap refresh to a trained associate, shares the approved planogram, sets a noon check-in, and identifies who can approve substitutions."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Say: “Use this approved layout. Let me know by noon if an item is unavailable.”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Delegating without a deadline; assigning work without authority; micromanaging every step."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Escalate staffing constraints, restricted equipment use, and decisions outside the employee’s role."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Consider training, workload, and safety authorization."}, {"type": "bullet", "text": "State the outcome, deadline, resources, decision limits, and check-in time."}, {"type": "bullet", "text": "Review completion, remove obstacles, and recognize progress."}, {"type": "heading", "text": "Optional practice — unscored"}, {"type": "paragraph", "text": "BL-102-L03-P01: Which detail belongs in a good delegation handoff?"}, {"type": "bullet", "text": "A. Only the employee’s name"}, {"type": "bullet", "text": "B. Expected result, deadline, resources, and decision limits"}, {"type": "bullet", "text": "C. A reminder to work faster"}, {"type": "bullet", "text": "D. No follow-up plan"}, {"type": "paragraph", "text": "Answer: B. A complete handoff reduces rework and confusion."}]}, {"id": "1ee26854-bcf9-5e3d-87f8-320d92ce7539", "position": 4, "title": "Handle Concerns and Conflict Respectfully", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Unresolved conflict can affect service, safety, and trust."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Listen separately when needed"}, {"type": "paragraph", "text": "Hear each person’s account without assuming who is right. Ask about specific actions and dates, not rumors."}, {"type": "heading", "text": "Use the right channel"}, {"type": "paragraph", "text": "Handle routine task disagreements with coaching. Follow HR and reporting policies for harassment, discrimination, threats, retaliation, or other serious concerns."}, {"type": "heading", "text": "Agree on practical next steps"}, {"type": "paragraph", "text": "Clarify expectations, document as required by policy, and check whether the problem is resolved. Protect confidentiality to the extent appropriate."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "Two associates disagree over who should restock a display. The supervisor reviews assignments and workload, listens to both, and clarifies the next shift’s responsibilities."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Say: “I want to understand what happened and clarify the work so this does not repeat.”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Taking sides before hearing facts; discussing private concerns with unrelated coworkers; ignoring serious reports."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Immediately involve the designated manager or HR contact for threats, harassment, discrimination, or safety risks."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Hear each person’s account without assuming who is right."}, {"type": "bullet", "text": "Handle routine task disagreements with coaching."}, {"type": "bullet", "text": "Clarify expectations, document as required by policy, and check whether the problem is resolved."}, {"type": "heading", "text": "Optional practice — unscored"}, {"type": "paragraph", "text": "BL-102-L04-P01: What should a supervisor do first with a routine task disagreement?"}, {"type": "bullet", "text": "A. Choose the louder employee’s side"}, {"type": "bullet", "text": "B. Hear the facts and clarify expectations"}, {"type": "bullet", "text": "C. Share the story with the team"}, {"type": "bullet", "text": "D. Ignore it indefinitely"}, {"type": "paragraph", "text": "Answer: B. Fact-finding and clear expectations support fair resolution."}]}, {"id": "5276e12c-f92a-52e5-8e66-61821dc8780a", "position": 5, "title": "Lead a Consistent Daily Huddle", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "A few minutes of clear communication can prevent repeated questions and missed tasks."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Start with priorities"}, {"type": "paragraph", "text": "Share the day’s key customer-service goals, deliveries, promotions, and safety reminders. Keep the message short."}, {"type": "heading", "text": "Invite useful questions"}, {"type": "paragraph", "text": "Ask what could block progress and who needs support. Confirm which employee owns each priority."}, {"type": "heading", "text": "Review and adjust"}, {"type": "paragraph", "text": "At the end of the shift, note what was completed and what needs handoff. Do not share confidential employee or customer information in a group huddle."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A morning huddle covers an incoming truck, a weekend paint promotion, and a blocked receiving aisle. The team assigns owners and a check-in time."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Say: “Our priorities are a clear receiving aisle, accurate sale signs, and helping customers quickly. What might get in the way?”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Listing too many priorities; using huddles to embarrass staff; skipping follow-up."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Escalate unsafe conditions, staffing shortages, or unresolved customer issues to the responsible leader."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Share the day’s key customer-service goals, deliveries, promotions, and safety reminders."}, {"type": "bullet", "text": "Ask what could block progress and who needs support."}, {"type": "bullet", "text": "At the end of the shift, note what was completed and what needs handoff."}, {"type": "heading", "text": "Optional practice — unscored"}, {"type": "paragraph", "text": "BL-102-L05-P01: Which is the best daily huddle practice?"}, {"type": "bullet", "text": "A. Discuss private personnel issues in detail"}, {"type": "bullet", "text": "B. Share top priorities, owners, and safety reminders"}, {"type": "bullet", "text": "C. Avoid questions"}, {"type": "bullet", "text": "D. Give every employee ten unrelated goals"}, {"type": "paragraph", "text": "Answer: B. A focused huddle improves alignment without overloading staff."}]}], "questions": [{"id": "10640214-477a-5fe7-8193-354e7823a9c5", "position": 1, "prompt": "Which instruction is clearest?", "options": ["Make the store look better", "Check aisle three for missing shelf labels and report them by 10 a.m.", "Stay busy", "Do what you think is best"], "correct_option": 1, "explanation": "The instruction identifies the task, location, and deadline."}, {"id": "895bd20b-af1a-597f-8a09-3738104e744e", "position": 2, "prompt": "Which feedback is most useful?", "options": ["You always do this wrong", "Next time, tell the customer you are checking stock before you walk away", "Everyone knows better", "Try harder"], "correct_option": 1, "explanation": "Specific feedback gives the employee an action to practice."}, {"id": "4e25e63c-faac-5be1-8119-ab8111e9e509", "position": 3, "prompt": "Which detail belongs in a good delegation handoff?", "options": ["Only the employee’s name", "Expected result, deadline, resources, and decision limits", "A reminder to work faster", "No follow-up plan"], "correct_option": 1, "explanation": "A complete handoff reduces rework and confusion."}, {"id": "05cf3105-207d-527b-94c8-f79a91649ad6", "position": 4, "prompt": "What should a supervisor do first with a routine task disagreement?", "options": ["Choose the louder employee’s side", "Hear the facts and clarify expectations", "Share the story with the team", "Ignore it indefinitely"], "correct_option": 1, "explanation": "Fact-finding and clear expectations support fair resolution."}, {"id": "bf724c34-6ce1-5d5f-a810-45eca6846f73", "position": 5, "prompt": "Which is the best daily huddle practice?", "options": ["Discuss private personnel issues in detail", "Share top priorities, owners, and safety reminders", "Avoid questions", "Give every employee ten unrelated goals"], "correct_option": 1, "explanation": "A focused huddle improves alignment without overloading staff."}], "catalog": {"course_code": "BL-102", "skill_level": "foundations", "topics": ["Leadership & Managing a Retail Team"], "keywords": ["Set Clear Expectations", "Coach in the Moment", "Delegate with Follow-Through", "Handle Concerns and Conflict Respectfully", "Lead a Consistent Daily Huddle", "Why this matters", "Lesson content", "Make work observable", "Define the standard", "Keep standards consistent", "Hardware-store example", "What to say or do", "Common mistakes", "When to ask for help", "Key takeaways", "Optional practice — unscored", "Describe what happened", "Explain the effect", "Agree on a next step", "Match task and readiness", "Clarify the handoff", "Close the loop", "Listen separately when needed", "Use the right channel", "Agree on practical next steps", "Start with priorities", "Invite useful questions", "Review and adjust", "BL-102-", "HR", "L01-P01", "L02-P01", "L03-P01", "L04-P01", "L05-P01"], "learning_paths": ["Department Lead/Supervisor", "Store Manager/Owner"]}}$coursedata$::jsonb;
 c jsonb; l jsonb; q jsonb; target uuid;
begin
 c := payload->'course'; target := (c->>'id')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('coltrain-course:' || target::text, 0));
 if exists(select 1 from public.training_courses where id=target) then
  if not exists(select 1 from public.training_courses t where t.id=target
   and t.slug=c->>'slug' and t.version=(c->>'version')::integer
   and t.title=c->>'title' and t.description=c->>'description'
   and t.category=c->>'category' and t.passing_percent=(c->>'passing_percent')::integer
   and t.owner_organization_id is null) then
   raise exception 'BL-102 course differs; create a new version rather than overwrite';
  end if;
  if (select count(*) from public.training_lessons where course_id=target) <> jsonb_array_length(payload->'lessons')
   or (select count(*) from public.training_questions where course_id=target) <> jsonb_array_length(payload->'questions') then
   raise exception 'BL-102 content differs; draft import was not changed';
  end if;
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   if not exists(select 1 from public.training_lessons t where t.id=(l->>'id')::uuid
    and t.course_id=target and t.position=(l->>'position')::integer
    and t.title=l->>'title' and t.body=l->'body') then
    raise exception 'BL-102 lesson differs; draft import was not changed';
   end if;
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   if not exists(select 1 from public.training_questions t join private.training_answer_keys k on k.question_id=t.id
    where t.id=(q->>'id')::uuid and t.course_id=target and t.position=(q->>'position')::integer
    and t.prompt=q->>'prompt' and t.options=q->'options'
    and k.correct_option=(q->>'correct_option')::integer and k.explanation=q->>'explanation') then
    raise exception 'BL-102 question differs; draft import was not changed';
   end if;
  end loop;
 else
  insert into public.training_courses(id,slug,version,title,description,category,passing_percent,published)
   values(target,c->>'slug',(c->>'version')::integer,c->>'title',c->>'description',c->>'category',(c->>'passing_percent')::integer,false);
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   insert into public.training_lessons(id,course_id,position,title,body)
    values((l->>'id')::uuid,target,(l->>'position')::integer,l->>'title',l->'body');
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   insert into public.training_questions(id,course_id,position,prompt,options)
    values((q->>'id')::uuid,target,(q->>'position')::integer,q->>'prompt',q->'options');
   insert into private.training_answer_keys(question_id,correct_option,explanation)
    values((q->>'id')::uuid,(q->>'correct_option')::integer,q->>'explanation');
  end loop;
 end if;
 -- Optional metadata: imports remain compatible before the catalog migration.
 if to_regclass('public.training_course_catalog') is not null then
  insert into public.training_course_catalog(course_id,course_code,skill_level,topics,keywords,learning_paths)
  values(target,payload->'catalog'->>'course_code',payload->'catalog'->>'skill_level',
   array(select jsonb_array_elements_text(payload->'catalog'->'topics')),
   array(select jsonb_array_elements_text(payload->'catalog'->'keywords')),
   array(select jsonb_array_elements_text(payload->'catalog'->'learning_paths')))
  on conflict(course_id) do nothing;
 end if;
end;
$courseimport$;
do $courseimport$
declare
 payload jsonb := $coursedata${"course": {"id": "a10452d3-d56b-5f78-b0ef-c1a87f2b67fa", "slug": "bl-103-time-management-prioritization", "version": 1, "title": "Time Management & Prioritization", "description": "Prioritize customer needs, safety, assigned work, interruptions, and shift handoffs in a busy hardware store.", "category": "Business Operations & Leadership", "passing_percent": 80}, "lessons": [{"id": "3a3dadd5-d910-5a3c-8a16-9c8b27586152", "position": 1, "title": "Recognize Priorities During a Shift", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Hardware stores have customer questions, deliveries, and planned work happening at the same time."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Safety comes first"}, {"type": "paragraph", "text": "A spill, blocked emergency exit, or other immediate hazard needs prompt action under store procedure. Do not walk past a hazard to finish routine stocking."}, {"type": "heading", "text": "Consider urgency and importance"}, {"type": "paragraph", "text": "An urgent issue needs attention soon. Important work supports service and operations even when no one is asking about it right now."}, {"type": "heading", "text": "Confirm the order"}, {"type": "paragraph", "text": "When priorities compete, tell the manager what is happening and ask which task should come next."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "You are restocking screws when you notice liquid on the floor. Secure the area and follow spill procedures before returning to the shelf."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Say: “I found a spill. I’m following the safety procedure, then I’ll return to stocking.”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Treating the longest task as most important; ignoring hazards; silently dropping assigned work."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask for help with hazardous spills, injuries, or competing demands you cannot resolve safely."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "A spill, blocked emergency exit, or other immediate hazard needs prompt action under store procedure."}, {"type": "bullet", "text": "An urgent issue needs attention soon."}, {"type": "bullet", "text": "When priorities compete, tell the manager what is happening and ask which task should come next."}, {"type": "heading", "text": "Optional practice — unscored"}, {"type": "paragraph", "text": "BL-103-L01-P01: What should take priority over routine stocking?"}, {"type": "bullet", "text": "A. An immediate aisle hazard"}, {"type": "bullet", "text": "B. Straightening a display"}, {"type": "bullet", "text": "C. Counting extra shelf tags"}, {"type": "bullet", "text": "D. Choosing music"}, {"type": "paragraph", "text": "Answer: A. Immediate safety concerns require prompt action under store procedure."}]}, {"id": "4c212de2-6e5f-5b84-b13f-11ab0b0dc07c", "position": 2, "title": "Plan the Next Useful Step", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "A clear next step helps employees start and finish work."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Define the outcome"}, {"type": "paragraph", "text": "Instead of “fix receiving,” identify the specific result, such as sorting today’s delivery into labeled staging areas."}, {"type": "heading", "text": "Break work into steps"}, {"type": "paragraph", "text": "Check instructions, gather supplies, complete one section, and verify the result. Use a short checklist when several details matter."}, {"type": "heading", "text": "Estimate realistically"}, {"type": "paragraph", "text": "Ask about deadlines and available time. Do not promise a completion time without considering interruptions and resources."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "An associate is told to prepare an endcap. They check the approved display plan, gather products and labels, build the display, and request a final check."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Say: “I’ll gather the products and labels first, then set the display and verify the prices.”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Starting without instructions; doing easy tasks instead of required tasks; skipping verification."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a manager when the assignment, display rules, or available time is unclear."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Instead of “fix receiving,” identify the specific result, such as sorting today’s delivery into labeled staging areas."}, {"type": "bullet", "text": "Check instructions, gather supplies, complete one section, and verify the result."}, {"type": "bullet", "text": "Ask about deadlines and available time."}, {"type": "heading", "text": "Optional practice — unscored"}, {"type": "paragraph", "text": "BL-103-L02-P01: What is the best first step for an unfamiliar display assignment?"}, {"type": "bullet", "text": "A. Start placing any nearby products"}, {"type": "bullet", "text": "B. Review the approved plan and needed materials"}, {"type": "bullet", "text": "C. Ignore the deadline"}, {"type": "bullet", "text": "D. Change the prices to match your idea"}, {"type": "paragraph", "text": "Answer: B. A clear plan reduces mistakes and rework."}]}, {"id": "3c02024e-fb33-5bb1-8652-9bd90a727db2", "position": 3, "title": "Handle Interruptions Without Losing Your Place", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Helping a customer should not mean forgetting a half-completed task."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Pause safely"}, {"type": "paragraph", "text": "Put down tools and materials safely. Do not leave sharp objects, unstable stacks, or open cartons where customers could be hurt."}, {"type": "heading", "text": "Capture your place"}, {"type": "paragraph", "text": "Use a permitted checklist or brief note to mark the next step. Never record unnecessary customer personal information."}, {"type": "heading", "text": "Return or hand off"}, {"type": "paragraph", "text": "After helping, resume from the note. If the shift changes or a new priority takes over, tell the next person what remains."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "While checking shelf labels, a customer asks for help finding a faucet connector. You make the area safe, mark the aisle section you were checking, and return after assisting."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Say: “I’m helping this customer. I’ve marked where I stopped so I can finish the label check.”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Leaving trip hazards; relying on memory for many unfinished tasks; refusing reasonable customer help."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a coworker or manager when multiple customers need help or a safety-sensitive task cannot be paused."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Put down tools and materials safely."}, {"type": "bullet", "text": "Use a permitted checklist or brief note to mark the next step."}, {"type": "bullet", "text": "After helping, resume from the note."}, {"type": "heading", "text": "Optional practice — unscored"}, {"type": "paragraph", "text": "BL-103-L03-P01: What should you do before leaving a stocking task to help a customer?"}, {"type": "bullet", "text": "A. Leave an open carton in the aisle"}, {"type": "bullet", "text": "B. Make the area safe and note where to resume"}, {"type": "bullet", "text": "C. Forget the task"}, {"type": "bullet", "text": "D. Move products into an exit path"}, {"type": "paragraph", "text": "Answer: B. A safe pause and clear note protect customers and help you finish later."}]}, {"id": "fbdb7125-f6ee-5337-9dce-26e6da1d0324", "position": 4, "title": "Communicate When Priorities Change", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "A silent change can leave important tasks unfinished."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Give a short update"}, {"type": "paragraph", "text": "State what was planned, what interrupted it, and what remains. Keep the update factual and concise."}, {"type": "heading", "text": "Ask for a decision"}, {"type": "paragraph", "text": "If two tasks cannot both be completed, ask the responsible leader which has priority. Do not guess when a deadline or safety concern matters."}, {"type": "heading", "text": "Use teamwork"}, {"type": "paragraph", "text": "Request a handoff or help when appropriate. Share enough context for the other person to continue without starting over."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A delivery arrives while you are setting a promotional display. You tell the manager the display is half finished and ask whether to help receive the truck."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Say: “The display needs about one more section. The truck is here. Which should I handle first?”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Pretending both tasks are done; changing priorities without notice; blaming others for unclear handoffs."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Escalate missed deadlines, customer commitments, or work requiring special authorization."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "State what was planned, what interrupted it, and what remains."}, {"type": "bullet", "text": "If two tasks cannot both be completed, ask the responsible leader which has priority."}, {"type": "bullet", "text": "Request a handoff or help when appropriate."}, {"type": "heading", "text": "Optional practice — unscored"}, {"type": "paragraph", "text": "BL-103-L04-P01: Which update is most useful?"}, {"type": "bullet", "text": "A. I got busy"}, {"type": "bullet", "text": "B. The display is half complete; the delivery arrived; which task comes first?"}, {"type": "bullet", "text": "C. It is someone else’s problem"}, {"type": "bullet", "text": "D. Nothing changed"}, {"type": "paragraph", "text": "Answer: B. A specific update lets the manager make an informed decision."}]}, {"id": "5b67236a-6827-501d-9986-db3b9dfa8d0b", "position": 5, "title": "Close the Shift with a Useful Handoff", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Good handoffs prevent repeated work and missed customer promises."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Record what is done"}, {"type": "paragraph", "text": "Check off completed tasks and confirm any important results, such as corrected shelf labels or received cartons."}, {"type": "heading", "text": "Name what remains"}, {"type": "paragraph", "text": "List unfinished tasks, location, urgency, and any relevant next step. Follow approved systems and privacy rules."}, {"type": "heading", "text": "Confirm ownership"}, {"type": "paragraph", "text": "Tell the incoming employee or manager who will take the next action. Do not assume a note alone guarantees follow-through."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "At shift change, you report that aisle four is stocked but two labels need printing, and you identify where the label request was saved."}, {"type": "heading", "text": "What to say or do"}, {"type": "paragraph", "text": "Say: “Aisle four is stocked. Two labels are pending in the approved system, and the next shift has the request.”"}, {"type": "heading", "text": "Common mistakes"}, {"type": "paragraph", "text": "Saying only “not done”; leaving customer promises undocumented; sharing private details in open notes."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Escalate urgent safety issues and time-sensitive customer commitments directly, not only in a written note."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Check off completed tasks and confirm any important results, such as corrected shelf labels or received cartons."}, {"type": "bullet", "text": "List unfinished tasks, location, urgency, and any relevant next step."}, {"type": "bullet", "text": "Tell the incoming employee or manager who will take the next action."}, {"type": "heading", "text": "Optional practice — unscored"}, {"type": "paragraph", "text": "BL-103-L05-P01: What belongs in a useful shift handoff?"}, {"type": "bullet", "text": "A. Only a general complaint"}, {"type": "bullet", "text": "B. Completed work, unfinished items, and who owns the next step"}, {"type": "bullet", "text": "C. Private customer details unrelated to the task"}, {"type": "bullet", "text": "D. Nothing if you are tired"}, {"type": "paragraph", "text": "Answer: B. Specific status and ownership help the next shift continue smoothly."}]}], "questions": [{"id": "2201c782-a1ec-5367-b41b-d71a3577d172", "position": 1, "prompt": "What should take priority over routine stocking?", "options": ["An immediate aisle hazard", "Straightening a display", "Counting extra shelf tags", "Choosing music"], "correct_option": 0, "explanation": "Immediate safety concerns require prompt action under store procedure."}, {"id": "33837cd4-5473-5251-866b-629021f60bfb", "position": 2, "prompt": "What is the best first step for an unfamiliar display assignment?", "options": ["Start placing any nearby products", "Review the approved plan and needed materials", "Ignore the deadline", "Change the prices to match your idea"], "correct_option": 1, "explanation": "A clear plan reduces mistakes and rework."}, {"id": "100c8926-4e50-557e-a5c8-5b434ebda8fc", "position": 3, "prompt": "What should you do before leaving a stocking task to help a customer?", "options": ["Leave an open carton in the aisle", "Make the area safe and note where to resume", "Forget the task", "Move products into an exit path"], "correct_option": 1, "explanation": "A safe pause and clear note protect customers and help you finish later."}, {"id": "b6be0d36-c2f3-5829-862a-7fcff25fb7c2", "position": 4, "prompt": "Which update is most useful?", "options": ["I got busy", "The display is half complete; the delivery arrived; which task comes first?", "It is someone else’s problem", "Nothing changed"], "correct_option": 1, "explanation": "A specific update lets the manager make an informed decision."}, {"id": "5a42674b-4713-5fc7-aee5-511b9e4eeece", "position": 5, "prompt": "What belongs in a useful shift handoff?", "options": ["Only a general complaint", "Completed work, unfinished items, and who owns the next step", "Private customer details unrelated to the task", "Nothing if you are tired"], "correct_option": 1, "explanation": "Specific status and ownership help the next shift continue smoothly."}], "catalog": {"course_code": "BL-103", "skill_level": "foundations", "topics": ["Time Management & Prioritization"], "keywords": ["Recognize Priorities During a Shift", "Plan the Next Useful Step", "Handle Interruptions Without Losing Your Place", "Communicate When Priorities Change", "Close the Shift with a Useful Handoff", "Why this matters", "Lesson content", "Safety comes first", "Consider urgency and importance", "Confirm the order", "Hardware-store example", "What to say or do", "Common mistakes", "When to ask for help", "Key takeaways", "Optional practice — unscored", "Define the outcome", "Break work into steps", "Estimate realistically", "Pause safely", "Capture your place", "Return or hand off", "Give a short update", "Ask for a decision", "Use teamwork", "Record what is done", "Name what remains", "Confirm ownership", "BL-103-", "L01-P01", "L02-P01", "L03-P01", "L04-P01", "L05-P01"], "learning_paths": ["Department Lead/Supervisor", "Store Manager/Owner"]}}$coursedata$::jsonb;
